/* 平成15年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h15.committeeSessions.push(...[{"id":"h15-20030303-9","meetingId":"h15-cm03","date":"2003年3月3日","dateIso":"2003-03-03","committee":"文教委員会","time":"午前１０時０３分～午後２時０２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１５年請願第２号、小中一貫校の建設計画を中止し、その費用で３０人以下学級の実現、施設・設備の充実を求める請願","agenda":"平成１５年請願第２号、小中一貫校の建設計画を中止し、その費用で３０人以下学級の実現、施設・設備の充実を求める請願","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"その後の努力と合意形成の現状は、まずどうなっているのか教えていただきたいと思います。","respondent":"指田教育次長","answer":"通学路についても複数案を持ちながらいろいろご協議していきたい、こういうふうな話をしているわけでございまして、これからきちんと丁寧な説明をしていきたい、こういった姿勢に変わりはありません。","voiceIndex":6,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、先日の本会議でも各党、各会派から住民参加をめぐる論議が出されて、区長も答弁をしていますよね。品川区の住民参加というのは、物事を決めてから、決めた方針を上から伝えるだけなんですか。要するに、意思決定過程で住民の声が出てくれば、その声を尊重し、理解を得る努力というのはないんですか、今の答弁から言うと。","respondent":"指田教育次長","answer":"ただ言えますことは、それが全部すべての事案について、すべて区民の声を聞いて全部やるんだというふうな話で、これは仕事を進めていくという考えは持っていたらば、行政は停滞するだけだ、このように考えております。","voiceIndex":8,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"では聞きたいんですが、次長は、昨年の決算特別委員会の、さっき名前が出ましたので、あえて土井委員の質問に対して、このように答弁しているんですね。」ちょっと原文のままですから、言葉はいろいろとありますけれども、きちんと一つ一つお答えをしていくというふうになっているんだけれども、去年のこの陳情が出てから現在までに、どれほどの説明と理解を得る努力をされたんでしょうか。","respondent":"指田教育次長","answer":"したがって、冒頭申し上げましたように、ある程度のものは固まりましたから、本会議終わりました後、あるいは予算委員会が終わった後、丁寧な説明に入っていこう、こういう段取りになっているということです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、一度も説明をやっていないということですか。何回かはやったんでしょうか。今のニュアンスからすると、一度も説明を受けていないというふうにとれると思います。それからもう一つ、今度大井地区にも小中一貫校の拡大をするという方針ですけれども、これに対しては、関連のＰＴＡなり、教職員なり、地域に対する説明、理解を得る努力はされたんでしょうか。","respondent":"指田教育次長","answer":"大井地区については、まだ一定程度そういう方向で、区民の方の声を聞いて、小中一貫校を全区的に展開していきたいんだ、大勢の地域において展開していきたいんだ、各地域と言いましょうか、各地区においてですね、展開していきたいんだという考え方で。","voiceIndex":12,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"私は先日の区長の答弁で、精神的なものかもしれません。だけれども、区長はこう答弁しているんです。カリキュラムの内容がまとまった段階でこれを説明するというのは、事案を、意思を決定する前の段階で住民の声を聞こうとする姿勢は全くないんじゃないですか。これが地方自治体と言えるんでしょうか。あるいは区長答弁が貫かれていると言えるんでしょうか。いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"この小中一貫校は、今回出てきた問題だけではないんですよ。ですから、これは全然無関係のことではなくて、小中一貫校のこの請願に関しては、全く関係なくない、中心問題だと思う。進め方に対する問題ですから。それを質問しちゃいけないんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"私は今までこうした請願のたぐいをいろいろ論議に加わってきましたけれども、請願本文にかかわらなくても請願の本文にかかわる問題で質問というのはどの委員会でも自由にやっていたはずです。そうしなければ、この問題の請願の本来の趣旨や進め方の問題について、私は審議できないと思います。こんなやり方は大変不満ですね。全面的な審査をやる上において。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-007"},{"speaker":"沢田委員","kind":"提案","question":"今の質問は、そっくりそのまま後ほど提案説明が終わった後に回答願いたいと思います。第１は、予算説明では、小中一貫校の建設経費ですね、大体８０億円ぐらいだろう。それから用地買収が３０億円ぐらいだろうということが事前に説明をされておりますけれども、先ほどの段階では、詳細設計が決まっていない段階ではっきりしていないと言いますけれども、事実関係はどこまで詰まっているんでしょうか。","respondent":"鷹倉庶務課長","answer":"先ほど申し上げましたとおり、２万7,０００平方メートルの延べ床、後ほど施設検討部会の状況をお知らせ申し上げますけれども、今現在そういう大きさを考えてあります。あらかたそういう方向ですけれども、それをどの程度の平米単価でやっていくか、それによるわけです。","voiceIndex":22,"id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"私どもは、８０億円というのは、私らが言ったのではなくて、予算概要説明の中で、区の理事者から言われたんです。ですから、本会議場でこういう話があったけれどもというふうになったわけで、教育委員会から私は聞いたことではないんです。予算担当のほうから聞いたということですから、詰まっていないなら詰まっていないで構いません。","respondent":"上川内生涯学習課長、鷹倉庶務課長","answer":"現在の総合体育館は昭和５０年の建築です。今回改築という形の計画を立てたものです。","voiceIndex":24,"id":"exchange-009"},{"speaker":"沢田委員","kind":"質問","question":"としますと、築３０年ですか、おおよそ。大体こうした建物というのは８０年近く寿命があると、その間きちっと手直しをしていけば、大規模修繕をやっていけば、１００年、アメリカあたりで１５０年の鉄筋コンクリートの寿命があるのに、わずか３０年で壊すというのはどういう事情なんでしょうか。","respondent":"鷹倉庶務課長","answer":"ただ、それはあくまで法定上の耐用年数でございまして、実際上どういう形でその老朽度を見ていくかということがあります。学校改築につきましても、そういう観点から老朽度について見ていくです。","voiceIndex":27,"id":"exchange-010"},{"speaker":"沢田委員","kind":"確認","question":"じゃあ、その問題は確認しておきますけれども、私の感想から言いますと、３０年近いマンションはいくらでもそこらにありますよ。マンションの最大の問題というのは、長期的な計画的な修繕をやりながら、当面５０年、そして、その先は８０年、１００年をもたすというのが目標でみんなやっているのに対して、なぜ３０年で壊してしまうのか。私は大変むだだろうと思います。この点については。","respondent":"谷田部学務課長","answer":"その他特別な事情がある場合に学級編制を弾力化する例といたしまして、山形県におきましては、小学校１年できめ細やかな指導を行う必要があるということが認められるときには実施している。","voiceIndex":29,"id":"exchange-011"},{"speaker":"沢田委員","kind":"質問","question":"もう一度先ほどのことを聞きたいんですけれども、品川区では習熟度別だとか、少人数の、ＴＴですね、チームティーチングでということを効果を上げているということは、少人数の学級編制に、学級編制というか、少人数の教育にすれば、その効果はあるということは認めているわけですか。","respondent":"青木指導課長","answer":"これは何度もこういう場でお話をしていますけれども、その学習の内容ですね、その学習の内容とか単元の内容、領域、そうした内容によって、その人数の関係で効果があるなしが言えるというふうに考えております。","voiceIndex":31,"id":"exchange-012"},{"speaker":"沢田委員","kind":"意見","question":"私は、学習の内容という、内容をどんな内容かを問わず、少人数で教える体制のほうが絶対にいい教育ができることは間違いのない事実だというふうに思うのと、世界のこの学級編制基準に比べて、日本はあまりにも巨大学級だと、たしか毎日だか読売だか大きく報じておりましたけれども、世界の流れからしても、４０人学級でサミット加盟国でやっているところなんかおそらくないと思うんですね。","respondent":"青木指導課長","answer":"もう少しご説明しますが、国語とか算数とかいった教科学習もありますが、また集団としての教育というのもあります。それから、その教科の中でも体育だとか、そうした授業もあります。","voiceIndex":33,"id":"exchange-013"},{"speaker":"原委員","kind":"質問","question":"この請願項目に沿って、ちょっと教育委員会のご見解をお伺いをしたいと思いますけれども、小中一貫校の建設というのは、新しい形態の中で新しいシステムをつくって、それでよくしていこうという趣旨があるわけですね。私は金額的なものではなくて、質的な内容のもので、それはほかの形ではないかなというふうに思うんですけれども、その見解をちょっと教えてください。","respondent":"鷹倉庶務課長","answer":"今後、学校改築、この学校だけは、現在もご承知のとおり荏原第五中学校あるいは台場小学校、さらに来年度にも予定されております。学校改築は、全体的な学校環境の整備という大きな中での改築という大きな流れも加わっているです。","voiceIndex":36,"id":"exchange-014"},{"speaker":"原委員","kind":"意見","question":"私も今ご説明があったとおりだと思うんですね。この小中一貫校の建設を中止したから、その１００億円をそこに充当すれば、それが施設の充実になったり、あるいは３０人学級が実現できたりという話ではない。全く次元の違うものであって、それはそれ、これはこれで考えなければいけないし、しかも、現状の中では、３０人学級は法を改正しなければだめだよというような説明もあったわけですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-015"},{"speaker":"原委員","kind":"質問・要望","question":"今、委員長に整理していただきましたけれども、それと一方では、建築計画に充てた費用と、それをそっちに流用すれば、これが成り立つのかということとはちょっと違う次元の話だということをはっきりさせていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-016"},{"speaker":"沢田委員","kind":"質問","question":"本体が幾らかかるかというのを、我々は３０億円、８０億円、１１０億円というのは聞いていますけれども、明らかにしていないんですが、もしこれを学校改築なんかの一環だということなんですけれども、財源構成は、例えばですよ、１００億円だとしたらば、国とそれから区の自主財源で導入というのは、大体割合としてはどれぐらいなんでしょうか。","respondent":"鷹倉庶務課長","answer":"したがって、当然投資的経費ですので、何年かにわたって、区民が利益を受けるわけですから、そういう形での償還、したがって、単年度で云々というのは、やはりやわらかな、なだらかに負担が軽減されていく、このように考えております。","voiceIndex":43,"id":"exchange-017"},{"speaker":"沢田委員","kind":"質問","question":"「アエラ」だったか、区長が別で出たのかわからないんですが、小中一貫校の大体４０％は自主財源で、５７０億円の基金から取り崩すということが言われていたんですよね。そうすると、４０億円は自主財源ということととらえていいんでしょうか。","respondent":"鷹倉庶務課長","answer":"その数字については、私としては確認はとれてございません。","voiceIndex":45,"id":"exchange-018"},{"speaker":"沢田委員","kind":"質問","question":"それで、全く関係ないと言いながら、もしそれが事実だとすれば、４０億円は自主財源を取り崩すということになれば、３０人学級に充てることができると。全く国庫補助がないにしても、それから、しかもさっき３０人学級で１５億4,０００万円の年間というのは、これは小中学校の全学年についてですか。関連しましたので、それだけ。","respondent":"谷田部学務課長","answer":"それから５年から６年に上がる際、それから中学校２年から３年に上がる際、それぞれ学級維持制度というのがございまして、例えば小学校１年のときに４２人いて２学級編制していたという場合に、２学年になるときに、お子さんの数が減って４０人になったというケースの場合に。","voiceIndex":47,"id":"exchange-019"},{"speaker":"沢田委員","kind":"意見","question":"私は、チームティーチングなんかも、一つの前進施策だと思うんです。それから、今のも前進施策だと思うんです。そういうのを利用しながら、できるだけ費用負担の少なく、しかも効果的なもので、まずやってみると、そういうのを生かしながら。だから、対立するものでは私はないというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":51,"id":"exchange-020"},{"speaker":"佐藤委員","kind":"質問・要望","question":"ちょっとこれは委員長にお聞きしたらいいのかどうなのか、これは小中一貫校の建設計画を中止しということで、今、小中一貫校を建設することにかかる費用を通常の学校経営のほうに回せという話なんですが、これは学校建設を中止することをだけを求めている請願なんですか。それとも小中一貫教育を、その前提としてやめなさいと。そこの意図というのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-021"},{"speaker":"佐藤委員","kind":"質問・要望","question":"共産党は、その校舎の建築とか跡地の問題とかいうこともおっしゃっていましたが、そこに柱をなすのは小中一貫教育をどうするかというところを議論しないで、その小中一貫校の学校の建設を中止しなさいというのは、どうもちょっと僕は議論というか、する場合に、大事なものがどこかちょっと置いてきぼりになったような、そういう感じをするんで、その小中一貫校の建設計画というのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-022"},{"speaker":"沢田委員","kind":"意見","question":"この1,３００名の子どもたちには立派な校舎、体育館までつけて、それからカリキュラムは特別なもの、先生は特別の先生を、やる気のある先生を集めてやる、そういう考え方ではなくて、この請願は、区内すべての子どもは区民の子どもだと、だから区内全体の基礎学力というか、人格形成に有利な教育をするためには、こういう小中一貫校計画ではなくて。","respondent":"青木指導課長","answer":"この学校の研究や実践で成果を上げていく、その成果そのものも全区にそれを普及していきたい、その成果を生かしてそれぞれの学校がまたそれぞれの学校の特色づくりに邁進できるような、そういう状況をつくっていきたい、そういうふうに考えております。","voiceIndex":55,"id":"exchange-023"},{"speaker":"沢田委員","kind":"意見","question":"特色ある学校というふうに言いますけれども、戸越台中があんなに高い競争率になったわけです。それはプールを持ち、屋内プールを持ち、すばらしい学校、施設整備という問題があるでしょう。やるんだったら、みんなに基礎的な条件として、いい校舎やいい学びの環境やら、そういうものを平等にそろえて、その上で競うのならいいけれども、このやり方は私は間違えているというふうに思います。","respondent":"指田教育次長","answer":"といいますのは、我々は何も一つだけをやって、それでもって終わりとしているわけではありませんし、そのいろんな意味において、今回の答弁でも行いましたように、学校選択を含め。","voiceIndex":57,"id":"exchange-024"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、全地区的に、すべての学校で小中一貫校をやるんですか。","respondent":"指田教育次長","answer":"今後の方策とすれば、これはまたいろいろと文教委員会でもご論議いただくような形になろうかもわかりませんけれども、連携校マターでの小中一貫教育というものもやるだろうし、あるいは学校の併設型のものもやるでしょうし、あるいは４・３・２という教育を全区的に展開していく。","voiceIndex":59,"id":"exchange-025"},{"speaker":"原委員","kind":"質問・要望","question":"一つだけ。今お話の中で、これだけ確認しておきたいんですが、小中一貫校が普通の学校に比べて特別だという認識で今お話をされていたようなんだけれども、これは、もし特別であるとすると差別になると思うんですよ。それは、区別するならいいと思うんだけれども、差別をつけて、これは特別でこれは特別じゃないんだという考え方はとんでもない話で、そこのところだけちゃんと整理をしていただきたい。","respondent":"指田教育次長","answer":"何回となく本会議、今回の本会議のときでもお答え申し上げております。この小中一貫校の、第二日野小でやるところが特別に、こうやってお金をつぎ込み、新しい先生をつぎ込みなんていうことを毛頭考えている話ではありません。","voiceIndex":61,"id":"exchange-026"},{"speaker":"沢田委員","kind":"質問","question":"本当にそうなんですか。これまで「論座」だとかいろんなところで教育長が発言して、今の中学教諭は特にだめだと、公募制でやる気のある人を都の教育長に頼んで集めるんだと、そういうふうに集まった教師がやる気のあるいい先生かどうかは別ですよ。そういうことをだーっと書いてあるわけですよ。だから、みんな期待をしている部分もあるんです。ちゃんと書かれている。なぜ期待を持っているのかという意見を。","respondent":"若月教育長","answer":"そういったようなものをもう一回とらえ直そう、これはやっぱり一貫でなければできないことです。同じところでよく同じ釜の飯を食うと言いますけれども、まさにそうです。そういう中から出されたものを、あるいは得られた成果を今の在来の小中学校に返していく。","voiceIndex":63,"id":"exchange-027"},{"speaker":"沢田委員","kind":"意見","question":"５年生ぐらいから。だから、教師の問題も大事かもしれないけれども、この受験競争の中で、子どもたちが学校に丸ごと投げ込まれて悪戦苦闘している教師、子どもたち、そこに心を寄せることが私は非常に大事だと思うし、区教委と教師あるいは学校、父母らが一緒に力を合わせて、どうしたら子どもたちに対して基礎的な学力や人格形成になるかということを一緒に考えるべきだというふうに思います。許せないよ。","respondent":"若月教育長","answer":"これは非常に重要な」と呼ぶ者あり〕私は、いやこれは本論から、今日の議題からは外れていますけれども、そうおっしゃいましたので答えますけれども、〔「教育長が言ったから、私は言ったんですよ」と呼ぶ者あり〕それであるならば、かつて学級崩壊とかいじめとかがありましたか。","voiceIndex":65,"id":"exchange-028"},{"speaker":"原委員","kind":"質問・要望","question":"今教育論議はまた次の機会に任せておいて、この請願項目に沿った形で一応この審査をしていただきたい。教育論議をやっていくと幾らでも長くなっちゃうし、議論がかみ合わない部分も必ず出てくるはずなので、請願項目に沿った形で進めていただきたい。その点お願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-029"},{"speaker":"沢田委員","kind":"質問","question":"今の論議というのは、どこに端を発しているかというと、小中一貫校で一部の子どもを特別な条件でやるんじゃなくて、区民の子どもみんなに教育条件を提供しようというところから発生してずっと来たわけです。そのほかの雑誌でも、教員は何もやらないということを教育長が先頭に立って言えば言うほど現場の先生方は悩んでいるわけですから、白けちゃうじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-030"},{"speaker":"沢田委員","kind":"質問","question":"日野中ＰＴＡ関係者が、ＰＴＡでやったわけではないんですけれども、署名を集めたことに象徴されていますから、ですから、私は冒頭に進め方の問題を聞いたんですけれども、議事整理をしていただいたんで、そこはあえて後ほど言いますというふうにしましたけれども、そのほかに、ここで言っている財政の問題もありますよね。なぜ中止するのかということを論議をしなければ、請願審査にならないじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-031"},{"speaker":"沢田委員","kind":"質問","question":"私は、委員長が請願審査の中に当たって、この文言の中だけを審査をしろということを、２８年間議員をやってきたけれども、初めてです。それがなければ、これを中止しと言わないわけですから。その問題をいわば、この請願と関係していないと言ったら、今後の陳情・請願の審査はみんなその領域に入ったら、まともな審査ができなくなると思いますよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-032"},{"speaker":"佐藤委員","kind":"質問","question":"一応念のためにお伺いしておきたいんですが、これは中止する側の請願なんですが、物事は必ず反対するものがあれば賛成するものも当然あって、そういう中で、全体の区民の意見というふうなものが出てくるんでしょうが、この小中一貫校の建設に関しては、この賛成する関係者というのは、一人もいないんですか。〔「そういう質問も、じゃあここに載っていないということになっちゃう。","respondent":"指田教育次長","answer":"我々のところには、いろいろなところのまち場に行って、これは私どもだけではなくて、区長や何かも出ていってまちにいろいろなところへ行く、そういう声の中において、その小中一貫教育について関心があり、それをぜひともやってほしい、そういう声がなければですね。","voiceIndex":75,"id":"exchange-033"},{"speaker":"沢田委員","kind":"質問","question":"今の小中一貫校の声だとかメールは大多数の声だとおっしゃいましたよね。具体的にはどういうデータ調査に基づくものですか。","respondent":"指田教育次長","answer":"データを１件１件つぶさにとっているわけではありません。電話が来ましたから、じゃあこういう声がありました、じゃあ名前を教えてくださいと言って全部チェックしているわけではありません。そういうふうに、私どもとしては受けとめているという内容です。","voiceIndex":77,"id":"exchange-034"},{"speaker":"沢田委員","kind":"質問","question":"似たような発言はありましたけれども。それから、その大多数の声だと言いながら、その根拠を示すことができないというのは何ですか。例えばメールが何通来ただとか、どういう集会で言ったら、これだけの人が要求しただとか、請願署名がこれぐらい出てきただとかというんならいいですけれども、私どもの少なくともかかわっている問題では、日野中関係で3,５００人の反対の署名が出てきたこと。","respondent":"指田教育次長","answer":"最後のほうの、箇所のところに、少なくともこの考え方、言っている内容としたら、子どもたちの教育環境を優先して考え、例えば日野中学校、教育センター五反田図書館、五反田文化センター、第一日野小学校、第一日野幼稚園を有機的に提携して。","voiceIndex":79,"id":"exchange-035"},{"speaker":"沢田委員","kind":"質問","question":"それで、日野中のあの地域の人たちは、とにかく日野中が移転してもらっては困るのこの１点でまとまっているんです。だから、品川区は上で決定してどんどん進めるんじゃなくて、意見を聞き、教育専門家の意見を聞いたり、教職員の意見、父母の意見を聞いて、本当にこれをやっていくべきことなのかを、やるべきだというのに先に決めちゃって、あとは上からトップダウンで進めてきたのが実態じゃないですか。","respondent":"指田教育次長","answer":"そういったところも含めて、きちんと説明をしてまいりますし、決してゆめゆめ区民の方々に対し、あるいは地域の方々に対して説明をおろそかにするなんていう考え方は毛頭持っていないということです。","voiceIndex":81,"id":"exchange-036"},{"speaker":"沢田委員","kind":"質問","question":"あれは。データを出してほしいというのに対して。それが一つと。そうじゃなくて、さっき区長が言った、区政の主人公は区民自身だ、政策を決定する段階、その前の段階に区民を集めて意見を聞き、広聴を利用して吸い上げ、審議会をつくったりして、それを決定をしていくというのが、今全国の流れじゃないですか。住民投票の問題も含めて。それは地方自治なんでしょうか。民主教育なんでしょうか。","respondent":"鷹倉庶務課長","answer":"今の地域への説明あるいは住民への説明という話がありましたけれども、２月の１９日に大崎第一地区の町会、自治会連合会の会議の集まりの中にお話をしてまいりました。","voiceIndex":83,"id":"exchange-037"},{"speaker":"沢田委員","kind":"意見","question":"長くなっているからあれですけれども、先ほどの論議で、小中一貫校を計画をしていった、その背景にはたくさんの小中一貫校推進の声とメールが寄せられているというふうに言われていたんだけれども、じゃあメールは何件寄せられたのか、声はどうした形で寄せられたのかと聞いたんです。今の段階になって、説明会でこういう意見だということを聞いたんじゃないんです。","respondent":"富田教育改革担当課長","answer":"ただいまメールですとか、また区民の方々からどういうお声が寄せられたかというご発言ですが、メールに関しましては何件かいただいておりますが、ほとんど小中一貫校についての質問のような内容が多うございまして、１件１件回答しています。","voiceIndex":85,"id":"exchange-038"},{"speaker":"石田委員","kind":"確認","question":"先ほどからちょっとお話を伺っていて、データとかそういう話が出たけれども、１点だけすごく確認をしたいことがあります。区教委は、品川区の子どもたちにとって何が大切かということを、もちろん真剣に考えて、教員の指導力不足も考えて、さまざまないろいろな問題を考えて、小中一貫教育が大切だということを判断をしたわけだと思います。","respondent":"指田教育次長","answer":"したがいまして、方向とすれば、今石田委員が言われたこの考え方をもとにして、我々としては教育行政というものは進めていく、いるつもりですし、今後も進めていきたい、このように考えております。","voiceIndex":87,"id":"exchange-039"},{"speaker":"石田委員","kind":"意見","question":"だけれども、先ほど言った場所の問題については嫌だと、明確に言っていらっしゃる方も地元の中にいらっしゃることは私も理解をしているけれども、ここで言う「小中一貫校の建設計画を中止し」という考え方については、その建設予定地を別として考えるのならば、私は小中一貫校の教育課程を、そういう形の小中一貫教育を入れた学校をつくってほしいという声のほうが多いと思うし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":89,"id":"exchange-040"},{"speaker":"上山副委員長","kind":"質問・要望","question":"一、二ちょっと確認だけさせていただきたいんですけれども、簡単なことですし、３０人学級の考え方のところなんですけれども、先ほど最初のほうでもどなたか議員の中で、３０人学級は法的にどうのこうのという話をちょっと出たように思うんですが、３０人学級、今の３０人学級をつくっていく上で、法的にどんなふうな状況になっているのか、それから今と、それから今後こういうふうに変わっていく。","respondent":"谷田部学務課長","answer":"公立義務教育諸学校の学級編制及び教職員定数の標準に関する法律というのがございまして、この中で、都道府県が学級編制をする場合につきまして、小学校につきましては４０人、中学校も４０人ということで、その分の教員の国庫負担もあるです。","voiceIndex":90,"id":"exchange-041"},{"speaker":"上山副委員長","kind":"質問","question":"文部科学省のほうでそういう動きが出ているというようなことでの報道があったように思うんですが、そこら辺はどうなんでしょうか。現状は、今伺いましたが。","respondent":"谷田部学務課長","answer":"これは各都道府県の教育委員会の判断によりまして、小学校低学年、先ほど学級維持では小学校２年、それから卒業を控えた６年、それから中学校３年、東京都につきましては、その３学年については前年度の学級数を維持できる制度を設けたということで。","voiceIndex":92,"id":"exchange-042"},{"speaker":"上山副委員長","kind":"確認","question":"もう一度ちょっと確認したいんですが、それは国庫補助とかいろいろかかわりがあるかと思うんですけれども、今回の請願のかかわりで言えば、小中一貫校の計画中止とその費用で３０人学級というのは、表現はちょっといろいろあるんですけれども、実際その３０人学級をつくっていく上で、例えば先ほどこの説明の中でも例えばということで、費用が３０人以下学級にしたらどれくらいかかるという説明の中で。","respondent":"谷田部学務課長","answer":"区の単独の財源で充てなければならない。それが１人当たり平均年収1,０００万円とすれば、毎年１５億4,０００万円ほどかかりますよと、これは区の持ち出しになりますというお話です。","voiceIndex":94,"id":"exchange-043"},{"speaker":"上山副委員長","kind":"質問・要望","question":"今のかかわりと別な話の、品川で例えば３０人学級を独自にやるということであれば、先ほど今答弁があったような品川区の独自負担、財源で言えば１５億4,０００万円ということで、法的にはこれは問題ないにしても、お金を出せばという前提で言えば、あまりそういうのは前提がないのかもしれませんけれども、法的にそのことが何か問題があるわけではないと私は思うんですけれども。","respondent":"谷田部学務課長","answer":"４０人以下の学級編制は、その４０人を超える場合については法律でも問題はありますけれども、その４０人以下である場合については問題ございませんで、ただ、先ほど申し上げましたとおり、国のほうの給与の負担法の関係が出てまいりますので。","voiceIndex":96,"id":"exchange-044"},{"speaker":"中島委員","kind":"提案","question":"先ほどからずっとお話を伺っているんですが、今日の本題というのが、小中一貫校の建設計画を中止し、３０人学級という極端な提案なんですが、署名の人数のこととかいろいろありましたが、私たちもいろんな地域の中に入っておりますから、いろんな声を聞いております。そういう中で、小中一貫校に期待する声というのは非常に多く受けております。","respondent":"青木指導課長","answer":"これはもう学級の子どもたちの数の問題ではございません。教師はどんな人数でも教師としての質というのは問われますし、そうした指導力を向上していかなければならないというふうに考えております。","voiceIndex":98,"id":"exchange-045"},{"speaker":"中島委員","kind":"質問","question":"私もそう思うんですね。その中の一つの案として小中一貫校ということを計画されて、多くの期待もあるわけですから、今日のこの審査というのは、３０人学級をその小中一貫校の計画を中止してという、極端なこういうものに対して、どう対応するかという簡潔な対応の仕方でいいんじゃないかなと思います。その上で、教育論議というのは別のところでやっていくべきじゃないかなと思いますが、私のこれは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-046"},{"speaker":"沢田委員","kind":"質問・要望","question":"今後、大井地区まで小中一貫校を拡大をしていく方針なんですけれども、基本的なこのスタンスというか、姿勢を聞きたいんですが、関係ＰＴＡ、地域、それから当該の教職員に対して理解を得ると、合意を得る努力というのを私はぜひ貫いていただきたい。その努力を決める前から関係者の意見を集約して進めてほしいと思いますけれども、いかがでしょうか。決めた後もですけれども、もちろん。","respondent":"指田教育次長","answer":"といいますのは、一言一言、正直言いまして揚げ足取られて、ここのところ言ったじゃないかと言われるのが私非常に不安なところがありまして、はい、そうですと、こういう形には言えませんけれども、できる限り、私のほうはこういった施策をしていく。","voiceIndex":101,"id":"exchange-047"},{"speaker":"沢田委員","kind":"意見","question":"私は、継続か結論を出すかということについてはですね、今日は実際の小中一貫校のステップアップ学習、あるいはコース別教育というのを現在までされておりませんし、それからできれば少人数学級が全国的にどうなのか、それから東京２３区、三多摩でどういう動きがあるのか、あるいは長野県の県教委では少人数学級をやってきたことを県教委としてまとめているだとかということがありますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":105,"id":"exchange-048"},{"speaker":"高星委員","kind":"質問","question":"意見を言う前に、３０人学級について、この委員会で３０人学級の実現という部分について、さまざまな話をこれまでもして、ほかの案件で何かそのさばきについて何かあったように思うんですけれども、ちょっと委員長のほうで、それをちょっと教えてもらえませんか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-049"},{"speaker":"高星委員","kind":"質問・要望","question":"今、うちの委員会で決を出したことがあるかないかという、一つの参考にしようと思ったんですが。じゃあこれからちょっと私の意見に入りたいと思います。場合によっては、いつどんな予想もつかないようなことが起こるかもわかりませんから、そういう場合は必ずしもそうじゃないんだということで、お考えをしておいていただきたいということで、私も今日決をとっていただいて結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-050"},{"speaker":"佐藤委員","kind":"意見","question":"まだ意見表明をしていなかったんであれなんですが、小中一貫教育に関しては、これからも幅広くいろんな議論、これは当然必要であると思いますが、この小中一貫校の建設計画を中止しという本請願に関しましては、反対をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":112,"id":"exchange-051"},{"speaker":"沢田委員","kind":"質問・要望","question":"この点では、改めて関係者の意見を事案決定前に十分説明し、理解を得る努力を、特に新しい施策をやるときにはやっていただきたいということが一つと、それから、今日はちょっと時間の関係でできなかったんですけれども、今度のカリキュラムで見ますと、小学校５年生からコース別の学習を入れていくということを言われていますけれども、もしこうした形で理数系だとか文化芸術系だとか、言語系だとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-052"}]},{"id":"topic-02","title":"平成１２年請願第２７号、「遺伝子組み換えイネ」を学校給食に使用しないことを求める請願","agenda":"平成１２年請願第２７号、「遺伝子組み換えイネ」を学校給食に使用しないことを求める請願","exchanges":[{"speaker":"原委員","kind":"質問","question":"だから、安全性の審査については、やっぱり確たるものができ上がっていないという話をされていましたので、それをここでどうのこうのというのはなかなか難しい状況なんじゃないかなと思うんですね。結論を出すにも忍びがたいところがあるし、請願の要旨の中にもいろいろ書かれていますからね。どうしたらいいでしょう。継続でいいんじゃないかと。私は。結論は先送りじゃないでしょうかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-053"},{"speaker":"佐藤委員","kind":"意見","question":"私どもの会派のこういう専門の方が１人おられまして、ここにも紹介議員になっていますけれども、今現在、この遺伝子組み換えのお米が使われているわけではないし、今説明があったように、まだ研究段階ということであれば、原委員と同様、継続にしたほうがいいんじゃないかなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":124,"id":"exchange-054"},{"speaker":"中島委員","kind":"質問","question":"ですから、こっちがよくて、向こうが悪いとかという、そういうことをまず決めることも今は無理だと思うんですね。ですから、この問題に対しては、やはりもうちょっとしっかりいろんな研究が深まってから取り組むべきことかなと私は思っています。ですから、継続でも構わないと思います。ですから、原委員のおっしゃったように継続で私はいきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-055"},{"speaker":"沢田委員","kind":"質問","question":"〔「読んで。それで、一部遺伝子組み換えの食品が日本にも上陸をしていますけれども、本当に将来にわたってそれが人類にどういう影響を及ぼすのかというのは、よほど慎重にしないと取り返しのつかない問題になるというふうに思っています。ですから、将来にわたって遺伝子組み換えでいろんな実験を通じて大丈夫だということが出れば、そのときは別ですけれども、現時点ではこの趣旨には賛同いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-056"},{"speaker":"高星委員","kind":"意見","question":"何とも言えない、私も趣旨採択でお願いしたいなというふうに思っているんです。なぜかと言いますと、最近はいろんな遺伝子の組み換えなんかで、こんなこと言うと古くさい人間だと思われちゃうかしれませんけれども、人間までつくられてくるような時代になってくるという。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":127,"id":"exchange-057"},{"speaker":"中島委員","kind":"意見","question":"私も今ちょっと言い方を間違えてしまったと思うんですが、継続ということではなくて、今結論が出る問題ではないし、区のほうとしてもよくよく検討されるというお答えがありましたので、趣旨採択という形でいいと思います。ちょっと継続と間違えて言ってしまったので、すみません。訂正します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":128,"id":"exchange-058"},{"speaker":"石田委員","kind":"意見","question":"先ほども言ったように、遺伝子組み換えというものはさまざまな論議はあるにしても、いい方向性だという話もあれば、それは先ほど今高星委員もおっしゃったように、主観的にそれは理解できないというようなことも、それはさまざま意見があると思いますが、ここに出てきた請願項目自体は、このもの自体がないものに対してそれを、その趣旨がわかるとか、わからないとか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":129,"id":"exchange-059"},{"speaker":"高星委員","kind":"意見","question":"だから、そういう視点で言いますと、確かに今石田委員がおっしゃったことはよくわかります。考え方の方法、一つの考え方としては、品川区のこれからの教育にも大きく影響してくるんだということもあわせて考えれば、私は別に近未来にこういうことが起こるとするならば、僕は趣旨採択してもおかしくないんじゃないかというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":130,"id":"exchange-060"},{"speaker":"佐藤委員","kind":"意見","question":"そうすると、市場に出回るような見通しが確かになった段階では、それに対してこういうふうな請願が出てきて、それをその是非を議論するのはいいと思うんですが、あくまでも研究段階で、これを品川区議会としてその是非を論ずるのはちょっといかがかなというふうに、北野議員があえて紹介議員ではあるけれども、僕自身は、やはり改めてまたそういう時期が来ればお出しいただくのも一つの方法ですし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":131,"id":"exchange-061"},{"speaker":"原委員","kind":"質問・要望","question":"ある意味では。ですから、はっきり決められたことではないことについて、ここがいろいろ考えるとちょっと取り越し苦労的な考え方をして、こういう請願をなさったのかなと思うんですけれども、どうもそこを考えると、今継続の話をされましたけれども、もう一度よく考えた時点で請願を出すなり何なりをしていただいてもいいんじゃないか。だから、そういう意味では、継続で見直しをさせていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-062"}]},{"id":"topic-03","title":"小中一貫校施設計画検討部会の検討状況","agenda":"小中一貫校施設計画検討部会の検討状況","exchanges":[{"speaker":"高星委員","kind":"確認","question":"一つだけ。午前中の議論も含めて、説明にないようなことを聞くのも気が引けるんだけれども、一つだけ。施設検討部会のほうに、ＰＴＡ会長は入っていないですね。それだけ確認したいと思います。","respondent":"鷹倉庶務課長","answer":"この施設検討部会の状況についてという形で、この６回を今終えているわけですけれども、１回、２回、３回という形で出席していただいております。４回目から都合により出席していただけていないという状況です。","voiceIndex":142,"id":"exchange-063"},{"speaker":"高星委員","kind":"質問","question":"私は、実は嫌な記憶で、総合体育館の記憶があるので聞きたいんだけれども、前に戸越体育館の工事か何かのときに、選挙の開票所も総合体育館でやったことがあるんだけれども、だから、今回あそこは冷暖房、屋内の体育館、冷暖房をつけるのかどうなのか、それだけちょっと教えて。そういうことを考えているのかどうなのか、ちょっと教えてもらいたい。","respondent":"鷹倉庶務課長","answer":"総合体育館の冷暖房をどうするかということは、今後実施設計をする中で考えていかなければいけないわけですけれども、ただ一つ考えられるのは、非常に大きな体積を占めてありますので、それをやっていく場合、かなりのコストがかかるという部分、これを十分配慮しながら。","voiceIndex":146,"id":"exchange-064"},{"speaker":"高星委員","kind":"意見","question":"だから、あえて聞いたのは、前に総合体育館でやったときに、夏だったんですよ。何期かな、４期目かな、そうすると、蒸しぶろみたいになって、それで車を何台もトラックみたいなでっかいのが来て、クーラーを入れたんでしょう、あれ。そうすると、もろに当てると今度は票が飛んじゃうし、えらい苦労したんです。本当に蒸しぶろみたいなところでやっていたんですよ。考えていくくらい言ってください。","respondent":"鷹倉庶務課長","answer":"先ほど申し上げましたとおり、そういうコストの問題もあるということを踏まえつつ、そういう全体の空調のことも十分検討していきたいな、そのように考えてあります。","voiceIndex":148,"id":"exchange-065"},{"speaker":"石田委員","kind":"質問","question":"一方は今ちょっと広くなったけれども、そうすると、これでいくと、この計画で３方はそんなに広くないと思うんですが、どれぐらいの道路幅にしようと考えていらっしゃるのか、普通のセットバックとか、何ｍにするというのはある程度考えを持っていかないと、一番最初にそれが決まってくることだと思うんですね。","respondent":"鷹倉庶務課長","answer":"南、南」と呼ぶ者あり〕失礼いたしました。南側が６.５ｍで、北側が５ｍ。問題は、この規模の建物を建てるときに、どの程度後退するかということがあります。それを合わせた形でゆとりのあるような形の建物にしていかなければいけないというふうに考えているところです。","voiceIndex":150,"id":"exchange-066"},{"speaker":"石田委員","kind":"質問・要望","question":"法律上のセットバックだけだと。それが今お話を伺ったら、何かまだそれがという話だから、ぜひこれは先にやらないと絶対だめなことだと思うので、要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4464#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":53257,"voices":156}},{"id":"h15-20030303-5","meetingId":"h15-cm03","date":"2003年3月3日","dateIso":"2003-03-03","committee":"総務委員会","time":"午前１０時１５分～午後３時０５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を97件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"１、議案審査の１の第１０号議案、品川区職員定数条例の一部を改正する条例","agenda":"１、議案審査の１の第１０号議案、品川区職員定数条例の一部を改正する条例","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"それと、衛生試験所の検査技術ですけれども、今まで検査技術が１２名いて、特に今は食品衛生の問題とか、さまざまな環境問題で、かなり技術的に高度なものもあると思いますし、同時に、区民の安全性という点から、非常に心配があるわけですけれども、どういうような内容が委託されるのか、そういう内容ですね、直営でする部分、委託の部分を教えていただきたいと思います。","respondent":"桑村人事課長","answer":"今回の検査技術の見直しの考え方ですけれども、基本的に非常に緊急を要する、あるいは食中毒ということで、すぐに結論を欲しい、あるいは対応をしなければいけない、それと一般的な、例えば糞便検査、あるいは血液検査等、ほかの検査業者でもやれるものと。","voiceIndex":8,"id":"exchange-001"},{"speaker":"桜井委員","kind":"質問・要望","question":"そうすると、検査技術のほうからいきますと、直営でやるということは今はっきりしなかったんですけれども、食中毒の関係とか、血液検査とか、緊急を要するものとか、そういうところで５名残したという理解でいいんでしょうか。それって話が違うんじゃないかと私は思うんですけれども、その点についての考え方を、人事課長に聞くのも何ですけれども、総務部長であれば、教えていただきたい。","respondent":"桑村人事課長","answer":"そういうものは対応をしてもらったほうが、むしろ仕事の中身としてうまくいくのではないだろうかという考え方で進めてあります。次の保育園のことですけれども、栄養士につきましては、６名がおります。","voiceIndex":10,"id":"exchange-002"},{"speaker":"桜井委員","kind":"意見","question":"保育士の関係で言うと、３５名の減と言っておりますけれども、この間５、６年の間でも夜間保育をやったり、休日保育をやったりとか、幼児保育とか、仕事の量としてはかなりきついというか、内容的には大事なことですけれども、そういう点から言えば、必ずしも、単純に事務系と比較できないと思うんです。そういう点では、この委託については大きな疑問がありますし、理解しがたいというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-003"},{"speaker":"川西副委員長","kind":"質問","question":"今、説明の中にあって、聞き漏らしたかもしれませんが、保健師の減員というものの主な見直しの事業というのを教えてください。","respondent":"桑村人事課長","answer":"保健師につきましては、何が定数かというのは、正直言って、はっきりしない部分もございまして、人口１万人当たりの率にするかというような話で、ある程度決めていたわけですけれども、保健師の業務が今後どういうふうな形で進んでいくんだと言えば。","voiceIndex":13,"id":"exchange-004"},{"speaker":"川西副委員長","kind":"質問・要望","question":"今のご答弁は８０％賛成なんです。検査業務で事務職でできるものはいっぱいあると思います。高齢者の健康づくりとか、相談業務、高齢者でも出来ると思うんです。そういうものは再雇用を活用していただいて、私は従来、相談業務というのは、予算特別委員会か、決算特別委員会か、本会議の一般質問でしたと思うんですが、そういう窓口は再雇用の方に出張っていただきたい。ここで要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-005"},{"speaker":"土井委員","kind":"質問・要望","question":"役所は何をやるべきか、民間に何を頼むべきか、この辺を厳格に検討をして見ていくということは極めて重要なことだと思います。ただ問題は、区がやるべきことというところですね。区がやらなければいけないこと、ここの部分と、任せてもいい部分というものをどうきちっと選び出していくのか、見極めていくのか、ここが極めて重要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問","question":"８５名という人は、定年を迎えたというふうに理解をしていいんですか。","respondent":"桑村人事課長","answer":"そうではなくて、職種の見直しをしたです。先ほど言いましたように、採用につきましては、事務の１１人と保育士１８人ということがありますので、２９人です。退職者は別に関与しているものです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、減というのはどういうふうに理解をしたらいいのか。もうちょっと言うと、増もあるわけですね。その辺はこれでは見えないですね。その辺を教えてほしい。人事についても、同じような仕組みを事業部長に権限をある程度持たせる。その辺でこういうふうに出てきたのか、あるいは人事課、総務部で数字のやりくりをしてきた結果なのか、その辺をちょっと聞かせてください。","respondent":"桑村人事課長","answer":"ちょっと定数での説明と、採用、退職のその年の数字の説明とは、例えば５年サイクル等では合うんでしょうけれども、その年ではなかなか合わないというのが現状です。それから、事業部制の話です。","voiceIndex":19,"id":"exchange-008"},{"speaker":"林（宏）委員","kind":"意見","question":"事業部制を取り入れて、人員配置という部分に非常にウェートがかかっているところがあるわけだから、例えば新規採用の人をぜひ欲しいとか、あるいはここまで削れそうだとか、事業部案というか、そういうものをしっかり出すように、人事課が部長にものが言えるかどうかわからないけれども、でも、それは扇の要のほうがものを言うということになるわけだから。","respondent":"本間総務部長","answer":"それが事業部制をとることによりまして、今は私と人事課長と、それぞれの事業部長とのやりとりに変えてございまして、事業部長のほうも、先ほどお話の出ました「ヒト、モノ、カネ」という、事業部内の経営的な観点から。","voiceIndex":21,"id":"exchange-009"},{"speaker":"林（宏）委員","kind":"意見","question":"お考えはそれぞれ持ちようだから自由だろうけれども、命が危ないとか、そういうようなことに対しては明確に、大丈夫なんだという、この数字だけではなくて、行政としての責任は何らかの形でしていく責任があると思います。片方しか伝わらない場合もあるわけだから、その辺はきちんと行政の責任で伝えていくというのが、さっきの土井委員のお話にプラスしてというか、併せてお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-010"},{"speaker":"藤田委員","kind":"質問","question":"もう１点は、区民課のほうの品川荘にも職員が張り付いていたというのを初めて知ったんですけれども、例えば日光についてはいると思いますが、箱根荘についてはどういうふうになっているのか。今まで必要があって品川荘に職員が１名いたという、今回退職ということで、今後の業務に支障はないのかどうか、その辺をお聞きしたいと思います。","respondent":"桑村人事課長","answer":"保育園の調理代行の話ですが、平成１２年から進めてまいりまして、平成１５年の９園が入りますと、平成１６年度は残るのは９園です。","voiceIndex":24,"id":"exchange-011"},{"speaker":"藤田委員","kind":"質問・要望","question":"品川荘については分かりました。ですから、残りの９園も、通園させている保護者に対してはある程度、口では言わないかもわかりませんが、早くやってもらいたいなということがあると思いますので、ぜひその辺を、まだ平成１５年度が始まっておりませんけれども、その次の年に向かって検討をしていただきたいなということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-012"},{"speaker":"嶋委員","kind":"確認","question":"先ほど川西副委員長の中でお話が出ました考え方だと思いますが、保健師の件ですが、現在、保健師が何名いらっしゃるのかということと、今、区民まつり等で、区民の健康を増進せよみたいなコーナーをつくっていただいて、保健師に来ていただいて、まちの中で地域と一体となってやっておりまして、今年度も区も力を入れたという、心に障害を持った方たち、引きこもりとかありますが、高齢者のみでなくて。","respondent":"桑村人事課長","answer":"むしろ逆に、方向とすれば、相談業務のほうへ進んでもらいたいという考え方がありますし、これからもそういうふうに考えていると思いますので、そちらの方向へ仕事は進んでおります。","voiceIndex":27,"id":"exchange-013"},{"speaker":"塚本委員","kind":"質問・要望","question":"林委員の言われた点で伺います。そういう種類で人を少しずつ減らしていくという方法が一つある。それから、土井委員も指摘したように、この仕事は区が直接やる必要はない、民間委託をしようじゃないかということの、どっちのほうから判断が働いてくるかということも定数になって形で表れてくる。そこのところの仕組みをひとつお聞かせいただきたいと思います。","respondent":"桑村人事課長","answer":"もう一つは、大きな意味での視点の考え方につきましては、これは毎年総務部からの、来年につきましてはこのことについて検討をしていただきたい、あるいはそれについての回答をいただきたいということのやりとりを別途やっております。","voiceIndex":29,"id":"exchange-014"},{"speaker":"塚本委員","kind":"質問・要望","question":"１点は、この仕事を民間に委託しようじゃないかとされた場合に、やめてしまおうじゃないかと。委託した場合には、携わった職員が見かけ上はいなくなるわけですけれども、それでは予算措置がどこに、向こうの働き手はいるわけですから、それをどういうふうに人員としてカウントするかという仕事が残っている。そのことをお聞かせいただきたい。","respondent":"桑村人事課長","answer":"これはある程度職種的なものもありますし、それから、林委員もおっしゃられましたけれども、それと、今回の定数の問題がどこの時点で合致するかというようなことを検討していく。","voiceIndex":31,"id":"exchange-015"},{"speaker":"塚本委員","kind":"質問","question":"もう一回委託したときのことをお聞きしたいと思います。","respondent":"桑村人事課長","answer":"委託したときの職員の考え方につきましては、基本的には、ほかの職場についていただくというのが原則です。","voiceIndex":33,"id":"exchange-016"},{"speaker":"塚本委員","kind":"質問・要望","question":"１点目の、委託したときのコストパフォーマンスということは、人件費も含んでいるわけですから、その比較は常に意識して、我々が見やすいようにするという習慣をつけていただきたいと思います。改めて隘路といいますか、何なのか、どうすべきかということを伺いたい。","respondent":"本間総務部長","answer":"この過員を解消する方向として、今まさにご指摘の部分がありますが，この点につきましても、例えば技術系であっても、大学卒とか、高校卒程度の能力はあるわけですから、それの技術系とか、要するに、つけるような、そういうような方向での検討をしていきませんと。","voiceIndex":37,"id":"exchange-017"},{"speaker":"桜井委員","kind":"質問・要望","question":"ですから、そういう点は、委託先だからと言って、そうした状況がどういうふうな形で提供されているのかどうかという、例えば１園、２園というだけでなくて、今お話があったように、３７園中２８園になりますよね。もう一つ、先ほど話があった保健師ですけれども、たしか１万人に１人、一定程度の配置基準というのがあったような気がするんですけれども、それは今は整っているんでしょうか。","respondent":"本間総務部長","answer":"保育園の調理代行につきましては、この間いろいろな場面で議論がされておりまして、お答えしておりますとおり、サービスを下げないで、効率的に良く事業目的を達成するということで、そういう意味で、それぞれ委託している業者につきましても。","voiceIndex":39,"id":"exchange-018"},{"speaker":"桜井委員","kind":"意見","question":"法的責任というか、区民へのサービスというのは、より積極的に、しかも、さまざまな複雑多岐にわたっていることについて、もっと質の向上を図るべきだというふうに思っております。それと同時に、３番目には、先ほど指摘した検査技師の問題、保健師の問題についても、かなり区民の生活に係わる重大な分野での委託というのは、これも理解しがたいと思います。最後に、技術の継承の問題も指摘したとおりです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-019"}]},{"id":"topic-02","title":"２の第１1号議案、職員団体のための職員の行為の制限の特例に関する条例の一部を改正する条例","agenda":"２の第１1号議案、職員団体のための職員の行為の制限の特例に関する条例の一部を改正する条例","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"準備はいけないよということですけれども、３のところで、適法な交渉とは、交渉および具体的な協議案件の合意形成に不可欠な意見集約と意見聴取とするということですけれども、本文のほうでは、「交渉を行う」、準備が抜けたということですが、交渉および具体的な協議案件の合意形成というのは、どこのことを指しているのか、理事者側と労働組合との具体的な協議、合意形成を指しているのか。","respondent":"桑村人事課長","answer":"これは当局側と組合側の間に交渉案件がございまして、それの合意形成ということです。","voiceIndex":49,"id":"exchange-020"},{"speaker":"塚本委員","kind":"質問","question":"と言いますと、組合内の合意形成については、準備行為というふうに判断していいわけですか。","respondent":"桑村人事課長","answer":"基本的に今回この内容でいくのは、いわゆる交渉そのものをやっている時間、それから、交渉を円滑に進めるために、向こうが一旦中座をして、合意形成のために向こうなりの会議をするという場合だと思います。","voiceIndex":51,"id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"説明があったわけですけれども、単純に、準備の抜けたその中身は何かということで、今言ったように、交渉が始まって、その間に一旦中断して、また話し合いをするということは当然あることですから、これは交渉そのものだよというふうに解釈します。その辺のところが判然と区別しにくいのではないかという心配を聞いているんです。","respondent":"桑村人事課長","answer":"一つ、今回対象外となる活動、２にあるものについてはすべて対象外ということで、これは交渉継続であったとしても、必要ないだろうというふうに判断しております。そういう意味では期間的な機関運営ということです。","voiceIndex":53,"id":"exchange-022"},{"speaker":"塚本委員","kind":"意見","question":"条例としては明確な表現になっておりますけれども、運用となると、それこそ交渉ごとの範囲も当然出てくるわけですけれども、その辺のところを態度を明確にして、方向性をしっかり示しておく必要があると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":55,"id":"exchange-023"},{"speaker":"土井委員","kind":"質問","question":"そうすると、これは交渉なんですよ、勝手なことを言っているんだったら、それは交渉とは言わないんですよということになりますね。それはどちらかの仕事になると思うんですけれども、具体的にこれが協議のことなんですよということが決まらないと答えが出ないわけですから、ここが非常に重要だと思うんです。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-024"},{"speaker":"桜井委員","kind":"質問","question":"今回の、ながら条例の改正にあたって、昨年第４回定例会である議員の質問で、区長も答弁されていて、その答弁の内容は、ながら条例の中から除外するということで、組合と合意に達したというふうに聞いているので、当然のことながら、品川区においてもそのような方向で組合と詰めて、条例の改正をしてまいるというふうに答弁をされているわけですけれども、この間の。","respondent":"桑村人事課長","answer":"一つは、組合との話し合いの経過ですが、これは私どものほうとしても東京都の動向、あるいはその後質問等を受けまして、１２月末に組合のほうに提起をいたしました。その辺は、ながら条例の改正をしたいです。時間内組合活動の見直しをするです。","voiceIndex":57,"id":"exchange-025"},{"speaker":"桜井委員","kind":"意見","question":"当然ながら、労働基準の関係で言えば、団結権というのが認められているというところにきていると思うんです。後段は意見として述べておきたいと思いますけれども、一応合意をしたということについては、是としたいというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-026"},{"speaker":"藤田委員","kind":"質問・要望","question":"先ほどから議論になっておりますが、どの時点で始まって、どの時点で終着するのかという、これは第三者から見て分かるような、そういうチェック体制といいますか、これは決められた正当の中で行われているんだというものを区民の皆さんにもきちっと理解を示す体制も、これはやはりこういうふうに飛び抜けているわけですから、双方が規律に基づいてやると思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-027"}]},{"id":"topic-03","title":"３の第１２号議案、職員の特殊勤務手当に関する条例の一部を改正する条例","agenda":"３の第１２号議案、職員の特殊勤務手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"土井委員","kind":"質問・要望","question":"それと、それらの作業が、いわゆる金銭的なもの、手当というような形のもの、それから、給与表がどうなのかというもの、あるいはその進み方とか、運用の仕方がどうなのかというもの、こんなものがあるのではないか、よくわかりませんので、そういうふうに思うんですけれども、その辺についてお聞かせをいただきたいと思います。","respondent":"桑村人事課長","answer":"私どものほうについては、その制度がないです。その辺のところの任用制度の整備が必要です。これは平成１８年度にむけてこれについても整備していこうというような、早急に検討をしています。","voiceIndex":67,"id":"exchange-028"},{"speaker":"土井委員","kind":"質問","question":"そうなると、今いらっしゃる区の職員が移るということになれば、今の職員の方、あるいは職員団体の皆さん等がどのように理解をされているのかというのが一つある。この関係をどう調整をし、理解を得ているのかということ、ここが一つ大きなポイントだろう。まして、場合によっては作業を一緒にやらなければいけないわけですから、そこら辺についてはどのような形になっておりますか。","respondent":"桑村人事課長","answer":"その中で議論をさせていただきまして、平成１８年度に向けて制度をつくるという考え方で、今日段階、清掃の東京都の組合とも話をいたしまして合意をしておりますし、その他の職員の方とも合意しております。","voiceIndex":69,"id":"exchange-029"},{"speaker":"土井委員","kind":"確認","question":"今のところをもう一度確認をしたいんですけれども、下の清掃業務手当、それから上のほうの１の不規則勤務手当等の、現在の区の職員の皆さんに対する処遇については、今の職員団体との間で合意に至ったというふうに理解していいのか。","respondent":"桑村人事課長","answer":"これは言い方は難しいんですけれども、区の職員の労働条件ですので、東京都の清掃の方と、私どもが特にそのことについて交渉する必要はないわけですけれども、現実には働いている方ですので、その辺は情報提供をさせていただいてあります。","voiceIndex":71,"id":"exchange-030"},{"speaker":"土井委員","kind":"質問","question":"端的に言えば、東京都の派遣の皆さんは、交渉相手はだれなのか、協議相手はだれなのかという問題等々が絡んでくるので、その段階でそちらの皆さんも含めて合意されているのか、「ちょっといらっしゃいよ」と言って話をしてみて、情報提供したんだというのでは大分話が違うので、その辺をお聞きいたします。","respondent":"桑村人事課長","answer":"ただ、一緒に働く清掃事務所のほうもそういう団体を持ってありますので、そことも話し合いをさせていただいたとか、そのデータは、いわゆる交渉と合意という形ではございませんけれども、理解を得るようにお話をさせていただいて、向こうにしてみれば、本俸まで含めて。","voiceIndex":73,"id":"exchange-031"},{"speaker":"土井委員","kind":"質問","question":"要するに、区の職員はこういう形でやるんですよ、こういう形にするんですよ、そして、こちらの組合とは合意したんですよという情報を提供したと。そして、その情報の内容等々について理解をされたのか、それとも、区の職員がやられるんじゃしようがないでしょうという意味の理解もあり得るわけですね、了解するには二つあるわけです。そのうちのどちらなんですか。","respondent":"桑村人事課長","answer":"情報した云々じゃなくて、この内容について理解を示したということです。","voiceIndex":75,"id":"exchange-032"},{"speaker":"林（宏）委員","kind":"質問","question":"ちょっと理解が浅いので。１ページの、午前７時３０分というのを午前７時１０分に繰り上げるというのは、今までは７時３０分から働く場合は不規則手当が出ますよというふうになっていたのを、７時１０分に直すということは、７時３０分という人はこれから外れるというふうに理解をするわけですか。","respondent":"桑村人事課長","answer":"実は、私もこういう表現がいいのか、逆に、何とか以前という表現がいいんじゃないかと、いろいろ思ったんですけれども、今の質問に答えれば、７時３０分からの方も入るという考え方です。","voiceIndex":77,"id":"exchange-033"},{"speaker":"林（宏）委員","kind":"意見","question":"例えば７時４５分だったら、以前の７時３０分という表現の仕方は対象にならなかったわけでしょう。今度は７時１０分という表現になったら、７時３０分は対象にならないというふうに、日本語の解釈の仕方としては，普通は理解すると思うんです。","respondent":"桑村人事課長","answer":"条例のつくり方で、私もちょっと疑問のところがあるんですけれども、いわゆる３０分以上になれば、うしろは５時４５分ですね。５時１５分から５時４５分の間、いわゆる３０分については、不規則勤務手当の対象外という考え方です。","voiceIndex":79,"id":"exchange-034"},{"speaker":"林（宏）委員","kind":"意見","question":"逆に言うと、７時から出なさいよというのは言えないということに解釈をすればいいわけですね。それから、２ページの第１０条の１だけど、清掃事務所に勤務する職員が、ごみもしくはし尿の収集作業または自動車による運搬作業に従事したとき、品川区の仕事は収集・運搬ですよね。とすると、何でこの文章があるのか。その中で、何であえて収集作業または自動車による運搬というのが必要なのかどうか。","respondent":"桑村人事課長","answer":"収集に携わわらないわけではございませんけれども、職員の両方を該当させるという意味です。今回これに該当する職員は、清掃車のうしろに乗って、積み込み作業をやっている職員と、品川区ですと直営で自動車運搬をやってありますので、そういう職員はです。","voiceIndex":81,"id":"exchange-035"},{"speaker":"林（宏）委員","kind":"質問","question":"清掃の仕事というのはこれでしょう。それを何で書くのかなという、はっきりしておかないと、事務もいるよとかがいろいろあるでしょう。自動車整備などもあるようだから、それは分かりました。雇上がありますよね。その民間に対してはこれはどういうふうに係わってくるんでしょうか。","respondent":"桑村人事課長","answer":"雇上車両につきましては運転手付きでまいります。清掃業務手当は、区の職員にその業務に従事したときの手当ですので、いわゆる雇上の職員の方は、その会社によるという判断です。","voiceIndex":83,"id":"exchange-036"},{"speaker":"林（宏）委員","kind":"質問","question":"分かりました。それから、もう一つ、し尿のほうですけれども、これは品川区だけが受けた仕事ですよね。清掃のごみ収集・運搬というのは２３区全体が受けたんだけれども、し尿に関しては品川区だけです。そうすると、これについて財調はどういうふうに捉えてくれるんですか。","respondent":"市岡企画財政課長","answer":"し尿の業務というのは、品川区の場合は中継施設なので、ほかの区でも収集というのはあると思うんですが、財調上は中継施設として通常の標準算定以外にこれを算定してもらっておりますので、損はないです。","voiceIndex":85,"id":"exchange-037"},{"speaker":"林（宏）委員","kind":"質問","question":"損得というか、きちんと持ち出しが多くならないというか、見てくれるというふうなことに理解しておきます。それから、２３区がそれぞれ収集・運搬をやっているんだけど、こういうふうに４月から区の職員が直接清掃作業に入っていくというのは、品川区だけですか。","respondent":"桑村人事課長","answer":"数区が検討しているというふうに聞いてありますけれども、やる可能性はありますけれども、条例提案をしているのは品川区だけです。","voiceIndex":87,"id":"exchange-038"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、形の上ではそれぞれの区が行くとなれば、同じ状況が生まれるわけでしょう。清掃事務所の仕事場でね、さっきいろいろ説明をされていたような。２３区それぞれが特殊勤務手当、不規則勤務手当を付けないで、そのまま区の職員が行くという可能性はあるんですか。","respondent":"桑村人事課長","answer":"もう一つは、その意味で一貫性は言い切れないところはありますけれども、議論の中で何が一番大きくなってきたかと申しますと、調整額の絡みで、特殊勤務手当として措置しなければいけないのではないか、その議論がかなり大きくなって。","voiceIndex":89,"id":"exchange-039"},{"speaker":"林（宏）委員","kind":"質問","question":"今清掃事業そのものが完全に２３区に移譲されたわけではなくて、一部事務組合という過渡期にあるので、いろいろあると思うんだけど、先ほど来、平成１８年からという説明をされているんだけれども、これについて２３区でどういう話し合いというか、課長会なのか、部長会なのかわかりませんけれども、ここには担当の課長がいらっしゃらないけれども、人事課長会では。","respondent":"桑村人事課長","answer":"正直言いまして、１年間かなりの回数をやりましたけれども、まだ現実的な案がなかなかできていないのが現状です。","voiceIndex":91,"id":"exchange-040"},{"speaker":"林（宏）委員","kind":"意見","question":"全部は読めないでしょうけれども、平成１７年度末について、何区がどういう考えを持って今やっているのかなというのが、判断材料になってくると思うので、出せる範囲でそういう情報も私たちに課長会の情報がいただければ、平成１７年度末に向かってのいろいろな品川区としての考え方をまとめていくのに役に立つと思うので、お願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-041"},{"speaker":"藤田委員","kind":"意見","question":"細かい話ですけれども、３ページの犬猫等動物死体処理手当が一頭１５０円になっていますね。これについて、我々はよく見かけるわけですが、蛙、ネズミ、この辺も全部この中に入るんでしょう。そのときに、見ていますと、１人で来るのではなくて、複数で見えるんですね。そうした場合に、１人の処理手当が出るのか、どちらか１人に絞りなさいというような形にするのか、どういうふうになっているのか。","respondent":"桑村人事課長","answer":"ご自宅のほうに伺って、２人で作業をすることもあろうかと思います。そのときの実際上の運用の規定が、都の職員がどういうふうに出ているか把握してございませんけれども、それにつきましても、私どもどういう基準でお支払いするか、しっかり考えていきたいと思います。","voiceIndex":94,"id":"exchange-042"}]},{"id":"topic-04","title":"４の議員提出第１号議案、品川区区民参加条例","agenda":"４の議員提出第１号議案、品川区区民参加条例","exchanges":[{"speaker":"桜井委員","kind":"提案","question":"議員提出第１号議案、品川区区民参加条例について、提案をしたいと思います。委員長にもご理解いただいております。ちなみに、議会制度が今あるわけですから、さまざまな意見を聴取していくという手法と同時に、議会での条例を決めていくという点については、住民の意思を議会も十分反映させていくというところで、それを区長としてもちゃんとしていくという流れを考えているところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-043"},{"speaker":"林（宏）委員","kind":"提案","question":"提案された桜井委員にお尋ねします。第１条で、「区民が主体的に区政に参加するために」と書いてあるんだけれども、これと選挙はどういうふうに関係しますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":103,"id":"exchange-044"},{"speaker":"桜井委員","kind":"質問","question":"参加の中には参政権というか、当然明記されています。地方でももちろん選挙を通じてしたり、だけども、例えば選挙をする場合は公約で有権者と結びますね。ですから、そういう点では直接そこの問題に係わっている、そういう区民の皆さんの意見を聞くということは矛盾はしないというふうに思っているわけです。すべて選挙によって信託されたというふうにはいかないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-045"},{"speaker":"林（宏）委員","kind":"質問","question":"これがないと、議員のやっている仕事というのが満たされていないというふうに、あなたは否定をするわけですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-046"},{"speaker":"桜井委員","kind":"意見","question":"そういうことはございません。もちろん選挙は、広く有権者に問いかけて判断をしてもらう。それは私たちとしては、今の優れた制度だと思います。その問題と、ある１点の事柄、例えば中央公園のそうした問題について、別に選挙で問うているわけではありませんから、そうした問題について区民の意見をいろいろな形で政策に反映していくという、そういう手法の一つとして考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":106,"id":"exchange-047"},{"speaker":"林（宏）委員","kind":"提案","question":"そうすると、例えば今の話だと、行政執行機関から提案されたのを一つ一つやっていかなければならない。その辺の現状というのは否定はされてはいないんだと思いますけれども、どういうふうに捉えたらいいのか。自分たちの、主に賛成、反対というと、今提案されているあなたたちが反対に回ることが多いじゃないですか。それについて物足りないから、こういうことをやろうというふうに考えるのと違いますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":107,"id":"exchange-048"},{"speaker":"桜井委員","kind":"質問","question":"品川区でも、今ご紹介したように、３０を超える審議会がありますね。ですから、そういう審議会で議論をされるという、それも一つの大きな形だけれども、それだけにとどまらない、直接関係者の意見を聞くという、そういう手法として、どんな場合においても住民参加を明確化するという、そういう趣旨ですから、必ずしも最初から問題が反対、賛成というところから出発するのではないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-049"},{"speaker":"林（宏）委員","kind":"提案","question":"そういう仕事と相矛盾しないですか。僕は矛盾すると思っているわけ。だけど、こういうことを提案をされてくるということは、矛盾しないというふうにお感じになっていらっしゃるわけですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-050"},{"speaker":"桜井委員","kind":"意見","question":"さっきから言うように、例えば私ども条例で４２名議員がいますし、人口で言えば、9,０００人に１人、高いですね。だから、基本的には議会の議決で物事を決めていくというのは、それは当然ですけれども、決めるにあたって、どれだけ区民の声を吸収して反映されるかという、そういう制度としての考え方というものを持っているんですけれども、議論がかみ合っているかどうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":110,"id":"exchange-051"},{"speaker":"林（宏）委員","kind":"意見","question":"例えば審議会なりをつくったとしても、３２万人が直接話し合う直接政治はできないわけですよ。そこも選ばられた人ですね。どこも選ばれた人という形をとらざるを得ないわけですよ。そういう形の中で議会というのが機能していないならば、あえてこういうことで必要なものを随時つくっていくという考えになるのはいいんだけれども、僕は品川区議会というのはしっかり機能していると思っている。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":111,"id":"exchange-052"},{"speaker":"桜井委員","kind":"意見","question":"さっき言ったように、条例の性格ですけれども、いろいろな政策をつくるにあたって、現在審議会がありますね。審議会にしても、さらに住民の意向等を汲み尽くしていくのかということで、今まではあまり公募という形をとっていませんね。だから、必ずしもそのことと住民参加条例が、議員の役割を否定するというのは、ちょっと角度としては違うのかなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":112,"id":"exchange-053"},{"speaker":"林（宏）委員","kind":"質問","question":"そこの一つのことをとるならば、要綱なり、委員会、審議会なりで決めていけば、「基本的」とおっしゃるから、基本的にはそれでいいわけです。これは全体のことを取り決めようとしているわけですね。あるいは公開にしても、公開できるものはしていこうという方向にある。それなのに、なぜあえてこれが必要なんですかということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-054"},{"speaker":"塚本委員","kind":"質問","question":"引き続き伺います。区政というものがどう捉えられているかというのは、うしろのほうで分かるわけですけれども、どうも腑に落ちないのは、区政は区長だけがやっているような捉え方でものを言っている。区政に参画するんだったら、議会も区政の両輪ですから、議会の活動に対して、区民は今以上にどうやって参加するんだという問題意識が全く欠落しているように思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-055"},{"speaker":"桜井委員","kind":"質問・要望","question":"塚本委員が指摘されたのは基本的なことだと思うんです。最初、私たちの問題意識として、基本条例というか、塚本委員もご質問された、基礎的自治体のあり方というそこにかかると思うんですけれども、基本条例という、いわば条例の上位というのが、そういう考え方があると思うんです。だから、今回はそういう到達点のところでご了解いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-056"},{"speaker":"塚本委員","kind":"質問・要望","question":"区民参加条例という、こういう表現でいいかどうかはともかくとして、主人公である区民が区政に責任を持って係わること、そのための変えるべきものは変えるということは大賛成ですけれども、今指摘したように、根本的に片方が欠落しているという指摘をせざるを得ないということが一つ。そのことについてお答えいただきたい。第７条、区民投票と書いてありますけれども、これは住民投票とどう違うのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-057"},{"speaker":"桜井委員","kind":"質問","question":"第５条の前段ですけれども、すべて一義的に公開しなければならないというふうには言っているわけでないんです。前段で、原則とする。ですから、すべて一律にというのは考えられていません。〔「２の問題です」と呼ぶ者あり〕１が、２として、執行機関ということになっておりますから、第５条の精神はそういうことです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-058"},{"speaker":"塚本委員","kind":"質問","question":"附属機関の会議についてを２で規定しているわけですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-059"},{"speaker":"桜井委員","kind":"意見","question":"はい、そうです。区民投票の関係ですけれども、確かに住民投票ということが一般的にはされていまし、私たちも住民投票ということも、名前としてはあるかなと思ったんですけれども、ただ、これまで、例えば何々市という場合に、市民投票となるし、だから、使い方としてはいろいろ区を主体的に考えているところで、性格は、一般的には住民投票ということと同じです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":119,"id":"exchange-060"},{"speaker":"桜井委員","kind":"提案","question":"現状は、品川区の場合には、制度化はされていません。今でももちろんそういう条例を、例えばさっき紹介したように、準公選をやるときには区長を選ぶ区民投票ということで、条例提案をしていますね。それに基づいて要綱を決めてやっているわけですから、それは十分にできるけれども、そういうことが必ず主眼としてありますというふうに、条例として明記したということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":121,"id":"exchange-061"},{"speaker":"塚本委員","kind":"質問","question":"法律の中で、技術的なことも含んでいるので、理事者に伺いますけれども、第５条の本文と２のところの関係では、２のほうが大きな規定をするような気がするんですけれども、これはどういうふうに理解していいかということ。そういうことは、法解釈といいますか、条例を決めるときに、解釈するとどうなっていくかということをお伺いいたします。","respondent":"小野（孝）政策担当課長","answer":"今、塚本委員のお尋ねの、第５条の２項についての解釈ですけれども、私どものほうも、「執行機関は」ということになっておりますので、附属機関のみではなくて、その他の会議についても言及したものだというふうに解釈をいたしましたけれども、先ほどの提案者のほうのご説明では。","voiceIndex":122,"id":"exchange-062"},{"speaker":"土井委員","kind":"質問","question":"区民投票、住民投票の関係ですけれども、住民投票の具体的な条例等をおつくりになったところは概ね何らかの形で、完全に二分をするような課題、問題が提起をされて、それに対処するためにおつくりになったというのが大部分だというふうに思うんです。それが１点。質問の部分はありますけれども、直してくださいとしか言いようがないので、やめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-063"},{"speaker":"藤田委員","kind":"質問・要望","question":"投票できる資格者は中学生のところもあれば、１８歳、１９歳というところも、いろいろありますけれども、第７条の２で、「投票に付すべき事項」、この事項が、どういう事項があるのか。確かにさっき言いましたが、行われているんですよ。投票に付すべき事項というのは、どういう議題があったときになるのか、その判断はだれがしていくのか、その辺をちょっとお聞かせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-064"},{"speaker":"桜井委員","kind":"意見","question":"新聞紙上をにぎわせている住民投票というのは、原発の問題とか、そういうふうになっているのが最近多いですけれども、しかし、私どもの調べた１３を超えるところでは、必ずしもそうではなくて、多摩市の場合にも特段そういう大きな論点があってというわけでもないし、紹介した宝塚市も、二分したような論点があってやっているということではないんです。ただ、たとえばどうかということで申し上げました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":127,"id":"exchange-065"},{"speaker":"桜井委員","kind":"意見","question":"具体的に、例えばこれは住民側から請求が出されてやる場合もあるし、あるいは議会の意思として、前に品川区でも行った、準公選みたいな、そういう事例もありますけれども、第７条で規定をしているのは、広く区民の意思を聞く必要があると判断した場合は、この規定は区長というふうになっておりますけれども、それは全体的な問題として、地方自治法からは、住民からもよく意見という。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":129,"id":"exchange-066"},{"speaker":"川西副委員長","kind":"質問","question":"あるいは、都市計画審議会に私も参加しているんですが、一つのルールに基づいて公開制となっている。もう一つは、かなり専門性を要すると。そういうのの分類というのはされたのでしょうかというのが一つです。それから、今、区の制度の中で、全然違うかもしれないけれども、広聴員制度は、住民がどのように参加意識を持って、どういうふうに効果を得ているのか、調査をなさったのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-067"},{"speaker":"桜井委員","kind":"意見","question":"確かに、先ほど申し上げたように、附属機関の中では、プライバシーの問題とかありますから、一律にすべて公開というふうには考えておりません。原則は公開ということで、委員会の性格もありますから、それはこれまでもやっている。ただ、今までの委員会がそのことを論議して、この委員会は公開が必要かどうかというところまてはやっていない。そういうことで考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":131,"id":"exchange-068"},{"speaker":"藤田委員","kind":"意見","question":"これを実施する場合、例えば区議会議員選挙の場合、地方統一選挙の場合、都議会議員選挙もありますけれども、それはかなり予算がかかっているけれども、これをもし１回やる場合、どれくらいの予算をかけてやろうとしているのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":132,"id":"exchange-069"},{"speaker":"桜井委員","kind":"質問・要望","question":"それは、住民投票のテーマによると思うんです。住民投票のテーマ、品川区で言えば、以前やった準公選の場合は幾らかというのは私も教えていただきたいんですけれども、そういう場合の予算措置は当然ながら議会の議決を要しますから、一律に、この条例を決めたからといって、定数の予算は幾らかという性格ではないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-070"},{"speaker":"藤田委員","kind":"質問","question":"小学校以上、品川区ではどれくらいの人数がいて、どれぐらいの予算を立ているかという、テーマ、例えばまちづくりをやるとすると、大変な予算がかかっていくんじゃないかなというふうに思うんですけれども、例えば小中一貫校でやる場合に、予算的にはどのぐらいのものをかけていくんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-071"},{"speaker":"桜井委員","kind":"意見","question":"私は区民投票を目的としているわけではなくて、実際に、いろいろ審議会をつくって、例えば小中一貫校をやるとすれば、広聴会をやるとか、いろいろな意見の聴取もありますね。住民投票については、幾つかの事例があって、実践もあるけれども、まだきちっとした到達点に、問題点もあるし、すべて住民投票で決するということはいいと思っておりません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-072"},{"speaker":"塚本委員","kind":"意見","question":"住民投票ですけれども、たしかアメリカの選挙では、それぞれの議員を選ぶ選挙のときに、いろいろな意思を幾つか並べて、それをどう思うかという投票をさせると思ったんですけれども、そういうことに関して、制度的にこうなっていますよというようなことが分かるかどうかということ。こういうときには大事な議論で、これが通ったときに、皆さん方は大変なことになるので、疑問がないかどうか。","respondent":"小野（孝）政策担当課長","answer":"アメリカの議会の中でどういう制度になっているかということについては、私も存じませんけれども、いろいろな個々の政治的な課題、あるいは政策的な課題というものを、候補者が明確に明示をして、あるいは対比をさせる意味で表のような形にして。","voiceIndex":136,"id":"exchange-073"},{"speaker":"塚本委員","kind":"質問","question":"電子投票が視野に入ってきたという時代になっているわけですから、それぞれの争点というものを整理して、問うという、それは直接直ちにこうしなければいけないということではないでしょうけれども、住民の意向を聞くということはだんだん考えなければいけない時代にきているのかなということを思いますけれども、このことに関しては。","respondent":"中尾根企画部長","answer":"そうしますと、本当に民を取り上げてやるということが重要であるとすると、そのことの多様なパイプを持って、そのことを吸い上げていくことが重要なのではないか。そういう手法の一つであるということには否定はできませんけれども、そのような感想を持っております。","voiceIndex":138,"id":"exchange-074"},{"speaker":"桜井委員","kind":"質問","question":"ですから、区のほうもＮＰＯとか、多様な形で区民の皆さんの参加というか、進めていることは私も承知しておりますけれども、より積極的に、政策についても、区民の参加というところを確立する必要があるんじゃないかというふうに、あえて意見を申し上げたいと思います。そういうことで、趣旨を申し上げましたので、論議いただいたことを感謝して、なお、ご賛同いただければありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-075"}]},{"id":"topic-05","title":"平成１５年請願第１号、「武力で平和は築けない！」イラク問題の平和的解決を求める意見書採択に関する請願","agenda":"平成１５年請願第１号、「武力で平和は築けない！」イラク問題の平和的解決を求める意見書採択に関する請願","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"ですから、積極的にアメリカをグループとするところと、フランスを中心とする、そういうところでそれぞれの報告がありましたけれども、アメリカ、イギリス、スペインの国内を見ても、例えばイギリスにしても、イラク攻撃については反対という意見が５２％を占めており、アメリカにおいても、イラク攻撃については、査察にもっと時間を与えるべきだというのが５９％を占めているんですね。","respondent":"古川総務課長","answer":"前段は省かせていただきますが、そののときの対応につきましては、「政府が方針を決定すべき事項であると考えますので、区長としての見解は差し控えします」、こういうことで区長の答弁をしています。","voiceIndex":150,"id":"exchange-076"},{"speaker":"桜井委員","kind":"質問","question":"政府の方針を決めるべきですけれども、政府の方針に対して、いろいろな世論もありますね。政府としては、アメリカのをグループとした決議について容認という形ですよね。しないというのも一つの対応かもしれないけれども、やはり意見を述べるということもありだと思うんですけれども、それは政府のやっていることについても了とするというふうな理解なんでしょうか。","respondent":"本間総務部長","answer":"先般の本会議場で区長がご答弁をさせていただき、今、総務課長がそれを再度確認の意味で申し上げたとおりが、品川区の見解です。","voiceIndex":152,"id":"exchange-077"},{"speaker":"塚本委員","kind":"意見","question":"大変な長文で、大した文章力だと思いますけれども、背景認識については、いかがなものかなと思う感じがあります。アメリカが北朝鮮問題に対して、日本が核武装をしそうだよということをアメリカが示唆しているという意味なのか、このままだと意味がとれないんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":154,"id":"exchange-078"},{"speaker":"塚本委員","kind":"質問","question":"日本はアメリカの植民地でしょうか、こういう認識の仕方は非常に自らを卑しめる表現の仕方で、いかがかなと。それから、アメリカの覇権主義の認識はこういう認識の仕方があるんだということは分かりますけれども、それの背景をすべての人が賛同できるかなというと、またこれは疑問があると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":156,"id":"exchange-079"},{"speaker":"川西副委員長","kind":"質問","question":"今おっしゃられたように、長文ですから、部分的にとってみますと、解釈も多少はあるのですが、全体を通して私は趣旨として生かしたいと思います。趣旨採択ができるのかなというふうに、意見を申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":157,"id":"exchange-080"},{"speaker":"藤田委員","kind":"意見","question":"この請願の主旨を生かして、趣旨採択をお願いしたいなということと、我が党の神崎代表が今日訪米しているんですが、アメリカの高官とか、国連の事務総長等との間で対談が予定されているということで、平和的解決に向けて、我々としては期待を持っているわけですけれども、そういう面で、２月２８日に区議会として全員一致で決議をしましたので、区議会の意向は明確になっておりますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":158,"id":"exchange-081"},{"speaker":"土井委員","kind":"質問","question":"私のここを言っているところの趣旨だったんだと、そっちの人が言い出すと、また言の葉を捉えての話になってしまうので、私自身が思うには、せっかくまとめた区議会の決議という重いものがあるわけですから、あまりここで趣旨が賛成だの、反対だのという話をやり過ぎるとますますおかしくなってしまうのではないかというふうな懸念を持っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":159,"id":"exchange-082"},{"speaker":"桜井委員","kind":"意見","question":"私は採択でいいと思うんですが、皆さんが趣旨と言うならば、それで賛同いたします。請願の主旨の５行というのは全面的に賛意を表したいというふうに思います。","respondent":"伊藤委員長","answer":"今日、結論を出すか、出さないかというところから始めていって、その次に、内容を、今話があったような方向で進めていくかということを意見集約していきたいと考えていますので、まずは本日継続するか、もしくは結論を出すかということのご意見をお願いいたします。","voiceIndex":160,"id":"exchange-083"},{"speaker":"林（宏）委員","kind":"提案","question":"提案を下げたいきさつがあるから、改めてここで意見書を出すということをやると、議会運営委員会の中の議論があれになってしまうので、どう扱っていくのかなと。それはもう全部の人が思っていることだけれども、議会として、今ここでやらなければいけないのは、意見書を出してくださいという請願がきたのを、どうするかという、平和というのは当たり前のことで、それに苦慮しているんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":162,"id":"exchange-084"},{"speaker":"川西副委員長","kind":"質問","question":"今の議長のご心配からしますと、趣旨採択で取り扱って、ここで決まった場合、必ずしも決議と意見書の矛盾点を考慮したら、趣旨採択の場合は、意見書を出さなくてもいいんじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":163,"id":"exchange-085"},{"speaker":"土井委員","kind":"質問","question":"私も非常に苦慮しながらお話ししたんです。それをただ手法的にイエスか、ノーか、採決をするのか、しないのか、継続にするのかということであるとするならば、その答えしかないとするならば、私の場合は継続と言うしか、議論をしない方法はそれしかないんですから、そうと言わざるを得ない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":165,"id":"exchange-086"},{"speaker":"藤田委員","kind":"質問・要望","question":"先ほど言いましたように、意見書を出す、出さないというのは、私としては、意見書は出さないで、既に議会の意思として決議がされているわけですから、ですから、先ほどの最初から５行目だけの趣旨を採択していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-087"},{"speaker":"林（宏）委員","kind":"提案","question":"今、取り扱いについて議論をしているわけで、土井委員から一つの提案があったわけです。考え方としては、「継続をするしかない」という、一つの発言があったわけです。それから、趣旨採択というのは、今日やるか、やらないかはわからないわけね。まだ言っていないから。今は継続ということだけが提案されているわけです。今日、決をとるというのはだれも言っていないんです。継続という提案があった。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":169,"id":"exchange-088"},{"speaker":"桜井委員","kind":"提案","question":"先ほど来、複数会派からも趣旨採択という意見ですし、当然今日審議しているわけですから、今日結論を出すということを提案いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":171,"id":"exchange-089"},{"speaker":"塚本委員","kind":"提案","question":"土井委員から大変含蓄のあるご提案がありましたので、私どもは土井提案に賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":172,"id":"exchange-090"},{"speaker":"藤田委員","kind":"質問","question":"うちとしては、ある一定の結論を持ってきているんですけれども、これだけそれぞれの委員の考えが違うわけですから、一旦休憩をしてもらって、鶴議員が紹介議員になっているんです。だから、今大いに悩んでいるところがあるんです。ですから、皆さんの意見が分かれているものですから、一致していれば一番いいわけですけれども、休憩をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":173,"id":"exchange-091"},{"speaker":"桜井委員","kind":"質問","question":"ということは、明日また審議をするという前提でしょうか。それがはっきりしないと。もし明日で事実上審議をしないとなると、廃案という形になりかねないという点では、私は今大変重要な時期だけに、紹介議員にはなっていませんけれども、この請願は今日趣旨採択をすべきだというふうに主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":177,"id":"exchange-092"},{"speaker":"川西副委員長","kind":"質問・要望","question":"私は、そういう点からしますと、これを継続審議にして、時期的に効果がどれほど、今と、新しく選出された議会との関係に持ち込んでしまうというような、こういう方はもう一回出されるかもしれないから、自然廃案になっても、出す可能性もありますから、それはそれでいいんですけれども、そういう可能性がありますから、できるだけ趣旨採択したいというのが気持ちですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":178,"id":"exchange-093"},{"speaker":"桜井委員","kind":"質問","question":"今の手続の来期という話ですけれども、委員会でのそういう意向ということについては、それとして議事録に残るわけですけれども、手続はどういうふうになるんですか。来期って、当選した後の委員会構成はまた違いますし、その辺の意味がよくわからないんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-094"},{"speaker":"塚本委員","kind":"意見","question":"手続といいますか、品川区議会は団結しているということは事実ですから、総務委員会の意思を議長に伝えて、しっかりと、もちろん議事録には残っておりますし、また、議員も、８割か９割は再選につながっていくわけですけれども、建前上は切れると言わざるを得ない。最後に総務委員会はこういう意思を持ったということの事実は残るということだろうと、私はそういうふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":184,"id":"exchange-095"},{"speaker":"桜井委員","kind":"質問","question":"次回の、進むなり、継続するものというのは、ちょっといかがなものかと思うんです。それぞれの会派があり、それぞれの委員がいますし、論議もちゃんと行うわけですから、それはその会派なり、議員のところで、継続的に論議をしていくというのが筋だと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":185,"id":"exchange-096"},{"speaker":"土井委員","kind":"意見","question":"それでいいというふうに発言しておかないと、何かがあってはいけないので。確かにこの委員会で一定のものができましたので、次期総務委員会で、ぜひ私たち１年間の成果というものをご理解をいただいて、場合によっては、そこで再度若干の論議もしていただいた上で、その委員会の総意としてまたやっていただけるということに期待をしたいというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":187,"id":"exchange-097"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1610#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":56869,"voices":190}},{"id":"h15-20030304-6","meetingId":"h15-cm03","date":"2003年3月4日","dateIso":"2003-03-04","committee":"区民委員会","time":"午前１０時０３分～午前１１時５８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"三上委員","kind":"質問・要望","question":"ところが、葬儀屋とすれば、通常の葬儀の流れの中でやっている話だということでの意見の調整というものがされていかないと、そこらあたりの不満が残るようなことになると大変問題になるのかなと、こういうふうに考えるわけですから、そこらあたりが、委託業務の中できっちりとそういった問題が打ち出しがされるのか、されないのか。そこらあたりをちょっとお知らせをいただきたいと思います。","respondent":"宮地区民課長","answer":"こちらにつきましては、基本方針の中で施設運営としまして、不明朗な慣習の排除ということを掲げております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"三上委員","kind":"質問","question":"給与の体系の中に、民間の場合でもそういったものが入っているという、あてにして、それで低い給与水準に抑えられているのかどうか。こういうことを考えていかないと、それにならった形で広域斎場も、それは違いますよと言った場合に、そこの業務を委託しようとしたけれども、受け手がなかったなどという話になりかねないですよね。そこらあたりの話し合いはちゃんとされているんですか。","respondent":"宮地区民課長","answer":"これからプロポーザル方式で仕様書をつくってまいりますけれども、過去のそういった給与の中に含めていたということも含めまして、これはないんだということを事前の仕様書の中で明確にするという方針でいきませんと、話のすれ違いが出てきますので。","voiceIndex":7,"id":"exchange-002"},{"speaker":"三上委員","kind":"質問・要望","question":"プロポーザルの、公にされていくわけですから、そこらあたりの段階できちっと当委員会にも報告をしていただきたいということをお願いしておきたいと思います。それから、案内標識についてですけれども、高速道路をおりた時点での案内板というのは考えられておりますか。","respondent":"宮地区民課長","answer":"今回は、港区側から来ますとそういったことが考えられるんですけれども、品川区内と大田区内の中で、あくまでも環７、第一京浜を中心とした案内表示になっておりますので、ここら辺は国道の管理事務所等と検討をしてきた結果ですので、今のところは。","voiceIndex":9,"id":"exchange-003"},{"speaker":"三上委員","kind":"意見","question":"そうじゃないんです。そういうふうな、ちょっとしたところの、案内板にしても、右左とか、都心だとかということでなくて、行った先でＵターンするとか、逆に右折する場合はこうですよという、そういうような丁寧な案内板みたいなものをつくっていかないと、一つ、二つつくったって、結局何にもならなくなってしまうということで、苦情が今まで起きているわけです。","respondent":"宮地区民課長","answer":"今委員のほうからご意見がありましたので、私どものほうは、事務局にその旨をお伝えするという形になろうかと思いますけれども、そういうことを要望としてお伝えしていくということで、よろしいでしょうか。","voiceIndex":11,"id":"exchange-004"},{"speaker":"本田委員","kind":"質問","question":"ですから、そういう意味では、この交差点のところに標識があったほうが親切かなというふうに思うんです。それが１点。そういうケースもあり得ると思います。どっちかに置いておいたほうが親切かなというふうに思います。","respondent":"宮地区民課長","answer":"今いろいろご意見をお出しいただきましたが、ここで付ける、付けないという話はちょっと申し上げられないので、私どもで思ってもみない、いろいろな、こういうところは不便だというのは気がつかない場合もありますので、もしこんなところにというご意見がありましたら。","voiceIndex":13,"id":"exchange-005"},{"speaker":"本田委員","kind":"質問・要望","question":"競馬場の入口のところは、私に言わせれば、環境から言えば、なくたっていいんじゃないか。それよりも、なぎさ会館のところの交差点、もしくはさっき言ったような、ポンプ所に新しくつくっているところの交差点のほうがいいかなというふうに思うんです。これは要望しておきます。それから、オープンの日程とか、それはいつ頃になるんですか。","respondent":"宮地区民課長","answer":"使用料につきましても、条例上で制定してくるのが、７月から８月ぐらいになってこようかと思いますが、既に予算面では見込みということで検討しておりますので、前回、決算特別委員会の中でもちょっとお話しさせていただきましたけれども、骨壺を含めた火葬料金。","voiceIndex":15,"id":"exchange-006"},{"speaker":"本田委員","kind":"確認","question":"そうしますと、７月、８月を予定している組合議会の中で、そういう詳細なことについては確認をするというふうに捉えてよろしいんですか。","respondent":"宮地区民課長","answer":"一応事務局の予定ではそうなっております。臨時会等のことも考えられますので、確実とは申し上げられませんが、今、直近であります組合議会が７月から８月ということになっておりますので、その中でというふうに考えております。","voiceIndex":17,"id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"意見","question":"前回のときも、交通アクセスで路線バスの話が出ておりますけれども、あの辺は今の段階ではどうなっておりますか。","respondent":"宮地区民課長","answer":"今の段階では、調整を積極的に進めているところですが、一番のところが大森側にあります大田スタジアム行が、斎場の開設時間に合わせまして、大幅増便ということで今話を詰めているところです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今までお話しした中の、本田委員のおっしゃった表示板ですけれども、確かに僕もあれは要らないなと思ったんです。見ると、３基で1,２００万円ぐらいの予算を組んでいる。一施設４００万円ぐらいかなと。走っていると、天王洲方向から来たときに、ぐるっと回るんですけれども、広い意味で、もっと広域的にもありますけれども、もうちょっと区内として考えられないだろうかなというふうに思います。","respondent":"宮地区民課長","answer":"分かりました。区内全体を見た場合の、品川区として考えられるところもありますので、もう一度検討をさせていただきたいと思います。","voiceIndex":21,"id":"exchange-009"},{"speaker":"三上委員","kind":"質問","question":"八潮団地の中にはどうするとかという団地の人たちの要求というのはあったんですか。","respondent":"宮地区民課長","answer":"それはかなり以前の説明の中でも、地元の八潮地区の中は車を通さないということでお話をさせてきた経過があります。ですから、通り抜け交通のような形にならないように、私たちも十分配慮をしなければいけないというふうに考えてあります。","voiceIndex":23,"id":"exchange-010"},{"speaker":"三上委員","kind":"質問","question":"幾ら団地の中だからと言ったって、団地の中を規制しているわけでないでしょう。どういう表現で、「ここは団地以外の車両については一切通り抜けできません」という表示を、入り口のところで関所を設けてやっているんですか。やっていないでしょう。そうすると、そういったことについて、何の制限もなければ、入ってこないということにはならないでしょう。","respondent":"宮地区民課長","answer":"ただ、地元の方への説明は、特に葬儀の霊柩車だとか、いろいろありますから、そういうのが通過するようなのは、葬儀屋にも協力をお願いして、通らないようにと。","voiceIndex":25,"id":"exchange-011"},{"speaker":"三上委員","kind":"意見","question":"そうすると、大井清掃工場のほうだって、斎場、その先はこうですよとかという案内というのが必要ないのかどうか。だから、そういうことも含めて、来る人の立場で考えた案内標識というのはどうなのかということを、もう少し丁寧に考えてもらいたいなと思います。４００万円なんかかけなくたって。そういう工夫というのをもうちょっと丁寧にやった上で、丁寧に考えてもらいたい。それはお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"マイガーデンですけれども、これはいつ頃まで借りられることになっておりますか。今の話ですと、１年ごとにまた向こうへ貸してくれますかということで、継続していくんですか。","respondent":"宮地区民課長","answer":"今、契約の準備を進めているところです。","voiceIndex":33,"id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"当然ながら、そこには水利というか、水の出る場所とかも設置をしてあるんでしょうか。","respondent":"宮地区民課長","answer":"既に水道管は入っております。緑で着色してある部分の真下を通っておりますので、ここから分岐する予定で、足洗い場、手洗い場等をつくる予定です。","voiceIndex":35,"id":"exchange-014"},{"speaker":"松澤委員","kind":"質問","question":"区内の遊休地や公共空間に、これからもほかでもするということですけれども、どのような考え方を持っているのか。例えば次はどこをしようとか、ある程度の計画はあると思うんですけれども、その辺のところはいかがでしょうか。","respondent":"宮地区民課長","answer":"一応まちづくり事業部のほうと連携をしながら、情報がありましたら、即、見に行って、活用できないかどうか検討をしてやっていきたいと考えていますが、どの程度の効果と、ニーズがあるかも、これをやっていく中で考えていきたいというふうに思っております。","voiceIndex":37,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"凄い魅力的だなというふうに思うんですけれども、月額1,０００円でこういうふうなことができるとなったら、かなりニーズは多いんじゃないかなというふうに思うんです。要望が多かったら、どういうふうにして選んで、１２人というと、少ないですけれども、どうやって選ばれるのか、お聞かせいただきたいと思います。","respondent":"宮地区民課長","answer":"希望がかなり多ければ、さらにどこかでできないかという見方もしていく必要がありますので、それは今回のどのくらいニーズがあるかを把握した上で検討をしていきたいと考えています。","voiceIndex":39,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういうふうなのが進んだら、まちづくり事業部と連携ということでしたけれども、生ごみの堆肥化のほうの、リサイクルのほうとも連携しながら、どこかで生ごみのリサイクルを始めて、そして区民のマイガーデンのようなところで使って、それだと、どんどん区内に広がるというふうな形になると凄くいいなというふうに思うんですけれども、そこら辺のところはどうでしょうか。","respondent":"宮地区民課長","answer":"あちこちで生ごみのコンポスト化、堆肥化を伺っておりますので、実験的な段階とも聞いておりますが、既に社会福祉法人などでも生ごみをコンポスト化、堆肥化して売っていらっしゃったり、いろいろしておりますので、いろいろなものを活用したいというふうには思っております。","voiceIndex":41,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区の事業としても生ごみをリサイクルの第一歩というふうな形で、ぜひ一緒にという形でやっていけるようなところで前進していっていただければいいなというふうに思いますので、要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-018"},{"speaker":"本田委員","kind":"質問","question":"区の遊休地、公共空地を畑にするということですが、当委員会でどうして取り上げるのか、何でまちづくり事業部でやらないで、区民委員会で取り上げたのかというのは、品川区内の中には遊休地といいますか、空地はいっぱいありますよね。区民委員会で取り上げて報告しているのは、どういう意味なんですか。","respondent":"宮地区民課長","answer":"ただ、事業部同士の連携というのも大事ですので、まちづくり事業部と区民生活事業部が連携するのも一つのいいことかなと考えていますが、必ずここでやらなければいけないというふうには考えておりませんので、きっかけが一つこちらにあったということで。","voiceIndex":44,"id":"exchange-019"},{"speaker":"本田委員","kind":"質問","question":"資材置場になっているけれども、ほとんど空き地というのが現状です。それならば、逆に、資材置場を一定程度確保して、歩行者の歩行部分をもう少し広くして、雨が降った日などは傘をさして、すれ違うのにぶつかるくらいですから、それで、マイガーデンをああいうところに、それこそ１３ではなくて、３０も４０も取れると思いますよ。どうでしょうか。","respondent":"太川区民生活事業部長","answer":"今委員がおっしゃいましたように、先ほどの課長の説明にもありましたが、いろいろこちらのほうで精査して、また検討した結果、区内の中でこれについて広げていくべきだ、また、そういう場所的なものもいろいろあるという、少しずつ情報は入っておりますけれども。","voiceIndex":46,"id":"exchange-020"},{"speaker":"本田委員","kind":"質問・要望","question":"説明は良く分かりました。ただ、どちらの所管でやるのか、規模、施策によって違うと思いますし、私は具体的に三共裏の遊休地といいますか、資材置場らしき格好にはなっているけれども、あれはいつまでもそのままにしておくべきではないというふうに思っておりますので、そういう場所がありますから、方針を明確にして、積極的に進めていただきたいという要望をしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"確認","question":"積極的にやってもらいたいという意味で、使う人にトラブルが起きないために確認ですが、水道をいつでも使えるということは、駐車場の中に水道が入っている、その辺の管理体制はどうしていくのか。それから、駐車場の中のガーデンですから、入口はそのまま入れるようになっているのかどうか。これは賃料等というのは今回はゼロということでよろしいんですか。","respondent":"宮地区民課長","answer":"それも含めての利用料1,０００円をいただくことになりますけれども、管理としては、この区域内は品川区が管理することになっております。駐車場は時間貸し駐車場ですので、車で来られた方はこの駐車場を使って、時間でお払いいただきます。","voiceIndex":49,"id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問","question":"生垣にしたということは、そこから入れるという意味ですか。それから、もう１点、水道料の問題でなくて、私が言っているのは、駐車場の利用者はここからは水道を使えないという状況で、トラブルを心配しているというのは、駐車場に来ている方が、そこから引っ張っていってやるような、それがまた後のトラブルに発生してくるんじゃないかという心配があるんですが、その辺はいかがですか。","respondent":"宮地区民課長","answer":"鍵付きですので、ここの利用者しか入ることができません。縦に見ますと、下側のところにつくるという形になります。この鍵を持っているのは、ここの区画利用者のみですので、駐車場に来られた方がここに入るということはできませんので、水も利用することはできません。","voiceIndex":51,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"山北町の区民農園ですけれども、私の知っている人で、それが生きがいになっているような感じで、休みというとそこに通って、野菜をいろいろつくるのが喜びになっているという方が友達にいるんですけれども、この需要というか、実際にどれぐらい希望者がいて、どうなっているのかというふうなところを教えていただけますでしょうか。","respondent":"宮地区民課長","answer":"それと、もうこれで終わりという人たちの空き枠の募集と、両方やっております。人気はあります。ただ、遠いということだけで、継続できない方たちも１年に何組か出てきますので、そこのところはまた抽選で入っていただくという形になります。","voiceIndex":55,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その抽選枠に対して、応募する人が足りないとか、そういうことはなくて、いつも応募枠よりもかなりの倍率というか、そこら辺のところもあるんでしょうか。","respondent":"宮地区民課長","answer":"人気は確かにありますので、多い場合は、またちょっと開発をして、少しまた枠をつくったりとか、中で融通をしておりまして、概ね希望は充足できるような形にはなっております。","voiceIndex":57,"id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"意見","question":"すばらしいのができると思いますけれども、最後に、小学校にＰＲというお話だったんですけれども、こういうＰＲは、本庁舎に来た方に、ここにも中小企業センターの方がやっておりますというのが何か分かるような方法、中小企業センターに行けば、確かに伝統工芸をやっていますという看板が出ていますね。そちらサイドでも考えて、向こうへ人の流れを持っていくような方法は考えられないかなと思います。","respondent":"市川産業振興課長","answer":"今ご提案をいただきましたことを、広報部門なり、施設関係なり、関係部署と打ち合わせた上で、実効性のあるものとして企画してまいりたいと思います。","voiceIndex":65,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"殊に、ここの場所で伝統工芸ができるかどうかわからないんですけれども、きゅりあんで伝統工芸のときにやりますよね。あのイベントは相当な人垣をつくっているし、チャンスがあれば、興味があって、行こうという方もいるんじゃないかなと思うんです。ぜひ活用していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-027"},{"speaker":"松澤委員","kind":"質問・要望","question":"中小企業センターが、旧勤労者福祉会館から中小企業センターになって、やっと中小企業センターらしくなるなという気がします。期待をしているということは、やはり人が入らないと、すぐ何でこんなのをつくったのなどと言われますけれども、そういう意味では、一生懸命頑張っていただきたいと思います。伝統工芸が移るということは、あった場所はどういうふうにしようと考えていますか。","respondent":"市川産業振興課長","answer":"今後の検討ということで、ご了解いただければと思います。","voiceIndex":68,"id":"exchange-028"},{"speaker":"松澤委員","kind":"質問","question":"あそこは前は、不特定多数の方が居座ってしまうということで、椅子を外したりしていましたけれども、今警備員が常駐しているんですけれども、すべてこういうような形で産業ＰＲコーナーというふうにできた場合、そんなに椅子とかを置くスペースもないと思うんですが、警備員そのものは今後常駐させるつもりですか。","respondent":"市川産業振興課長","answer":"先ほど説明をさせていただいた産業ＰＲコーナー全体をオープンしたときに、人の流れとか、ロビーの使用状態がどういうふうになるか、その辺を見定めた上で決めていくことだと思ってありますが、今の時点では何らかの形で警備員を配置をしておくということを考えてあります。","voiceIndex":70,"id":"exchange-029"},{"speaker":"三上委員","kind":"質問","question":"どうしても自分の行きたい会場はここだという意識がぱっと入った。もうそのまま行ってしまいましょうという雰囲気になるわけですから、入口の雰囲気というものを一工夫、二工夫をしていただいて、時間によっては，行ってみようかと、何なのかという思いを浮かばせるような入口のちょっとしたものを。そういう点での使いずらさというものを感じて今まできたんですけれども、そこらあたりどうですか。","respondent":"市川産業振興課長","answer":"特に駐輪対策については、現状でも、ご指摘になったようなことが、利用者の方からも窓口に苦情として寄せられることもありますので、これまでのところは警備員による有人対応ということで、自転車の整理、誘導ということで行ってまいりましたけれども。","voiceIndex":76,"id":"exchange-030"},{"speaker":"三上委員","kind":"質問・要望","question":"駐輪場というのは、やっぱりひっかかってくるかなと。あそこへ行ってみようかなと思っても、またああいう思いはしたくないなということで足が遠のくなどということがないように、中央公園で全体としての、間違いなく人が来るわけですから、そういう流れの中で駐輪場をどう確保するかということを、庁舎内を挙げて取り組みをしていっていただきたいと、お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-031"},{"speaker":"本田委員","kind":"質問","question":"今回こういう形でＰＲコーナーができるというのは大歓迎です。ご説明を聞きますと、ここに行けば品川区の産業が概ね商業、工業は分かるというようなことですから、この企画が区民にいろいろな意味で利用されることを期待するわけです。その辺いかがでしょうか。","respondent":"市川産業振興課長","answer":"確かに基盤技術の関係というのは、そのまま展示しても分かりにくいということは、ご指摘のとおりです。今回の展示は、六社ともすべて映像の展示説明をするということをお願いしています。","voiceIndex":79,"id":"exchange-032"},{"speaker":"本田委員","kind":"質問・要望","question":"商業コーナーでは商店街、品川観光のイベント掲示板というようなコーナーもあるようですが、この産業ＰＲコーナーは、中小企業センターそのものが品川区内の観光スポットの一つ、あそこに行くと、商業、工業、いろいろ分かるだけでなくて、大変おもしろいところだというようなイメージで区民の皆さんに利用をされるような形ができればなと考えていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-033"},{"speaker":"三上委員","kind":"質問・要望","question":"協力してくれた六社なら六社のうち、会社の中に、現実はこうだと、実習みたいな形で、１時間コースでも、２時間コースでも、そういうふうにしてやりますから、子どもたちを連れて、お父さん、お母さんたちもぜひ来てくださいというような、そういったところまでつながっていくような連携というものを深めていくようにしていただきたいなと、お願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-034"},{"speaker":"三上委員","kind":"質問","question":"ベンチャー創業支援事業ということで、これから何かやろうという人に対して、こういう事業はいいんじゃないかと考えていますが、そういう中にあって、先ほど創業支援ブースは１人から２人用というふうに、３人入ればいっぱいになるという、設備の中で、机、椅子ということについては、仮にぎゅうぎゅうでもいいから３人でもと言った場合には、その３人分の机、椅子というのは提供する形にはなるんですか。","respondent":"市川産業振興課長","answer":"机、椅子の配備ですけれども、これは基本の標準配備をするわけですけれども、標準配備というのは、基本的には１人でお使いになる対応ということで考えてあります。","voiceIndex":88,"id":"exchange-035"},{"speaker":"三上委員","kind":"質問","question":"それは大前提ですから、やってもらわなければならないでしょうけれども、簡易間仕切りにしても、間仕切りの方法というのはいろいろあると思うんです。ですから、そこらあたりももう少し工夫をしていただいて、どうせ使っていただくんですから、気持ちよく使ってもらえるように何とか工夫をしていただければと思います。","respondent":"市川産業振興課長","answer":"ただ、空間が空いてしまいますので、遮蔽性というのはあれですけれども、考え方としては、ご指摘になられたようなことを踏まえて考えていきたいと思います。","voiceIndex":90,"id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"意見","question":"前は３部屋にするというようなお話があったような記憶があるんですけれども、今、できるだけ広く、多くの方に使ってもらうという結果からの説明があったわけです。もう１点、女性起業家の話が出たときに、Ｊタワーのベンチャー創業支援を活用できるのではないかというお話がたしかあったと思うんですが、その辺の考え方は変わっていないのか、見通しとしてはどうなのか。","respondent":"市川産業振興課長","answer":"もう一つは、ある程度の広さを持ったオフィスを求める企業が、特に中堅どころの企業に多いということが、一定のニーズ調査の中で結果として出てまいりましたので、そういったことを考えた上で、最終的にオフィスを５区画、創業支援ブースを１区画という結論に至りました。","voiceIndex":92,"id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"意見","question":"もう１点、入居者募集が４月中旬からで、決定が５月下旬ですけれども、募集期間はどのぐらいあるのか、これは早くに周知しておかないと、期間がかなり短いんじゃないかと思うんです。企業がやるからには、それだけの計画性、資金性の問題も出てくると思いますけれども、これで間に合うのかなという心配があるんです。","respondent":"市川産業振興課長","answer":"今の日程構成としては、こういう形で考えてありますが、この中で、特にベンチャーオフィスの入居につきましては、８月の上旬から入居可能としておりますけれども、入居に約２カ月の猶予期間みたいものを設定して。","voiceIndex":94,"id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"意見","question":"入る前の段階として、事業計画をされているのに、募集が４月で、締め切りは５月というので、ちょっときつい面があって、そっちが心配だったんです。","respondent":"市川産業振興課長","answer":"ご指摘の点を踏まえて、この日程の構成につきましては検討をしたいと思います。","voiceIndex":96,"id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"せっかくそれだけいい事業を進めていく上で、空きのない形で、またせっかく入った方にはうまく仕事をやっていただきたいし、また、その仕事ができる範囲、品川区内の中にまた生かして、製造関係だったら、その材料だとか、下請け関係、品川区内の業者をさらに使うような、そこまでの指導もしていっていただきたいなと思います。これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"支援サービスというところで、専門スタッフを置くということですが、これは何人くらい、どこにどういう形で置かれるのか教えていただきたいと思います。","respondent":"市川産業振興課長","answer":"今予定していますのは、メインのコーディネーターを１名、そのアシスタントを２名ということで考えてあります。","voiceIndex":99,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１５の方が入るわけですから、いろいろな事業の方が入ってくると思うんですけれども、そういう方たちにはメインの方とアシスタント２名の方がいろいろな業種に対してコーディネートというか、支援をしていくというような形で、いろいろなアドバイスや、指導、助言というようなことができるような、そういう環境になるんですか。","respondent":"市川産業振興課長","answer":"おっしゃるように、入る方の業種によって、あるいは業態によって、どんな要請が出てくるかわかりませんので、このコーディネーターは、その辺の交通整理をした上で、自ら対応できる部分については、例えば簡単な翻訳とか、通訳のサービスといったものでしたらできるにしても。","voiceIndex":101,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それと、入居者決定というところですけれども、募集をされた方がたくさんいるとしたときに、決定をするというふうなところは、ただ単に、さっきのマイガーデンのように抽選というわけにはいかないと思うんですけれども、そこら辺のところはどういう形で決定していいくんでしょうか。","respondent":"市川産業振興課長","answer":"それと、募集が多数に及ぶ場合には、その中から選択をするわけですので、その企業の事業の発展性、もう一つは、先ほど鈴木真澄委員のご質問の中にありました、区内の在来企業の活性化にとってどういう効果を及ぼしてくれるかという点。","voiceIndex":103,"id":"exchange-043"},{"speaker":"本多副委員長","kind":"意見","question":"この１年間、区民委員会、南委員長を先頭に、委員、理事者、事務局の皆様に運営に大変ご協力をいただきまして、ありがとうございました。これからの品川区の区民生活事業と環境清掃事業、非常に幅広い取り組みをされておりますので、ますますの品川区政発展のために皆様のご尽力をどうぞよろしくお願いいたします。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":113,"id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2354#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":32361,"voices":114}},{"id":"h15-20030304-7","meetingId":"h15-cm03","date":"2003年3月4日","dateIso":"2003-03-04","committee":"厚生委員会","time":"午前１０時０５分～午後０時０４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須藤委員","kind":"質問・要望","question":"１点は介護人のほうなんですけども、社会福祉協議会が運営に当たるという形ですけども、その状況を皆さんいろいろ心配されているんで、民間に云々ということもあるようですけども、そのあたりの手当ての仕方がどうなっているのか教えていただきたいのと、それから２番目の級地加算で、６.８％から９.８％という数字をおっしゃられたんだけど、知的障害者の通勤寮というのが1,０４８で。","respondent":"日下部障害者福祉課長","answer":"その中でもいろいろ変更がこういう形で出てきますよということでご説明をさせていただきましたので、そういった意味では、個々にまたいろいろあればお問い合わせいただくということで、基本的にはそういう対応によりまして、十分にご理解をいただいているのではないかと。","voiceIndex":5,"id":"exchange-001"},{"speaker":"須藤委員","kind":"意見","question":"いろいろと今までもご尽力いただいているところなんですけども、いよいよ４月から始まるということで、障害者の方々はいろいろ不安感をお持ちになっているんで、できるだけ丁寧な対応をひとつお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"支援費のところは、私もなかなかよくわからないんでいろいろ教えてほしいんですけれども、以前ヘルパーの利用に上限をつけるとか、つけないとか、それがありましたけども、その顛末がどういうふうになったのか、今回何かには反映しているのかしていないのか、そこのところをちょっとまずお聞かせいただければと思います。","respondent":"日下部障害者福祉課長","answer":"そういう問題意識のもとで見直しの検討会、今後のあり方についての検討会を障害者の方にも参加をしていただいて、それでできるだけ早く今後の方向性を決めていきたいということで最終的な合意が得られたという経緯がありますので、私ども区のほうとしましても。","voiceIndex":8,"id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今の後半のほうからなんですけども、柔軟にするためにということで社会福祉協議会ということだと、私はちょっと発想が違うんじゃないのかなというふうに思います。ここのところをちょっと確認させていただきたいと思います。そして、障害者福祉課長のほうから、区のほうは現行サービス維持でということでお話があったんですが、そこのところをちょっともう一回確認しておきたいと思います。","respondent":"日下部障害者福祉課長","answer":"直近の状況でまいりますと、現在、特にホームヘルプのサービス関係が一番大きなやはりポイントになりますけど、これにつきましては、実は介護保険の段階でもいろいろケア協議会ということで、民間事業者の方、いろいろ一生懸命やっていただいているわけですけれども。","voiceIndex":10,"id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"何かの単価が高くなってくる、２３区高くなるというふうになると、今までの実際に使えていたサービスよりも現実問題頭打ちということが出てこないのかというのがちょっと、これは理屈の上でそういうふうになるんじゃないのかなという心配があるんですけども、そこのところはどんな感じなんでしょうか。","respondent":"日下部障害者福祉課長","answer":"それからこの関連で２点目のお尋ねなんですけど、頭打ちというお話がありましたけれども、これは先ほどもご説明させていただきましたように、この上限額を何のために設けたかといいますと、これは極端に言えば、いくらサービスを使っても、ちゃんと自己負担については。","voiceIndex":12,"id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"わかりました。それとあと最後なんですけども、今月の中旬ぐらいには、基準だとかあるいは受給者証の交付なんかをやっていきたいというふうに言っていましたけど、かなり国の動きもあろうかと思うんですけども、大体実際のところ、３月中のところでの手続というのはかなり現実的にやられるんでしょうか。","respondent":"日下部障害者福祉課長","answer":"実は、私どもも４月１日からスタートするためには時間がありませんので、これは全国どこの自治体も非常にあせっておりまして、今申し上げましたように、早くまず基準を決めていきたいと考えています。","voiceIndex":14,"id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"３点お伺いしますが、今障害者福祉課長からもご答弁あったんですけど、マスコミ等で知る限りでは、ほかの自治体はほんとうにこの制度が遅れているというか、間に合わないということがマスコミ等に出ているんですが、あらためて品川区は準備は万全ですかということが１点と、あと品川区でこの支援費制度をご利用する方は現時点ではどのぐらいいらっしゃるのか。","respondent":"日下部障害者福祉課長","answer":"それから利用者数ですけれども、以前申し上げました大体以前の私どもの試算で７００人ぐらいでしたけれども、ただ若干いろんな面で増えてきておりまして、これはなかなかどの時点でとらえるかというのは難しいところがありますけれども、現在の時点でいきますと７００名強と。","voiceIndex":16,"id":"exchange-007"},{"speaker":"藤原委員","kind":"質問・要望","question":"私も今年の初めに旗の台の心身障害者福祉会館であった新年会のときに、厚生委員会の委員として呼んでいただいて、この支援費制度については、ご家族の方も初めての制度なので不安があるというお話を承っておりますので、どうかほんとうに全力でご家族の方の不安がないようにやっていただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-008"},{"speaker":"金高委員","kind":"質問","question":"今の藤原委員とちょっと関連するんですけど、今まで区のほうに登録されていたということが、今度事業者として社会福祉協議会になるということで、社会福祉協議会も区と一体となって一緒に動いているわけですけども、その辺の連携のもとと、それからいわゆるシステムが変わるわけですので、そこについて先ほどの説明ですと７００人強の方がいると。","respondent":"日下部障害者福祉課長","answer":"ということで、先ほども須藤委員のご質問にお答えしましたように、社会福祉協議会と区が説明会を共催でやるという形をとっていますし、また何よりも当事者の方に対しましては、区のケースワーカーが１軒１軒訪問して、いろんな疑問点に答えておりますし。","voiceIndex":19,"id":"exchange-009"},{"speaker":"辻副委員長","kind":"確認","question":"ちょっと確認しておきたいんですが、この自己負担の２ページ目のところで、本人負担額の扶養義務者ということの考え方についてちょっとお伺いしたいんですが、それぞれのご事情があり、身体あるいは精神の障害、いろいろあるわけですけど、このアとイの２０歳以上の場合とイで、この父母の係わり方ですよね。","respondent":"日下部障害者福祉課長","answer":"ただ、二十を過ぎると、一応障害があるかないかは別にしまして、基本的には成人として自立をしたという形でとらえるのが本来のあり方だろうと、そういう考え方を基本にしまして、二十以上の方については父母が除外をされたということで聞いております。","voiceIndex":21,"id":"exchange-010"},{"speaker":"辻副委員長","kind":"質問・要望","question":"ですから、先ほどあったように、自己負担の上限、要するにどんどんサービスをやってあげていけば税がどんどん出ていくということで、これは介護保険が昨日もあったように、３２万人の人口のうち、６５歳以上は約５万9,０００人、６万人近くいて、そのうちに、要するに介護認定とかというのは8,０００人になってきて、そのうちに要介護になると約6,０００人ちょっとという感じになってくるんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-011"},{"speaker":"須藤委員","kind":"質問","question":"メンバーで、民生委員協議会というところとか学校関係が出ているんですけども、ここのメンバーは民生委員、児童委員というのは、何名ぐらい、またどういう基準で選ばれてくるのか、あるいは小学校の校長、中学校長というのも、どういう形で、それから私立幼稚園の園長というのもどういう状況の方が、その会の会長とか、そういう形で出られるのか教えてください。","respondent":"辻田児童課長","answer":"先ほど申しましたように、実践的な対応していく分科会、ここにつきましては、例えば民生委員の方でもいろんな具体的な児童虐待のケースに当たっているような方、また非常にそれに対して造詣の深い方、そういうような方を選任するようにお願いをしています。","voiceIndex":28,"id":"exchange-012"},{"speaker":"須藤委員","kind":"質問","question":"ですから、全体会の例えば民生委員協議会は、民生委員、児童委員となっているんだけども、民生委員は１３地区に分けてきましたよとかとなっているよね。","respondent":"辻田児童課長","answer":"それから分科会につきましては、いわゆる二重構造になっておりまして、上のほうで連携を強化していく、その下で実践的な協力体制のもとで分科会を運営するということで、ここは非常に実践的な部隊ですので、中には、例えば児童相談所の児童福祉士という方は同じ方で。","voiceIndex":30,"id":"exchange-013"},{"speaker":"須藤委員","kind":"質問","question":"その目的にかなうようにそれぞれの人材を選んでこなきゃいけないと思うので、例えば学校、校長といっても、年によって変わってきたりとか、いろんな流れがあると思うので、それが校長会の会長になるとか、民生委員なら民生委員の会長がそこに入っていきますよとかという、例えば医師会であれば、医師会の会長などとか、そういうふうなシステムになっているのか、医師会であれば。","respondent":"辻田児童課長、小沼福祉事業部長","answer":"失礼いたしました。各機関とも、全体会につきましては会長ないし会長にかわる方という方で選任をしていただいております。分科会につきましては、具体的な対応のできる方ということで、お願いをしているです。分科会の関係が出ましたけど、分科会につきましては年三、四回ありますけど、個々具体的なケースというようなことになりますので、そこの各選出させていただいた団体のほうから、実務等に精通しているというんでしょうか。","voiceIndex":32,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"先ほど児童課長のご説明で、児童虐待は増えているというご説明があったんですが、これは相談が増えているんでしょうか、それとも児童虐待自体が増えているんでしょうか。","respondent":"辻田児童課長","answer":"基本的にはどちらも増えているということなんですけど、児童虐待の品川管内ですね、児童相談所で持っている品川管内、児童相談所は品川区と目黒区と大田区を持っていますけど、品川管内でのこの３年間、平成１３年度までの件数でいきますと、１１年度が４０件。","voiceIndex":35,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"そこで虐待の、虐待と決める定義なんですけれども、しつけと虐待の違いというのは、どのように考えているんでしょうか。","respondent":"辻田児童課長","answer":"それで、どこで見分けをつけるのかというのは、これはやはり、児童相談所でも警察でも、児童虐待は犯罪ですから、非常につけづらいわけですけど、その辺はその状況状況によって判断していくしか基本的にはないのかなというぐあいに考えております。","voiceIndex":37,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問・要望","question":"それで、児童虐待の防止に対応するネットワークづくりということで、防止するためには、なぜ児童虐待をしてしまうのかという原因というか、要因があると思うんですけれども、主なものでいいので、協議会で出てきたことでいいんですけれども、児童虐待する側の主な、なぜやってしまうのかというのがわかれば教えていただきたい。","respondent":"辻田児童課長","answer":"そういうような一つ一つのことが複雑に絡み合って出てくる原因になっているということだというぐあいに考えております。","voiceIndex":39,"id":"exchange-017"},{"speaker":"藤原委員","kind":"意見","question":"そういうふうなフォローといいますか、どうやって児童のほうからは言わないと思うんですけれども、外見上に出ていない虐待はどのように把握していくのか。","respondent":"辻田児童課長","answer":"小学校に上がる前の子どもというのは、自らそれを訴えるということはなかなかできない。まして、３歳未満になりますと、何も動けない状況ですので、ほとんど発見は難しいという状況です。","voiceIndex":41,"id":"exchange-018"},{"speaker":"須藤委員","kind":"質問","question":"すみません、さっきいろいろ構成メンバーを聞いて何かと思っていたんですけども、今の情報を得たりなんかするときに、今行政は地域センターをコミュニティの核にしましょうということでいろいろ施策を組んでいますよね。そのあたりとの連携はいかがでしょうか。","respondent":"辻田児童課長","answer":"そういう中で、今後検討するべき事項かなというぐあいに考えております。","voiceIndex":43,"id":"exchange-019"},{"speaker":"須藤委員","kind":"意見","question":"新聞とかマスコミで来たときには、近所の方が最初に何かそういう雰囲気があるよということがあって、現実にいろんな問題が発生しちゃったということが報道されているんで、そうすると、何かおかしいんじゃないだろうかという時点で相談に行ったり、あるいは相談員がその現場に行かれたりということがいろんな面で早い予防になってこようかと思うので、その辺のところも組み入れられるように。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-020"},{"speaker":"築舘委員","kind":"質問","question":"ですから、民生委員はもちろん入っていますけど、民生委員というのは、どちらかといえば、主任児童委員が専門なわけでして、民生委員は高齢者の方々をケアしているわけですから、そういった青少年関係の方をもう少し入れていってもらいたいなということと、あと、分科会で、やはりもう少し現場の方を中心にしてもらいたい。","respondent":"辻田児童課長","answer":"こういう方を入れたほうがいい、ああいう方を入れたほうがいいという、いろいろあると思います。これもやはり分科会を運営していく中で、今後変更が必要であれば変更していくです。そのほかに、先ほど申しましたように、ケース会議というものもやっております。","voiceIndex":46,"id":"exchange-021"},{"speaker":"金高委員","kind":"確認","question":"１点確認させてもらいたいんですけど、１２年に成立しました児童虐待防止法、これはちょっと私の認識が違っていれば申しわけないんですけども、時限立法かなにかで出たというのがあったんですけど、これはどうでしょうかね。","respondent":"小沼福祉事業部長","answer":"期限が１５年、ちょっとそこのところが今具体的な年数まで記憶が定かじゃないんですが、５年ですか、１０年、たしか１０年じゃなかったかと思うんですが、具体的な年限はちょっと別にしまして、時限立法という形でたしか制定されたことは間違いございません。","voiceIndex":48,"id":"exchange-022"},{"speaker":"金高委員","kind":"質問・要望","question":"例えば、保育園、幼稚園でも、それぞれの保母、あるいは幼稚園の先生方がいるわけですけども、そういう中において、子どもたちと絶えず接触することによって、例えば身体的な形であれば、あざができていたとか、そういう形での状態がわかって、それで通報して初めて児童虐待がわかったとかという新聞報道も多々出ているわけでありますので、そういう分科会は分科会として年に３回ですけども。","respondent":"辻田児童課長","answer":"そういう中で、私どものほうも整合性のあるような形で、今後委員会、それからケース会議を進めていきたいというぐあいに考えております。","voiceIndex":50,"id":"exchange-023"},{"speaker":"宮崎委員","kind":"意見","question":"事務局が子育て支援センター内に置くというふうになっているんですけれども、この事務局の役割といいますか、具体的にどういうふうな仕事をしていくのか、そこのところの説明をいただければと思います。","respondent":"辻田児童課長","answer":"事務局の役割ですけど、まず各種委員会の運営、それからその中で決められたことの、それぞれの事務作業という形、そういうものが事務局の役割になってまいります。","voiceIndex":52,"id":"exchange-024"},{"speaker":"宮崎委員","kind":"質問","question":"委員会の運営というふうになると、基本的にはここで委員長が福祉事業部長、副委員長が児童課長といふうになっておりますけど、かなり事務局のところでの運営にかなり係わりが大きくなるだろうというふうに思うんですけど、具体的な、例えばそのときの議題とか、そういうものは当然事務局のところでつくっていくということなんですか。","respondent":"辻田児童課長","answer":"ただ、基本的にはそこでだんだんなれてくれば、事務局のほうに少しずつバトンタッチをしていくというようなこともこれからは考えてまいりたいというふうに考えております。","voiceIndex":54,"id":"exchange-025"},{"speaker":"宮崎委員","kind":"質問","question":"今、なれてくればどんどん仕事を渡してというふうにおっしゃったんですけども、私はこの児童虐待は、極めてプライバシーのところに踏み込んだ内容になっていくというものですから、私はやっぱり事務局というのは区自身がやったほうがいいというふうに思っているんですけども、そこら辺のところは、今の児童課長のご説明だと、福栄会に今委託しておりますけども。","respondent":"辻田児童課長","answer":"そのような意味で、全体的な相談機能を向上させるため、そしてその対応が正しくなされるためには、当然プライバシーの保護、それから処理の適切さ、そういうようなものが、今後十分な形で確保されていくように。","voiceIndex":56,"id":"exchange-026"},{"speaker":"金高委員","kind":"質問","question":"すみません。１点だけちょっとお伺いしますけども、一番最後の後見センター事業実績があります。その辺の、やはりお金のかかることでありますけども、実際にサービスを受ける方の出す分は出ていますけども、それ以外の間接的なそういう相談窓口になる方の弁護士、司法書士、税理士、当然費用的にはある程度高い分野があると思うんですけど、その辺をちょっとお聞かせ願いたいと思います。","respondent":"中川原福祉事業部副参事","answer":"やるんですが、法律的な専門的な相談とかは、この中の法律専門家の方に顧問的な形で相談を行うことで、相談経費としては成年後見センター運営経費の中に見ております。区から、これは事業費、補助費ですべていただいていますので、その間のやりくりの中で予算化しています。","voiceIndex":62,"id":"exchange-027"},{"speaker":"宮崎委員","kind":"質問・要望","question":"すみません、ちょっと法定後見コースと任意後見コース、具体的にちょっと入口がどういうふうに入っていくのかというのがちょっとよくわからなかったんですけども、そこのところをご説明いただきたいと思います。","respondent":"中川原福祉事業部副参事","answer":"ですから、在宅介護支援センターのケアマネージャーとか、民生委員とか、ご近所の方の相談から入ってこられる方がそういう方になります。","voiceIndex":64,"id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"最後の資料のところだと、いろいろ区を通じて入ってくるケースとか、いろいろあるんですけど、実際にはやっぱり近所の方のそういう相談もかなりあるんでしょうか。","respondent":"中川原福祉事業部副参事","answer":"近所の方というのは、今まで多いといいますか、今まで自分が何らかの関与をしてきて、自分が高齢化してきましてちょっと大変になってきたんで、だれか助けてくれないかなという、そういった形でご相談があります。","voiceIndex":66,"id":"exchange-029"},{"speaker":"須藤委員","kind":"質問","question":"基金をつくられるということなんですけども、この費用はどのくらいを見ていらっしゃるのか。それから、ちょっと細かい点なんだけど、支援員が特別養護老人ホームを訪問すると１回1,６００円、支援員が在宅訪問すると１回１時間2,４００円というような、数字のばらつきはどういう形で出てきているのかなというようなことが、ちょっとわからないので教えてください。","respondent":"中川原福祉事業部副参事","answer":"在宅の方の場合は、お一人のケースの方のお宅に伺いまして、１時間の中で、例えば貸し金庫にお預かりした通帳から生活費を引き出してお持ちして、そしてたまっている郵便物をちょっと一緒に拝見して、年金とか国民健康保険の手続を手伝ったり、そういったおうちにおいて。","voiceIndex":68,"id":"exchange-030"},{"speaker":"須藤委員","kind":"質問","question":"基金が1,０００万円プラスいろんな寄附があるということで、これはこういう費用でどんどん使っていかれるわけですよね。そうすると、1,０００万円の基金というのが毎回どういう形で、区のほうから補助でいくのか、その辺はどうなっているんでしょうか。","respondent":"中川原福祉事業部副参事","answer":"任意後見契約の場合も、本人が納得して契約してまいりますので、この基金については、当分安心のための装置といいましょうか、皆さんにこの制度を活用していただくのにあまり金銭的な抵抗感がないような、そういった仕掛けとして運営していくことで考えてあります。","voiceIndex":70,"id":"exchange-031"},{"speaker":"須藤委員","kind":"質問・要望","question":"大丈夫だよということで、基金の対象が報酬であるとか、サービス料金であるとか、いろいろ出てきているんで、そうすると、その辺の流れ方をきちんとしておかないと、どんどん足りなくなればサービスがどんどん出てくればその分費用がかかりますよという形になってこようかと思うので、そうすると、その辺も将来的なものを見ていかないと、区のほうの助成が進んでいきますよという形になろうかと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-032"},{"speaker":"築舘委員","kind":"質問","question":"細かいことで恐縮なんですけど、民生委員のＯＢといいますか、退任者の方が支援員になっているということですが、これは現職がやってはいけないというようなことがあるんですか。","respondent":"中川原福祉事業部副参事","answer":"現役の民生委員は、今高齢者相談員とか、いろいろ役割をお持ちですので、むしろこのネットワークの中で、民生委員としてお願いしたい部分がありますので、退任者の方は、そういったお役を離れてまだお元気でノウハウも持っていらっしゃいますので。","voiceIndex":73,"id":"exchange-033"},{"speaker":"辻副委員長","kind":"質問・要望","question":"今委員長から話がありましたけど、早い１年間だったなという感じがします。この１年間、さまざまな厚生委員会としての事業の中で、保健関係のほうがちょっと少なかったかなという感じがしましたので、これは予算のほうでひとつ頑張っていただきたいと思います。ほんとうに長い間ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3044#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":38248,"voices":85}},{"id":"h15-20030304-8","meetingId":"h15-cm03","date":"2003年3月4日","dateIso":"2003-03-04","committee":"建設委員会","time":"午前１０時０５分～午後０時０５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"管理方法の変更内容のところでちょっとお聞きしたいんですけれども、平成１４年度から委託開始して、今回あわせてここで出ているのが７カ所ですけれども、例えば委託それぞれにいろんな業者が入ってくるんでしょうけども、例えば樹木の管理をする業者というのは、７カ所の運動公園やなんかでそれぞれに違いがあるんでしょうか、この辺ちょっと。","respondent":"松代道路公園課長","answer":"委託化の内容というようなところだと思いますが、実は平成１４年度に委託をしましたところは、主に運動施設の受付と、ここにありますようにテニスコートとか野球場の管理を主に考えてあります。","voiceIndex":9,"id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"プロポーザル方式でやっている。今回の四つの施設がありますけれども、一括してということは、この四つ全部を一括してやるということですか。〔「はい」と呼ぶ者あり〕ということは、当然、ちょっと今のところでわからなかったのは、今の高木の剪定だとか、要するにそれを全部一括してやるという意味なのか、それともどこかの管理会社にそれを全部任せるという方式なのか、ちょっとそれだけ教えてください。","respondent":"松代道路公園課長","answer":"今委員ご指摘のとおり、１社がこの４公園、４施設を一括してすべての管理を行うというものです。","voiceIndex":11,"id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"料金のほうの内容についてお聞きしたいんですが、基本的にここの文面を見ますと、サービスアップ、効率アップということの措置というふうに書かれているんですが、例えば今現在１時間から１時間半待ちの状態が続いているというのは、逆の考え方からすると、既に利用勝手がいいから、サービス内容がいいから混んでいるというふうにも読み取れますし。","respondent":"松代道路公園課長","answer":"私ども、その辺が一番悩んだところでございまして、実はしながわ区民公園の南駐車場、この件に関しましては、昨年の３月と４月に利用者のアンケート調査をいたしました。","voiceIndex":15,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"そのお気持ちといいますか、そういう原因があっての改善策だということが利用者にわかるように、そういう理由がよく理解されていない場合は、単なる値上げだというふうなとらえられ方もしかねないので、その点はお含みいただきたいと思います。要望でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-004"},{"speaker":"船波委員","kind":"質問","question":"駐車場の料金のほうでお伺いしたいと思いますけど、この公園に入られる方が公園でどれくらい過ごされるか知りませんけど、入るために１時間から１時間半待つこともあるというので驚きですが、例えばしながわ区民公園について、いろいろ宣伝をしたりする、場所的にいろいろなものを使われて来られると思いますけど、そういうところに駐車場は限られているから、公共の交通機関でおいでくださいということは。","respondent":"松代道路公園課長","answer":"公共交通機関ですけれども、これは大森駅が周辺にございまして、そこからのルートもいろいろと周知を今までしてきてございまして、その駅を使ってご利用いただけるのが先ほど言いました半数に近い形で利用されていますので、大方そちらのほう。","voiceIndex":18,"id":"exchange-005"},{"speaker":"船波委員","kind":"質問","question":"それがどれほどの効果があるかもわかりませんけど、やはりないよりはいいのではないかと思うんですが、そういうことについての状況とか今後の予定はどうなっているんでしょうか。","respondent":"松代道路公園課長","answer":"今のご指摘、私ども今後、年に３回ほど広報等で紙面を使いまして、いろいろと催し物等のお知らせをしていますので、その際、そのことも含めて公共交通機関の利用、駐車場のありよう、そういったものを今後ともＰＲしていきたいというふうに思ってあります。","voiceIndex":20,"id":"exchange-006"},{"speaker":"船波委員","kind":"質問","question":"わかりました。では、この改定料金を２０分１００円にするということですけど、１００円単位で止められる民間駐車場がたくさん最近できましたね。天王洲とかしながわ区民公園の２０分１００円というのは、周辺にあるそういった民間の１００円で止められる駐車場と同じレベルになっているんですか。","respondent":"松代道路公園課長","answer":"ですから、そういった点ではちょっと天王洲公園は中に入ったところにありますので、施設利用者のためということもあって、２０分１００円、また、しながわ中央公園と天王洲と同一の料金体系をとったほうがよかろうというところで、今回の料金を設定したものです。","voiceIndex":22,"id":"exchange-007"},{"speaker":"船波委員","kind":"質問","question":"そうしますと、両方、天王洲のほうもしながわ区民公園のほうも、周辺の民間の駐車場よりは安いという設定だと、やはりどうしてもこの公園にあるほうに車が来てしまって、こういった改定をしても、やはり駐車場入場待ちを解消するという効果のほどはどうなるんでしょうか、それはやってみないとわからないということなのかもしれませんが。","respondent":"松代道路公園課長","answer":"これは天王洲野球場も同様でございまして、平日等は施設の利用者が少ない状況ですので、そういったときの一般の利用の方は結構なんですが、土曜・日曜に関しましては、非常に施設の利用者も多いということから、公園施設の利用者に限ると。","voiceIndex":24,"id":"exchange-008"},{"speaker":"船波委員","kind":"質問","question":"最後の質問ですけど、夜間や空き時間については、近隣の方が利用できるように変更するというのは、どういうことなんでしょうか。","respondent":"松代道路公園課長","answer":"その状況を周辺の方々への利用等もできるような形で今回２４時間のオープンということで、今回プロポーザルをしまして、民間会社が常時管理をしますので、私どもが職員の手で管理していた以上にセキュリティだとか、何かあったときの際の対応だとか。","voiceIndex":26,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"駐車場の料金のことなんですけど、しながわ区民公園のところは、利用者のサービスおよび利用効率の向上ということが書いてありますけれども、利用しやすくすることはいいことだと思います。特にここの庁舎の駐車場においても、ここに用事でいらっしゃった方は無料になっているということを含めれば、そうではないかな、基本的なその辺のお考えを伺わせていただきたい。","respondent":"松代道路公園課長、中谷まちづくり事業部長","answer":"これは平成３年にシルバー人材センターにお願いして以来、１１年ほどこの料金でやってまいりました。ですから、そういった意味では、低料金での利用者への還元というのは一定程度達成されたと考えています。料金徴収のことにつきまして、基本的な考えをちょっと補足説明します。今、道路公園課長から話がありましたけど、私どもの公園の有料施設、これは特定の方が特定の目的でお使いになるということで使用料金を徴収しております。","voiceIndex":30,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"公共施設というのはどなたでも車で来るというものではないと、それはそうだと思いますね。利用者優先という考えを先ほど課長が述べられた、空き時間もあって有効に使うというそのところと、利用者を優先するんだという、どういう部分で優先されているのかなと、それ以外に使われる方と、そこのところがちょっと引っかかったので、ちょっと教えてください。","respondent":"松代道路公園課長","answer":"ですから、天王洲公園を利用される方の駐車場としての使い方をしたいということで、公園利用者の方の駐車場ということでの看板を現地につけます。そういった形で、それを承知して使っていただけるようにしたいなというふうに思っているところです。","voiceIndex":33,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１のほうの委託の管理のところにいっていいですか。ここのところで、さっき日本体育株式会社にこの平成１５年度の委託というのは一括ということでしたけれども、もう一回戻って平成１４年度のところの委託の状況をもう一回聞かせていただきたい。","respondent":"松代道路公園課長","answer":"大きく変わりましたのは、平成１５年度一括でやりましたのは、平成１４年度の経過等をずっと見てまいりまして、それを一括で管理するスケール的なメリットがあるというようなところが見えましたので、そこを一括で今回日本体育株式会社に委託をするものです。","voiceIndex":35,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"平成１４年度は３社であったということで、その３社を教えていただきたいのと、平成１５年度、上の四つの部分がプロポーザルで一括ということですが、ここの部分だけですよね。前の年度のところまで広がって全部一緒ということですか。そうではない。この４カ所だけですよね。じゃあ、平成１４年度の３社のところ、ここは変わらず今までどおりということでしょうか。そこの３社を教えてください。","respondent":"松代道路公園課長","answer":"業者名です。東品川公園がオリエント株式会社です。私どもの区内業者です。子供の森公園がネクサス株式会社です。しながわ区民公園が日本不動産株式会社の３社です。","voiceIndex":37,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"日本体育株式会社というのがよくわからないのね。ここの資本金とか、本社はどこか、ちょっと会社の中身はわかりますか。今、東品川が地元、区内業者だということで、大きなところに行って、実際今まで区内に仕事が回っていたのが、その辺が移動してしまうというところがちょっと何かわからない。どういう会社なのか教えてください。","respondent":"松代道路公園課長","answer":"ちょっと資本金等の関係は今手元にございませんけれども、大手の部類に入る、そういう運動施設業者です。","voiceIndex":39,"id":"exchange-014"},{"speaker":"菊地委員","kind":"質問・要望","question":"先ほど部長の答弁、ちょっと私よく理解し得なかったんですけども、シルバー人材センターから派遣されている方と実際に駐車場に入る方のトラブルみたいな話とか、お年寄りだからいろんな意味でなかなか機転のきかないところがあったりとかいろいろあるんでしょうけれども、部長答弁とかみ合わせると何か管理が委託されると、そうしたらシルバー人材センターから入っていらっしゃる方の身分は保障されない。","respondent":"松代道路公園課長","answer":"いろいろ私ども改善方を申し入れをしまして、いろいろと指導したところですけれども、いかんせん細やかな対応がなかなか行き届かなかったというところで、トラブルがあり、クレームとして書面もしくは電話等で多く寄せられた。","voiceIndex":41,"id":"exchange-015"},{"speaker":"菊地委員","kind":"意見","question":"直営でやっていたときの業者の方、何らかの形で入っておられた業者がいるんだと思いますけれども、その業者はどういう形になりますか。","respondent":"松代道路公園課長","answer":"ですから、平成１４年度に委託したような形のほかの公園の例えば高木の剪定だとか、そういったものは受けた業者以外の別なところの業者が入ってやっておったんですが、この４公園につきましては、一括管理という形になってあります。","voiceIndex":43,"id":"exchange-016"},{"speaker":"菊地委員","kind":"質問・要望","question":"よくわからなかったんですけど、何か今実際に区のこういう管理やなんかで区内の小さな業者が入っていたりするんであれば、例えば日本体育株式会社というところに全面的に管理委託された際に、そういう業者の方、これまでの業者を一定程度使っていくことをぜひ、ここは委託してしまった以上、また口は出せないということなのかもしれませんけれども、その辺はぜひ要望しておきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"今年取り上げていただいたことによって、今回南大井地区がついたということなんですが、その南大井以外で平成１１年以降発生した水害を踏まえまして、区長名で他の地区も含めて要望し、そのうちの南大井地区だけが採用といいますか、その対象になったということなのか、現段階において、３地区が既に基本で設定されて、優先順位として南大井地区のところなんですけれども、南大井地区だけを要請されたのか。","respondent":"矢部下水道河川課長、北野委員長","answer":"南大井地区の完成時期なんですけれども、これから対策案を検討するということで、ちょっと定かなところは申し上げられませんけど、大体今までの例でいきますと、やはり下水道工事ですので。ほかにないようですので、本件を終了いたします。","voiceIndex":50,"id":"exchange-018"},{"speaker":"本間委員","kind":"意見","question":"見直しの内容の部分についてお尋ねします。しかし、指導的な部分での、もちろん自分たちが一番よくわかっていて半地下にして得する部分と、半地下にしたがために、その部分はまだ別な悩みが出てきているという部分もありますが、きちんとした指導をするということでありましょうけども、かなり一時的に拡大したその部分の適切なる指導についてちょっとお尋ねしたいと思います。","respondent":"矢部下水道河川課長","answer":"それはもちろんそういう形で今後も引き続き指導をしていくと。今後この４月以降はこれの対応になりますので、もしそういうことがあったとしても、うちのほうとしては助成ができませんということをはっきり言うなりして、指導を強化していきたいというふうに考えております。","voiceIndex":56,"id":"exchange-019"},{"speaker":"本間委員","kind":"質問・要望","question":"地下が大丈夫だったというような安心、慢心のもとに例えば女性の踊りの衣服など、よその人のものをまとめて保管していた部分がやられたとかというような部分で、このような問題点が把握されて、しばらくは非常によかったというふうな部分が一挙にして、ここでまた変なことになるんだなというふうな部分が出てきている昨今の状況ですので、その辺は一方にはよくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-020"},{"speaker":"菊地委員","kind":"質問","question":"見直しの内容のところで書かれている「地盤面より掘下げて土地利用を行う」という、これはどの程度のことまで言うんでしょうか。これは半地下の駐車場はわかるとして、今最近はやりの階段、１段、２段ぐらいおりて玄関があるという建物も結構つくられていますけれども、その部分も含めての話なんでしょうか、ちょっとお聞かせください。","respondent":"矢部下水道河川課長","answer":"実際の場合ではいろんなケースがあるかと思いますけれども、基本的には要するに道路面から、その宅地内に雨水が入るような構造については基本的にはやめてくださいという形になりますので、たとえ１段、２段であっても、そのような同じような指導になるかと思います。","voiceIndex":59,"id":"exchange-021"},{"speaker":"菊地委員","kind":"意見","question":"そういうことでしたら、その主旨にありますけれども、今、半地下、そういう浸水被害が出そうな地域でも、こうした半地下に建物をつくらないように指導しているというお話でしたけれども、この主旨の中に書かれている購入者の自己責任の明確化というところでは、もちろん１０代から住んでいて建て直しをされる方は、その地域がどういう地域かというのはもちろん十分知り得ていることだと思うんですけれども。","respondent":"矢部下水道河川課長","answer":"ただし、今回こういう形で宅地造成の業者も含めて、業者の方も含めて周知をしていますので、それの後、そういう浸水被害が出た場合については、基本的にそこに購入された方の損害賠償というんですかね、求償先につきましては、基本的にその建主、建築業者に。","voiceIndex":61,"id":"exchange-022"},{"speaker":"菊地委員","kind":"確認","question":"そこに対する指導はしましたよというのと、その後どうしたか、そこまでは責任を持てませんよというのは、少なくとも建築確認をおろす側の立場としては非常に責任のない話になってしまうんじゃないでしょうか。ちょっとだれにお聞きしたらいいのかわかりませんけど。","respondent":"山室住宅指導担当部長","answer":"それは私どもも承知しておりまして、いろいろな機会にそういったことをやっているわけですが、例えば業者の方に、できましたら協力というような形で、説明したことについて報告をお願いしたりとか、そういったことも少し考える必要があるか。","voiceIndex":63,"id":"exchange-023"},{"speaker":"菊地委員","kind":"質問・要望","question":"ちょっと今の部長のお話でよく見えなかったところをお伺いしたいんですけれども、それでは今まで水が出なかったところで、実際にそういう半地下状の建物が建てられて購入されたといった場合には、この見直しの内容を読めば、これまで水が出なくて突然水が出たという地域で被害に遭っても、これはその助成対象にはなりませんよという話ですよね。","respondent":"山室住宅指導担当部長","answer":"業者の購入者に対してどういうふうな説明をしたかというところまではなかなか把握し切れない部分があるわけですね。業者からの説明をある面では信用するしかないというのがあります。","voiceIndex":65,"id":"exchange-024"},{"speaker":"菊地委員","kind":"質問・要望","question":"ということであれば、こういう形で見直しの主旨が出てくるということよりも、これまで業者に対してもいろんな形で指導してくるということであれば、それこそ区内全域で半地下の建物をつくって売らないということを、それが指導になるのか、それとも方法的に実際に周知をしていく内容のものになるのかわかりませんけれども、やはりそういう手だてというのはとるべきものではないかなというふうに思いますので。","respondent":"山室住宅指導担当部長","answer":"対策をとっても、先ほど言いましたように、維持管理の過程でこれもまた被害を生じる可能性がありますので、そういったことを機会のあるごとに本人の方、もしくは関係者の方に提案していくという努力をこれからも続けていきたいというふうに考えております。","voiceIndex":69,"id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"水は高いところから低いところへ流れるので、当然家を建てる方も、それから家を購入する方も半地下の部分は当然こういう水が入り込むということを想定して、それぞれ自己責任の中で対策を講じるべきだと思いますので、年々助成を求めている方々が多い、限られた財源の中で求める方が多いということは、半地下の方はぜひ自己責任の範囲で助成に頼らず設置をすべきだと思います。","respondent":"矢部下水道河川課長、北野委員長","answer":"最初に事前の申請でという話なんですが、実施日以降に建築確認を得て行う工事について、今回の適用除外とか、そういう対象になりますので、ですから、うちのほうで建築確認のときにそういう内容をお話しして。ほかにないようですので、本件を終了いたします。","voiceIndex":71,"id":"exchange-026"},{"speaker":"船波委員","kind":"質問","question":"申しわけないんですけど、この別紙１、２、３、４で説明されたことが、ちょっとどういうふうにつながっているのかがわからなくなってしまったのでお伺いしたいんですけど、別紙１での説明は、東京都が決めようとしていることですよね。そういった地域に指定されるのが、指定されるように調整したというのが別紙２のことで、二葉三丁目・四丁目ということなんでしょうか。","respondent":"山室住宅指導担当部長","answer":"これが木造住宅の密集地域の整備がなかなか進まないという中で、どのような工夫をしたら促進がされるんだろうかということについて調査検討されてきたわけですが、それを踏まえて、我々理事者側からもどのような取り組みをしてきたかということを整理して。","voiceIndex":78,"id":"exchange-027"},{"speaker":"船波委員","kind":"質問","question":"わかりました。別紙１の東京都の事業体制による指定というのは、ではどの辺なんでしょうか、それは別紙２のほうで出ていた二葉三丁目か、別のところになるんでしょうか。","respondent":"山室住宅指導担当部長","answer":"今後のことは、構造規制の強化等が出てまいりますので、一方的な規制だけではなくて、昨日のまちづくりの話とも関連しますけれど、どういった規制と緩和の組み合わせでこういった木造住宅密集地域でのまちづくりを進めていこうかということを、今までも検討していますが。","voiceIndex":80,"id":"exchange-028"},{"speaker":"船波委員","kind":"質問・要望","question":"だから、ほかの人は泣く泣く移動とかということにならないように、やはり、十分な説明というか理解を高めていく試みが必要なんじゃないかと思って、そういうところで別紙４で説明されているように、まちづくりの懇談会だとかニュースだとか、そういうことをやられていくんだと思いますけど、別紙３のように、説明されていることが今後行われることについて、どういうふうに周知というか。","respondent":"浜脇住環境整備課長、山室住宅指導担当部長","answer":"ですから、この地域で私どもとすれば、一応こういう制度を使えないかということは、そろそろ検討しなくちゃいけないということでございまして、ただ、イコール業務ということじゃないんですが、やはり、私どもとすれば。この制度ができましたら、当然こういった制度をまちづくり協議会等にご説明して、新しいメニューとしてこういうものができましたよと、皆さんのところでもぜひ考えてくださいというところから当然進めていかなければいけない話ですので。","voiceIndex":82,"id":"exchange-029"},{"speaker":"林（和）副委員長","kind":"質問・要望","question":"私のほうからごあいさつします。この１年間、皆様方のご協力によりまして、建設委員会が充実したものとなりました。ほんとうにありがとうございました。来期もひとつお互いに出てきまして働かせていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3748#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":34228,"voices":93}},{"id":"h15-20030304-9","meetingId":"h15-cm03","date":"2003年3月4日","dateIso":"2003-03-04","committee":"文教委員会","time":"午前１０時０７分～午後３時５１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"高星委員","kind":"意見","question":"それで、３学期になってもういかんというときに、先生が、あなたここまで来たら、もうはってでも出てきたらと言ったらしいんだよ。だから、先生の内面というのは、いろいろ子どもの関係とかお互いクラスの信頼とかの関係とかで難しいところがあるんだろうというふうに思うんだけれども、具体的なことで、その基準みたいなのがどういうふうになっちゃっているのか、ちょっと聞いてみたいなと思って。","respondent":"谷田部学務課長","answer":"それで、そのほかにも感染症で、例えば百日ぜきだとかいろいろ伝染性の病気もありますから、これは本人の意思にかかわらず、そういうふうな判断をすれば、当然出席ができない。","voiceIndex":5,"id":"exchange-001"},{"speaker":"高星委員","kind":"質問・要望","question":"違うことでもう一つ。それから、有料なのかどうなのか。それと学校でやらないで、まちのお医者を指定してやられているのか、全体でインフルエンザ等の、ここではインフルエンザのことでなっていますけれども、インフルエンザの予防接種の打てる保護者とか子どもの意向は、考え方はどういうふうになっているのかというのを押さえているところがあったらちょっとお聞かせいただきたい。","respondent":"谷田部学務課長","answer":"風邪の時期ですから、通常学校の中では手洗い、うがいの励行をするように、それは外出先から戻ってきた場合には、そのようなことで予防する、予防措置をとるように、それからまたインフルエンザの場合につきましては。","voiceIndex":7,"id":"exchange-002"},{"speaker":"原委員","kind":"質問・要望","question":"学校でのインフルエンザですと、学級閉鎖が一番いい対策みたいになるのかなと今思っていたんですけれども、静かに休ませるということが対策の一つなのかなというふうに思うんですけれども、毎年風邪で休むところがあるわけですけれども、これが引き金になって、例えば次に何かほかの病気を発症して取り返しのつかないことになったとか、そういう事例というのはどうなんでしょうね、今までかつての。","respondent":"谷田部学務課長","answer":"品川区の場合、合併症を起こして重症化したというような報告は今のところ聞いてございませんので、やはり生徒・児童の出席率が、インフルエンザによって欠席者が増えてくれば、当然感染予防という問題と。","voiceIndex":9,"id":"exchange-003"},{"speaker":"原委員","kind":"確認","question":"それと、この学級閉鎖の期間というんですかね、１週間とか１０日とか、短いところは二、三日になるかもしれないんですが、その辺の判断というものは、例えば期間を１週間に区切って出てきたときに、やっぱりまだ出てこれないといった状況を把握しなければならない。","respondent":"谷田部学務課長","answer":"学校医との関係からお答え申し上げますけれども、通常欠席者に比べて、極端に１０人が休んだり１５人が休むというような話になれば、これは当然学校医にこういう状況なんだと、学校医のほうにどういう関係で今お子さんたちが病気にかかっているかというのは。","voiceIndex":11,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"先ほどちょっと高星委員からもあったんですけれど、学級閉鎖になったりなんかすれば、それは欠席扱いにならないで、診断書という話があったので、診断書が出れば、閉鎖されなくても個別の欠席扱いにならないのかどうかということと、それから、前に予防接種を集団的にやってきた時期があるんですけれども、ちょっとここで聞いてもしようがないことなんだと思うんだけれども、予防接種の効果が。","respondent":"谷田部学務課長","answer":"それで、データはどうなのかという話ですけれども、昔はＡ型、Ｂ型ですとか、Ａ型でもソ連型とか香港型とかいろいろあったですけれども、最近のインフルエンザはどのように発生するかというのは予測がまずつきやすくなったということと、それからＡ型とかＢ型にも両方効くような。","voiceIndex":13,"id":"exchange-005"},{"speaker":"沢田委員","kind":"意見","question":"私の勘違いなのかもしれないんだけれども、以前は何か予防接種をやっていたんじゃないかなと。ちょっとそれが議会で論議になったことがあるんじゃないかなと思うんだけれども、勘違い。ならそれはそれで構いませんけれども。〔「予防接種は、昔は強制ですよ」と呼ぶ者あり〕強制でやっていたよね。あれ、インフルエンザだったよね。問題になったんだ。","respondent":"谷田部学務課長","answer":"それで、あとかつて予防接種をしていたかどうかというのは、ちょっと私どもも記憶が定かでございませんので、これはちょっとあいまいなお答えをするのは非常にいけませんので、これはまた、午後視察に行く前に。","voiceIndex":15,"id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"最後にちょっと。すみません、長くなって。変な話と言えば変な話なんですけれども。学校である程度のインフルエンザが発生した初期の段階に、全教室にとは言わないんだけれども、例えば加湿器みたいなものを持っていって、予防的に教室でそういうのを使用するというか、そんなことは考えられないんでしょうか。自宅でやらなきゃ、今度はあれかもしれないんだけれども、感染するのは教室が多いですよね。","respondent":"谷田部学務課長、青木指導課長","answer":"特定の期間だけという話になりますと、これは非常に財政的な問題、それから難しい面もありますので、その辺は休み時間等々、うがい等をして。子どもに対しては、今、学務課長が申し上げましたけれども、うがい、手洗いの励行ということは繰り返し指導するところです。それから、やはり暖かくしろと、栄養をとれと、よく寝ろというような指導をしてございました。","voiceIndex":17,"id":"exchange-007"},{"speaker":"沢田委員","kind":"提案","question":"ちょっと思いつき的なので、全クラスに設置しろというと、年間の限られた期間ですから、一定の欠席数に達したような、パーセントになったらば、どこかから持ってきて加湿器のもとでやるというのは考えられるんじゃないかなということで、提案したということで結構ですので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-008"},{"speaker":"石田委員","kind":"質問・要望","question":"どうしてかというと、お医者さんに言われて、熱が下がったら２日ぐらいしたら、そのまま熱が下がっていたら、出席していいよというようなお話と、今の何かそのときに出てもいいという診断書をもう一度もらいに行ってくださいよという話が、学校では交錯しちゃっていて、どういう状況の中で出席をしたらいいかというのが、かかった人同士で交錯。","respondent":"谷田部学務課長","answer":"それで、問題なのは、お子さんによってかかった時期がいつなのか、これは一斉にかかるわけではないので、当然潜伏期間もありますし、症状が出てくるのも何日か出るのに多少ずれがありますので、それはお子さんが。","voiceIndex":21,"id":"exchange-009"},{"speaker":"石田委員","kind":"確認","question":"それで行ったと。そうしたら、それは要らないよという場合もあるみたいだし、話が非常に交錯をしているんだけれども、そこら辺のところは交錯したままやっちゃうのか、教育委員会のほうである程度の、個々の対応というのか、こういう場合はこういう、例えば熱が下がってから３日後とか２日後とか、そのお医者さんに確認してくださいとか、そういう決め事がある程度あると思うんだけれども。","respondent":"谷田部学務課長","answer":"今回たまたまインフルエンザのお話ですから、例えばある日数がたてば体調も治ってきますし、前も感染症の場合、先ほど言いましたように、百日ぜきですとか、風疹ですとか、いろんなそういう感染症の場合、そういう場合につきましては。","voiceIndex":23,"id":"exchange-010"},{"speaker":"石田委員","kind":"質問・要望","question":"わかりました。交錯している。ちょっともう１点違うことを言っていいですか。ある公園に行って野球をやったりいろいろしていた子どもたちがいるんですが、ここら辺のところは本来はどういう指導をしているのか、ちょっと教えていただきたい。","respondent":"青木指導課長","answer":"ただ、本当に元気な子であれば、こうした課題もこなしてみたらどうかといった勉強の内容なども提示してやらせることもありますけれども、学級閉鎖という状況においては、まず教員としては静かに家庭で過ごしなさいと、こういう指導をしております。","voiceIndex":25,"id":"exchange-011"},{"speaker":"原委員","kind":"質問","question":"午後のこれは、車の中でこっちをやるんですか。それとも今説明できるんですか。","respondent":"鶴委員長","answer":"はい、その予定です。この間もちょっとお話出ましたが、午後一番から視察する予定をしておりますが、本日は最後の委員会ということで、正副委員長よりごあいさつをします。","voiceIndex":33,"id":"exchange-012"},{"speaker":"上山副委員長","kind":"質問","question":"私のほうから。１年弱だったんですけれども、有意義な時間を過ごさせていただきました。今年はいよいよ小中一貫校の問題や、それから学校改築も始まってくる時期ですから、今後の新しい委員会になると思いますので、そちらのほうにゆだねていきたいなと考えています。今後とも見守っていきたいなと考えています。いろいろありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4466#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":11495,"voices":37}},{"id":"h15-20030304-5","meetingId":"h15-cm03","date":"2003年3月4日","dateIso":"2003-03-04","committee":"総務委員会","time":"午前１０時０３分～午後１２時２０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１４年請願第３１号 旧正田邸についての請願","agenda":"平成１４年請願第３１号 旧正田邸についての請願","exchanges":[{"speaker":"土井委員","kind":"質問・要望","question":"それが１点。もう一つは、裁判の関係なんですけれども、特別抗告が行われたやに私ども伺っておるんですけれども、その辺についての情報等々は聞いていらっしゃらないのかどうなのか。その場合の思いはどうなのか、その辺についてまず。","respondent":"中尾根企画部長","answer":"ただし、私どもはいろいろ大臣の答弁もありますけれども、国から聞いておりますのは、いろいろな表現を大臣がその都度答弁はしておりますけれども、国にとっての方針に変更はない、そのように国のほうからは聞いてあります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"土井委員","kind":"質問","question":"２８日の大臣の答弁の中を見てみますと、確かに残すというお話ではないけれども、使い方等々を含めてどのように、児童館になるとか何かというようなお話も出ておりますけれども、国会レベル等々でも検討を要するのではないかというような趣旨のものが含まれていますし、とはいえ、それは品川区との間の関係があるので相談したいという中身になっておりますけれども。その意味で、その内容に間違いないですか。","respondent":"中尾根企画部長","answer":"財務省のほうの見解は、財務大臣が皇后陛下がお住まいになったことを記念として、何かつくる方向で検討するのであれば、それは建物が取り壊された跡地に何かをつくるという前提で話されているということと、それから。","voiceIndex":7,"id":"exchange-002"},{"speaker":"土井委員","kind":"質問","question":"とすると、財務省の方針は、品川区に土地を売却はするんだけれども、上物等についても相談しますよと、こういう方針だということですか。","respondent":"中尾根企画部長","answer":"これは大臣がそういうふうに私は直接聞いたわけじゃなくて、財務省の事務のレベルではそういう解釈に変更はない、このように聞いてあります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"土井委員","kind":"質問","question":"したがって、それらについても、どう受けとめ、どう回答され、どのように認識をされているんですか。","respondent":"濱野助役","answer":"そういうことの中で、今私どもは物事を進めなければならないという事態であるというふうに認識しています。この間のナショナルトラスト等からの申し出、今、委員のお話のようなことであります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"土井委員","kind":"意見","question":"それらについて、この請願者のほうは、取り壊さないで、その活用法、その行く末等々をしばらくいろいろみんなで考えて方策を打ち出していきたいので、それを待ってもらう、そういう方策を何とかとれないだろうかという請願内容ですので、その辺は区との若干の違いはあるにしても、相当な９万近くの署名等も出されている、また、歴史的、文化的、社会的な大きな流れの中にあった建物だということ、また。","respondent":"中尾根企画部長","answer":"国の責任においてなされるべきという見解を私どもとっておりますから、国が変われば私どもも変わるです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"塚本委員","kind":"質問","question":"その中身はいろいろ難しいことがあるでしょうけれども、という認識判断に立つと、やはり事態を慎重に見守って、大きな品川区の判断の前提が、言葉は適当かどうかわかりませんが、ゆがみというか、揺れが出てきたというふうに、また、土井委員のほうから、最後の指摘の中で、前提の方針が変わってくれば当然のことがある、その方針に基づいて品川区はある種の態度を決めたわけですから。","respondent":"濱野助役","answer":"当然のことながら、この根本のところの前提のところが変わってくれば区の対応も変わってきますが、今の時点では、こうこうこういうふうに変わりそうだから、こうこうこういうふうにいたしますという時点ではないだろうというふうに考えています。","voiceIndex":15,"id":"exchange-006"},{"speaker":"塚本委員","kind":"確認","question":"責任官庁である財務省がある種の発言をし始めたということも確かですから、品川区の既定の方針ということは承知しておりますけれども、やはりとまる方向といいますか、方向を見極めるには変化に対応しなきゃいけない時期が来ると思うので、そういう一歩手前に来ているのかなという認識を私は持っているというふうにいつも思っているんですけれども。","respondent":"濱野助役","answer":"その国の対応の中で、品川区として品川区の行政がどういうふうに責任を果たしていくのか、役割を果たしていくのかということの中で物事を考えていくべきだろうというふうに思っていますので、今の国の方針を前提とした場合の品川区の対応というのは。","voiceIndex":17,"id":"exchange-007"},{"speaker":"桜井委員","kind":"質問・要望","question":"私も二、三、質問したいんですけれども、先ほど、特別抗告の話がありましたね。特別抗告についてのことを知りたいなと思っているんですが、具体的にはどういうふうな内容で、それから、どういうことをもとにしているのか。その期限というんでしょうか、期限の情報とか、これまでの事例があれば教えていただきたいなと思います。その内容についてどういう内容なのかお知らせいただきたいなと思います。","respondent":"市岡企画財政課長、濱野助役","answer":"この特別抗告というのは、例えばよくあるのは、表現の自由をめぐって、集会とかデモについて、高等裁判所が認めなかった場合にさらに最高裁まで、憲法２１条の権利が侵害されたということで争うという例があります。先ほどご答弁申し上げましたように、この問題は、区としては、解体された場合、その土地を購入する方針を決めておりますから、その方針に変わりはございませんということでお答えを申し上げた次第です。","voiceIndex":19,"id":"exchange-008"},{"speaker":"桜井委員","kind":"質問・要望","question":"実際、今の流れを見ていますと、区と国との関係ということもありますけれども、実際、区自体がどういうふうに、区自身の対応として、国のそういう流れというのはあるけれども、区民の皆さんからのいろいろな要望も出ているということもあって、例えば、区自身がある面では話し合いの場を設定してくれるということというのは、私はこのケースでもあるんじゃないかと思うんですけれども。","respondent":"市岡企画財政課長、中尾根企画部長","answer":"それ以外、もちろん、国に対していろいろ情報を求めたりはしておりますが、区として責任がとれないことについて公の場で申し上げることができないので、なかなか苦しいお答えをしているところですけれども、よろしくご理解願います。こういう内容です。","voiceIndex":22,"id":"exchange-009"},{"speaker":"藤田委員","kind":"質問・要望","question":"違法と書かれていますからね、この新聞に。ですから、我々も想定しているわけですけれども、文化財保護法を棄却した、すなわち文化財に当たらないんだというようなことで私は解釈してお話ししたわけですけれども。それから、これから特別抗告ですか、手続きに入るのか入らないのかわかりませんけれども、その間はずっと今現在の状態が続くのか。もしわかれば教えていただきたい。","respondent":"市岡企画財政課長","answer":"しかし、国有財産処分の方針からすると、年度内の処分ということを明らかにしていた以上、取り壊しの方針も変更していないわけですから、現実に取り壊せる準備はしておかなければいけないということで、２月２４日に高等裁判所の決定が出ましたので。","voiceIndex":25,"id":"exchange-010"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"建物については、残してほしくないという意見も出てきた。これは本当は物納というものから考えると、残してほしいという話が通用する話ではない、一般の我々の物納した場合はね。僕ら聞いている話ですよ。いろいろ要望を出されている方にもそういうアドバイスはしました。国で言うと総理大臣が一番責任者だけど、担当の大臣ですから、国の最高意思決定機関の考えと判断していいと思う。","respondent":"濱野助役","answer":"ただ、今までと変わってきつつあるかなという認識は持っていますけれども、どうするということはまだ塩川大臣も決めかねているのではないかということが現状だというふうに思っております。","voiceIndex":28,"id":"exchange-011"},{"speaker":"林（宏）委員","kind":"確認","question":"これはいろいろ理解の仕方だから、本人に確認したわけじゃないから分かれるけど。そういう意味で、僕は、国も言ってくれるというのは、早急に動くなら、そういう判断を出してくるべきだと思う。わからない、それも仮定の話だからどうこうではないんだけれども。だから、僕は、それぞれの立場の人が国に積極的に判断をきちんとしてくださいという行動をしていくべきだと思うけど、いかがですか、やったら。","respondent":"濱野助役","answer":"先ほど申しましたように、国としての基本の考えというのがあって、地方自治体の物の考えというのが、この問題についてはある、国有財産なんですから。そういう立場で国に対して一刻も早く基本的な方針を決定してほしいということを、それは強く申し入れているところであります。","voiceIndex":30,"id":"exchange-012"},{"speaker":"林（宏）委員","kind":"意見","question":"もう一つ、我々として責任上のことなんだけどね。今、我々に請願が出ている。我々の寿命というか、４月で一つの区切りを迎えるわけね。審議未了で一たん終わっちゃうからね。そうすると、僕は、一つのそういう人たちの署名をしてきた運動というのかな、意思表示というのをサポートするには、一たん請願を下げることも考える、それで５月に再提出するという。局長がいるんだから局長のほうがいいか。","respondent":"福田区議会事務局長","answer":"おっしゃいましたとおり、４月の任期満了をもちまして議会の同一性が失われる、こういう時期に来ております。したがいまして、今の時点で継続いたしますと、審議未了ということも十分考えられる。署名の効力ですけれども、この委員会に付託をされたものはこの議会から付託をする。","voiceIndex":32,"id":"exchange-013"},{"speaker":"林（宏）委員","kind":"意見","question":"動いているから、どこでどういう判断をすべきかわからないんだけど、そういうことなんですよ。１０万近い署名が効力を失っちゃうという事態も一つ考えておかなきゃいけないので、委員長にそれはお考えとしてはお伝えしておきます。その意思がどこで生かせるかという判断は理事者のほうで持っていらっしゃいますか。","respondent":"中尾根企画部長","answer":"そのことによって国が変更しようとしているのか、本当に従来どおりなのか、このことについてはもう少し時間が必要かな、そういうふうに思ってあります。","voiceIndex":34,"id":"exchange-014"},{"speaker":"林（宏）委員","kind":"意見","question":"区の考え方、反対もある賛成もあるという、それは一つのことをやろうとすれば、全員一致して３２万人の人が一つの方向を向くということは、まず、税金をただに、ゼロにすると言ったら全員、それでも区長はだめだと言うかもわからない。建物を残すという一つの意思がはっきりしているわけですよ、請願を出されている方は。それは委員長に僕のさっきの考え方だけ伝えておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":36,"id":"exchange-015"},{"speaker":"土井委員","kind":"確認","question":"間違いを犯すといけないので確認をします。となると、また歪曲された解釈になっていく可能性がありますので、これは、そういう形で、国会で議決をするという形で政治決着を図ることも可能なんだけれどもということの中で、なぜ今しばらく解体をご猶予いただけませんかというのが質問なんですね。だから、この文章をつないでいけばですね。","respondent":"濱野助役","answer":"つまり、幾つか出てきた手法に対する答弁というふうに理解していますので、もちろん、質問者がそれだけを考えていたわけではないということは確かだろうと思いますけれども、その一つに対する答弁として塩川大臣の答弁があったということだと思います。","voiceIndex":37,"id":"exchange-016"},{"speaker":"桜井委員","kind":"確認","question":"そこは別に変わっておりません、言っておきますけど。非常に苦慮している、苦慮しているという中身というのは、国が持っている建物だから、建物に対して云々は言えないというところでいいのか、ちょっとそこを確認したいんです。要するに、国に対して建物を残してほしいというふうに言う根拠がないというのは、そこのところをもう一度確認したいんです。","respondent":"市岡企画財政課長","answer":"もしその辺についていろいろ議論があるにしても、指定文化財については、まず現況調査から始まって、所有者の同意が必要なので、現実に取り壊しをすると言っている所有者に対して同意を得られることは考えられないという２点をご答弁申し上げているところです。","voiceIndex":39,"id":"exchange-017"},{"speaker":"桜井委員","kind":"確認","question":"その原点に戻れというお話のところで、私のもう一度確認したいところなんですけれども。取り壊しをしないでほしいという人たちの思いというのは、今お話し申し上げました。区民の中にもいろいろな意見があるし。そういう点では、例えば、しばらく猶予してほしいという意見だって、ある面では区としても言えるのではないかというふうに思ったわけです。そういうことで、その根拠のところで聞いたわけです。","respondent":"中尾根企画部長","answer":"ただし、先ほども言っているように、いつまた状況が変化してもそのことにこだわるんだと言ったら、これはもともとの本質的な問題のところにかかわりますので、国が所有しているものを、国が方針を変えるということについては、当然ながら。","voiceIndex":41,"id":"exchange-018"},{"speaker":"土井委員","kind":"質問","question":"あれは文化庁に問い合わせをしたら、担当官がそう言ってたよというのが、改めて文書で大分たってから出されているわけですね。同じように、あれは文化財的価値がないんだと最初から決めつけられていたお話ではないと思うんです。ただ、それの調査をするすべがありませんと言うのは正しいとは思うけれども、そこら辺はまだちょっと置いといていただかないといけないんじゃないですかと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-019"},{"speaker":"林（宏）委員","kind":"意見","question":"そのほうが、何万という署名をくださった方々に全部伝わらないわけですよね。この中の雰囲気がね。だから、それを生かすような方法を委員長から請願者の人たちにお話しをして、お考えが実現する方法を伝えるのが、この委員会の取り扱いとしてはベストとは言えないけどベターじゃないのかなと思いますから、継続という形をとって、委員長にその辺のお計らいをしていただくということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-020"},{"speaker":"塚本委員","kind":"質問・要望","question":"結論から言うと、継続の扱いにしていただきたいと思います。それを踏まえますと、議会としては、中身の議論を十分に尽くしており、我々がどういうことを考え、どこに問題があるのかということは、議論の中で明らかになってきていると思いますので、これをつぶさにお伝え願い、この請願そのものの思いを十分にくみ取ってよということで、表現等からこれは継続のままにしておくべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-021"},{"speaker":"藤田委員","kind":"意見","question":"今日の現段階で、国の推移を見ていくということで、今日は継続ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問","question":"２ページの上から２番目、市町村民税の法人税がプラスになっているんだけど、まあ、わずかなんだけど。それからもう一点は、最後の一つ手前の、財調のいわゆる清掃関係で、１７年度末、まだはっきりわかっていないけれども、相当債務が残るじゃないですか。そういうことについて、財調というか都と区の中で１８年度以降どういうふうに見ていくのか。建前論じゃなくて現実としてそのお金をどうするのかと。","respondent":"市岡企画財政課長","answer":"２点目も大変重要な問題でして、正直言って、清掃の今後のあり方と密接につながる今年度の負担なんですが、こういう問題こそ毎年の協議の中ではいつも時間切れではっきりしなくなるので、別途検討会を設けて、この検討会については。","voiceIndex":56,"id":"exchange-023"},{"speaker":"林（宏）委員","kind":"意見","question":"特別区協議会もこれについて、担当の課長なのかどういう役職だかわかりませんけど人がつくという話を聞いていますので、そういうところも含めて、これこそ２３区全体できちんと方向づけるべきだと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-024"},{"speaker":"桜井委員","kind":"質問","question":"今、お話のあった普通交付金の関係で、7,６３４億1,８００万円ということなんですけれども、これがマイナス１.９％ということで、区への影響というんですかね。それから、新規の改正ということで、プラス面として出されているのがあるんですけれども、逆に、こういうところはちょっと違うよとかマイナスとかいうのはないんでしょうか。その２点です。","respondent":"市岡企画財政課長","answer":"財源が落ちていますから、委員ご指摘のとおり見直すものがたくさんありまして。それから、雨水流出抑制事業の経費、これが４分の３ぐらいに縮減されております。そういうふうに見直し項目の細かいところでいろいろやって、マイナスの財源に対応しています。","voiceIndex":59,"id":"exchange-025"},{"speaker":"土井委員","kind":"質問","question":"それは、さらにひっくり返せば、これ以上東京で工場等をつくったときに国庫負担等が受けられない可能性を秘めているということになれば、財調というか一部事務組合の予算の中で、大きく需要額として工場土地の代金がのちのちに影響してくるということになるわけですから、その辺のほうはどのようになっているのか、かつまた清掃事業の根本のところを決めるための方針転換というか。","respondent":"濱野助役","answer":"３区の清掃工場の問題です。区長会等でも、３区からは用地買収について早急に買収に入ってくれというような要求も出ております。一部事務組合は、これは一部事務組合自体で決められない問題だから区長会で決めてほしいということで区長会がつけられた。","voiceIndex":61,"id":"exchange-026"},{"speaker":"土井委員","kind":"意見","question":"わかりました。問題はそのときの流れと方向なんですけれども、先ほどちょっと言いましたように、これからの財源負担等々を考えると、国から補助金も出ない、ブロック処理というのがきちっと決まらないと大変な事態になりかねないということになりますので、若干議論の方向みたいなものがありましたら聞かせてください。","respondent":"濱野助役","answer":"ただし、じゃあ、現実に今ごみ量が減っている中で、新たに巨額な投資をして清掃工場を建てる必要があるかという現実の問題から見れば、やはり現実的な答えは明らかだろうということ。","voiceIndex":63,"id":"exchange-027"}]},{"id":"topic-02","title":"２の第二次総合実施計画の策定","agenda":"２の第二次総合実施計画の策定","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"２ページの表２－２、そこの３番目の、一人ひとりの住みよさを高める品川プランが、さっき説明で終わった、いろいろりんかい線だ何だというのがあれしてきたと言うんだけど、ちょっとこれ極端過ぎませんか。何か意味があるの。7,８００、４、３と来ている数字。","respondent":"小野（孝）政策担当課長","answer":"こちらにつきましては、住宅の建設という形で。","voiceIndex":69,"id":"exchange-028"},{"speaker":"林（宏）委員","kind":"意見","question":"これで行くと１６年度の予算どうなっちゃうの、予算編成。","respondent":"中尾根企画部長","answer":"これは平成１５年度のローリングの中で、はっきり計画できるものについての今の計画の部分を計上しました。","voiceIndex":73,"id":"exchange-029"},{"speaker":"林（宏）委員","kind":"意見","question":"僕はこういう出し方は非常に無責任だと思う。すべて計画なんだから。新規も入ってきましたよと出しているわけ。こんな極端な数字のあらわし方で予算をつくっていくというのが信じられない。今の段階でとおっしゃるなら、ほかのところの数字も今の段階でというのが当てはまると思う。だって、数字から行くと２０００分の１だよ。極端過ぎるという。","respondent":"濱野助役","answer":"つまり、それの４分の１。つまり、これ自体は新規事業を打っていく計画ということでありますので、新規事業は、例えば、定住の策としては、平成１５年度に７８億円の新規投資をします。新規投資は１６年度以降今のところ予定はありません。","voiceIndex":75,"id":"exchange-030"},{"speaker":"塚本委員","kind":"質問","question":"ダイジェスト版のほうで、五つの都市像と七つの品川プランということで、タイトルとり方が抽象的だということがありますけれども、七つのプランとの関係なんですけれども、この図を見ているといかにもマトリックスになっていて、縦横関係があるというふうになっているのか。個々の事務事業はここに書いているんだよというふうになっているのかどうかをまずお聞きします。","respondent":"小野（孝）政策担当課長","answer":"五つの都市像と七つのプランですけれども、あの中を見ていただいても、この施策の中での体系というのはそれぞれの課題を実施したという、いろいろな施策の体系の事業があります。","voiceIndex":77,"id":"exchange-031"},{"speaker":"塚本委員","kind":"質問","question":"そういうことだろうと思うんですけど、どこまで小分けしてポジションをつくっているかということはどういう形ですか。","respondent":"小野（孝）政策担当課長","answer":"例えば、その一番上のまちづくりの活動への支援ということになりますと、７番目の課題で行くと、区民と共に歩む品川プラン、これは区民のまちづくりへの自主的な活動への支援という形になりますからそういうふうに分けます。","voiceIndex":79,"id":"exchange-032"},{"speaker":"塚本委員","kind":"意見","question":"というと、ナンバリングをしようと思えば縦の１、活力にあふれた個性あるまち、横の７、区民との協働、そういうのがあるかどうかは別として、そういうくくりができてくるということですね。それですべてがここへ入ってしまうという。","respondent":"小野（孝）政策担当課長","answer":"そういう形で整理をさせていただきました。すべての事業をそれぞれの施策でもって七つのプランの中に。","voiceIndex":81,"id":"exchange-033"},{"speaker":"土井委員","kind":"意見","question":"この表を見ますと、例えば、定住化の促進というのが三つ目に出てくるわけです。だけど、これは予算化をしてあるところの、予算のことで書いてあるのはここよというところがどこかにあるはずなんです。だから、そこだけが太い字で、ほかは関連項目ですよというふうになっていれば、ちょっと見やすいなと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":83,"id":"exchange-034"},{"speaker":"桜井委員","kind":"質問","question":"考え方だけ聞いておきたいんですけれども、今回の第三次の長期計画には、第二次について新規が１４というふうにして、見直しが７、全体的に七つの新たなというお話がありましたね。その特徴点というんでしょうか、そこをちょっと総論的に聞きたいんです。","respondent":"小野（孝）政策担当課長","answer":"これは七つのプランのところの２ページの表を見ていただくと、ここにずっと金額の流れが出ておりますけれども、やはり大きなものとしては、子育ての楽しさを広げる品川プラン、安心・安全を高める品川プラン、活力と魅力を創造する品川プラン。","voiceIndex":84,"id":"exchange-035"},{"speaker":"桜井委員","kind":"質問・要望","question":"詳しくは予算委員会もありますしね、ちょっと項目だけ説明されてもよくわからないんですけれども。例えば、子育ての楽しさを広げる品川プランの中で、さっき認証保育というお話がありましたよね。イメージ的には、そうした認証保育をここでは突き出していくとか、例えば、事例としてそういうイメージを教えていただきたいなと思ったんですけれども。もう少し内容をいただけますか。","respondent":"小野（孝）政策担当課長、中尾根企画部長","answer":"ここの中で、計画を抜粋して載せてあります。黄色い部分です。子育ての部分の中では、幼保一元化の推進、これが新規ですけれども。それから、小中一貫校の設置、こういうものが中心になっております。特に、さっきマトリックスとありましたけれども、この七つのプラン、これを意識的に打ち出してあるということなので、見開きの、今言いましたように、プランごとに、流れに沿って区が何をしていくか。","voiceIndex":86,"id":"exchange-036"},{"speaker":"桜井委員","kind":"質問","question":"ちょっと記憶にあるんですけれども、前にごみの圧縮というんでしょうか、１個5,０００万円だかかなりの金額で買いましたよね。ここに書いてある(1)から(8)までの定期補修になる。そうすると、随意契約というお話があったんですけれども、随意契約なんていうのは、一定程度、品物がある限りと言うと変ですけれども、ずうっとその会社にやっていくというふうになっちゃうんでしょうか。","respondent":"西島経理課長","answer":"この前購入したのはコンテナの購入です。今回はそのコンテナで圧縮するための設備の定期補修工事です。これは新明和工業の特許が通ってございまして、ここでしかつくってございませんので、設備を設置してしまいますとここで発注することしかできない。","voiceIndex":93,"id":"exchange-037"},{"speaker":"林（宏）委員","kind":"質問","question":"だから、これは東京都の時代に設置されているからどうこう言ってもしようがないんだけど、これを設置するときに、２５年間なり３０年間、この定期清掃ってやらざるを得ないわけ。半端な金じゃない、１万、２万円じゃないんで、億の金がかかるわけ。工事期間中のいわゆるごみ処理はどういうふうにするのかを聞いておきたいのと、今言われた、コンテナ２９台というのは、古いやつですか新しいやつですか。","respondent":"片田施設担当課長","answer":"それと、あともう一つの、８点目のコンテナ設備２９台、これは、昨年と一昨年に５０台ずつ新しいコンテナを購入しています。トータルでこの施設については１２９台のコンテナが設置していますけれども、その大半を前回、１００台ということで、過去２年で取りかえてあります。","voiceIndex":95,"id":"exchange-038"},{"speaker":"林（宏）委員","kind":"質問","question":"順次１台ずつということなんだけど、だから２カ月かかるということなんだろうけど。それから、コンテナは１００台にしちゃうと言ってたのに１２９台のまま使っているんですか。これも清掃のほうの委員会になるのかな。わかる範囲で聞かせてください。","respondent":"片田施設担当課長","answer":"なおかつコンテナ１台の中に７台か８台分ぐらい入りますので、それで一応、１日２往復から３往復ぐらいの中で、トータル１１２台ぐらいの格好になっていますので、もしそれが１週間とかそういうことでできるとすれば、そういうことでやり方もあると思うんですけれども。","voiceIndex":97,"id":"exchange-039"},{"speaker":"塚本委員","kind":"質問","question":"どうしても随契になってしまうということ。設備の量もかなりありますし、この種のことができる会社も五、六社、どのくらいあるんですかね、あると思うんです。特許という大きな壁はあるでしょうけれども、やはりこのままで行くと売り手商品のままで行ってしまうということはわかり切っているわけですから、いろんな工夫が必要なのではないかと思うんですけど、いかがですか。","respondent":"西島経理課長","answer":"引き続き、もう一度見直しをしまして、できるだけ経費をかけないように取り組んでまいりたいと考えております。","voiceIndex":105,"id":"exchange-040"},{"speaker":"塚本委員","kind":"質問・要望","question":"今回のあれは業者が少ないということですけれども、炉のほう、本体のほうになるともっと増えてくると思いますし、共通の部分というのはあると思うんですね。特許の部分というのはごく限られたところだろうと思うので、そういうことも含めて他社との競合性というものを求めていかないと、値段は下がってこないんじゃないかということを言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1612#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":38676,"voices":119}},{"id":"h15-20030305-13","meetingId":"h15-cm03","date":"2003年3月5日","dateIso":"2003-03-05","committee":"清掃・リサイクル特別委員会","time":"午前１０時０５分～午後０時４２分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"１の事業用大規模建築物へのごみ減量・リサイクルの対応","agenda":"１の事業用大規模建築物へのごみ減量・リサイクルの対応","exchanges":[{"speaker":"川西委員","kind":"質問・要望","question":"今の件ですけれども、廃棄物の管理者講習会の参加者、実績で教えてください。しかし、この資料は大変いい資料だと思うんですね。ですから、実績を伺ってからでもいいんですけれども、もう少し小さい規模の事業者に対して、年に１回ぐらい講習会なり、こういう事業目的に沿った説明会なり行っていただきたいというふうに思っています。ですから、そういったような種類のもので、例えば２００m2ぐらいのもの。","respondent":"中山清掃リサイクル課長","answer":"ちなみに、今の事業者の講習会をやる際にはそれぐらいのご参加なんですが、そのほかに、区の中でも3,０００m2以上の事業者、これは条例ですから、かかっておりまして、これは学校も3,０００m2以上で、人事異動があって、具体的に言うと教頭先生なんかが変わった際には。","voiceIndex":5,"id":"exchange-001"},{"speaker":"川西委員","kind":"質問・要望","question":"前向きな姿勢には感謝します。少しだけつけ添えておきますが、例えば消防法の中で、ビル全体の消防計画など、それから訓練の指導をやっていますけれども、そのほかに、借り主ごとの指導、計画を出させて指導・管理、それから実績報告をさせているというのは、将来にわたって、やはり時の問題ですから、これからの、この事業の始まりですから、ぜひ今後お考えいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"全部網羅しているのか、そうでないのかを、ちょっと一つ伺いたいんですが。ですから、やはりここのところの指導というのは、再利用率を改めてこうやって見て、どういうふうにされているのか、この報告書との関係での指導、その後の指導がどういうふうになっているのか。","respondent":"中山清掃リサイクル課長","answer":"これは、期限に提出されなかった場合には、やはり、これは条例に定めているものですから、本来１００％であるべきということで、事務所のほうでも督促といいますか、お願いをして、書き方がわからないという場合は説明しながら。","voiceIndex":8,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"だから、やっぱり厨芥類のリサイクルのシステムが、本当に本格的に取り組んでいく必要があるんじゃないかなというふうに、改めて思うんです。したがって、そこの点についても再質問はしませんけれども、ぜひシステムに乗せていただけるように、こういうところが、逆に言えばやりやすいというところはありますので、よろしくお願いしたいということをちょっとつけ加えさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"「改善勧告、公表、受入拒否などの措置を取ることもあります」という文章があるんですけれども、例えばこういうのに当たるような、ひどいというか、状況に当たったところがあったかどうか、お知らせいただきたいのと、あと、表の後ろのページのところの１４のところのその他がありますよね、再利用物の中でのその他。下にその他のその他があるんで、再利用ができるその他というのが何なのか。","respondent":"中山清掃リサイクル課長","answer":"例えば保管場所の設置についても、実際の中で、これは建築課と連携をとりながらやっておりまして、それに従わない例というのは、実際やりとりをかなりするケースがありますけれども、そこまでは至っておりません。","voiceIndex":11,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この書類の提出率がかなりいいということと、悪質な部分がないということでは、本当に、今後機能していくことで期待が大きいなと。半分以上が事業系ごみということでは、この辺のご指導によって、さらにごみの減量をしていくということで、またリサイクルも進むということで、大変結構です。特にこの再利用のパーセンテージが低いところに対して強力にご指導していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう観点でちょっとお伺いしたいんですけれども、例えば事業態ごとに、どうしてもこういうばらつきが出てしまうというのはあるんですが、例えば同じオフィスビルの方で、行政側としての目標値、平均がこういう形で出ますけれども、平均を目標とするのかどうかわからないですが、このフィードバックしていただいたものと、ご自身のデータと比較して、まだまだ足りないとか。","respondent":"中山清掃リサイクル課長","answer":"この努力に伴うのが経費の削減につながったかどうかというのは、残念ながらこの表は量としての把握はしておりますけれども、コスト面の報告まではいただくようになっておりませんし、なかなかそこまで、仮にお出しいただいたときに。","voiceIndex":14,"id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"まあ、全体としてこれだけの、非常に貴重なデータだと思いますので、これは行政の皆様のいろいろな対策のデータとしてもちろん活用いただくわけですが、実際出された方々にもぜひフィードバックいただいて、次の減量に結びつくように情報提供というか、活用いただきたいと思いますので、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-008"},{"speaker":"上山委員","kind":"意見","question":"今、各論的なところもあるので、ちょっと総論的なところを最初に幾つかお尋ねしたいことがあるんですけれども、私も議員になりたてのときは、たしか自治制度特別委員会か何かのときに、この条例か何か審査したような記憶も今よみがえってきたんですけれども、そのとき、大規模のこういう問題も出されていて、その後条例も品川区として施行されていて。","respondent":"中山清掃リサイクル課長","answer":"それで、そういう意味ではデータの把握も、より集計しやすく、それから、当時２３区の中でやはり移管になって、それぞれの区で書式を決めてということでやったんですが、品川区の水準がどの程度なのかということも、把握をきちんとするということで。","voiceIndex":17,"id":"exchange-009"},{"speaker":"上山委員","kind":"質問・要望","question":"こちらの、これのパンフレット２ページのところでは、例えばですけれども、２３区のごみ量が３５２万トンで、その半分が大体事業所活動により発生しているとここに書いてあります。これはちょっと要望なんで、そう思ったんです。こんなに努力してもなかなか、いろいろ難しいんだなということを実感したわけですけれども、そこはちょっと、これは最後に要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-010"},{"speaker":"嶋委員","kind":"質問","question":"この１番の表のほうなんですけれども、駅舎等とか入っているんですが、ちょっとこれで、私鉄、ＪＲ入っていると思うんですが、ちょっとどのような駅が入っているかお聞きしたいことと、それから、４番の事業所用のビデオの貸し出しというのがあるんですが、これは活用が、今どのようにされていらっしゃるのか、またその成果と申しますか、そういう意味では、今ＩＳＯ１４００1を取ったりとかして。","respondent":"中山清掃リサイクル課長","answer":"それなりのホームの数、大きさを考えますと。それから、事業所用ビデオですけれども、直近の数字はないんです。現在まで、今年度で１０件前後の貸し出しだというふうに認識しております。","voiceIndex":20,"id":"exchange-011"},{"speaker":"嶋委員","kind":"意見","question":"きょうのご報告は大規模建築物ということなんですが、いろいろな飲食店という形の部分、飲食店でも個人じゃなくて、ある程度大規模店の飲食店なんかも、そこで食べて、外で食べてそのまま、よくコンビニなんかは本当に店員さんが回りをお掃除をされているとか、いろいろなごみの回収を気を配っているところがあるんですが、ちょっと私がさっき訪ねたところも、そういう、食べる場所の。","respondent":"中山清掃リサイクル課長","answer":"申しわけありません、ちょっと答弁がもれておりまして、具体的な貸し出しの場所等で、品川・荏原両清掃事務所と清掃リサイクル課のほうで貸し出しを行っておるところです。広報については充実を、よりいろいろな工夫をして図っていきたいと考えています。","voiceIndex":22,"id":"exchange-012"},{"speaker":"石田副委員長","kind":"質問","question":"私から何点かちょっと。それは、変な話、各事業部にまたがる話だと思いますが、そこら辺の点をどうお考えなのか、まずそこら辺の基本的なところをお聞きしたい。","respondent":"中山清掃リサイクル課長","answer":"例えば、建設リサイクル法というのもできましたけれども、あれは解体された建物等の建設廃材のリサイクルとなると、例えば業種として建設業があっても、ここで出てくるのは3,０００m2以上の事業所としての把握ですから、そういう、事業者が対外的に行っている業務の分析は。","voiceIndex":24,"id":"exchange-013"},{"speaker":"石田副委員長","kind":"質問・要望","question":"中に入っていきますと、ちょっとこれ、具体的なことでよくわからないので教えていただきたいのは、発生抑制の工夫というところで、さまざまな納入業者等に引き取りをお願いしていくということがあるわけですが、これ、現実問題、これぐらいの大規模な業態でやっていらっしゃるところは、すべてそうしていると思うんですが、こうなってきたときに、この。","respondent":"中山清掃リサイクル課長","answer":"区外の業者が持ち帰れば、区外のデータの中に出てくるという形で、そこの事業者の中で処理も廃棄もリサイクルもされないものについて、持ち帰りのものはゼロになります。","voiceIndex":26,"id":"exchange-014"},{"speaker":"石田副委員長","kind":"意見","question":"それはびん商がどういうふうにしてるか、例えばその先がどういうふうにしているか、それを防ぐためにマニフェスト伝票をやりましょうというのが主眼なわけだから、そうすると、最終処分場なり、カレット工場なり、そういうところへ行ったという伝票処理を、これは素直に読むと、しなさいと書いてあるんだけれども、さっき言った第一ステップでは、発生抑制で、ここでいうゼロにしなさいというのは。","respondent":"中山清掃リサイクル課長","answer":"確かに、解決していないある種の課題というものはあろうかと思いますが、その辺はひとつ、ごみ減量の数字の中で努力を、それぞれがやっていく中で、いろいろな、先ほどの軽量化、簡素化、簡易包装というような努力も含めて出てくるのかなというふうに思っておりますので。","voiceIndex":28,"id":"exchange-015"},{"speaker":"石田副委員長","kind":"質問・要望","question":"私も民を圧迫させるつもりもないし、大変な作業になるというのは、なるべく簡素化したほうがいいと思いますが、一面そういうところの、例えばその出入り事業者の方の把握をこちらでしておくとか、そういうところの、先ほどの指導の中でやっていくことぐらいは、まあゼロでなかったとしても、現実的に総量は出ているわけで、そうすると、例えば、それはどこが引き取ったんですかとか。","respondent":"中山清掃リサイクル課長","answer":"ただ、いろいろそういう、新たに区としてＩＳＯも一つの切り口とした先進的な、あるいは計画的な取り組みを把握できる仕組みというか、情報が徐々にできつつありますので、連携は図っていきたいというふうに心がけてまいりたいと考えています。","voiceIndex":30,"id":"exchange-016"},{"speaker":"辻委員","kind":"質問・要望","question":"この内訳が欲しいんです。ですから、それは講習のときにきちんとやると、それから結果の使い方というか、それをぜひ今後、やっていただきたいと思います。事業者であればそのままいける。そうなってきたときに、その出方とか、そういうふうなものによっては、今言われているように、リチウム電池ですか、要するに充電できる電池というものに対して力を入れていく。これに対してどのように考えられているか。","respondent":"中山清掃リサイクル課長","answer":"逆に言えば、区側もこういう法の動き等をきちんと把握して、個別に、例えば立ち入りする職員が現実にその事業体に即した情報を持ってアドバイスできるようにしておくとか、そういうことも、これは重要な課題かと考えていますので、そういう法なり。","voiceIndex":32,"id":"exchange-017"},{"speaker":"辻委員","kind":"意見","question":"だから、その積み重ねが、現場の声を生かしながら、どうしたら有効なものになるかというのは、講習会、新しい人だけじゃなくて、再度の講習会、あるいは再々度、ベテランの人たちの講習会なり、意見を聞く場を、聞いて、どういう形で、このままやるなり、あるいは変えていったほうがいいよというような、この辺もぜひやっていただければと思います。","respondent":"中山清掃リサイクル課長","answer":"総量としては、大体処理量と会うようになってくるという形になっておりますので、いずれにしても、ご指摘のように、精度を高めて単にいい加減に書いて活用できないような形にしないような助言、あるいは講習の指導等はやっていきたいと考えています。","voiceIndex":34,"id":"exchange-018"}]},{"id":"topic-02","title":"第二期廃棄物減量等推進員の委嘱","agenda":"第二期廃棄物減量等推進員の委嘱","exchanges":[{"speaker":"川西委員","kind":"質問・要望","question":"４００何名の方かが１２年度とだぶっているかどうかを知りたいと思います。でも、１年間を振り返っての経過報告の中にちっとも出てこないので。大変、私、勉強になって、東京都の職員の発言されていたことがいまだに印象に強く残っていまして、いわゆる最終処分場の今後について、もう少し一般の方も知っていただきたいなと思いますので、計画の中にどこかで入れるように、活動計画、よろしく。","respondent":"中山清掃リサイクル課長","answer":"第一期、第二期の継続の方が約６割強という状況です。","voiceIndex":41,"id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"同じような、関連する質問なんですけれども、去年のその開催状況と比較してみると、去年は１月に委嘱して、地区連絡会が１１月で、大分長期に間があいて、その間もちろん活動されていたんですけれども、間があいていましたけれども、今回は７月に地区連絡会と早めて、全体の研修会というのになってきているんですけれども、最初から１００％のあれを持ってスタートできない状況で、改善されていくというのは。","respondent":"中山清掃リサイクル課長","answer":"委嘱式も全員に対して一堂に会していただいてご説明して、その際にも荏原文化センター大講堂を使って説明したんですが、委嘱状をもらって以降、先ほど申し上げた、いろいろな集積場の問題といっても、地域事情があったり、より地区ごとに話をしたいというお声が寄せられる中で。","voiceIndex":43,"id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱり、繰り返して進めていく中で、よりいいものにつくり上げていくという立場でやっていければいいことであって、あえてどうこうというつもりはないんですが、ぜひ実践活動できる方を推薦していただきたいという、そういう趣旨のところで見守っていきたいと思いますし、できたら、この委員会としても、来期はどういうふうになるかわかりませんけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"品川区は、区長も環境問題を重視して取り上げていますし、プレス発表の中にも、区民参加の環境、清掃問題というところでは、区がとても大事にしている事業ということでは、本当に実践のところで住民の皆さんが参加しやすい、そういった面では、この廃棄物減量等推進員の方々に期待するところも多いし、行政は本当にここのところを大事にしていってくださると思っているんですけれども、ひとつは。","respondent":"中山清掃リサイクル課長","answer":"町会・自治会推薦というのは、基本的に地域センター経由でお名前を、町会長推薦でいただくと。その他、広報誌等による公募という形なんですが、純然たる、はがき等での申し込みというのは８人だけでございました。４４３名が町会・自治会推薦なんです。","voiceIndex":46,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この中身的には、大体どこの時期も、いろいろ、全部参加すると６回ぐらいあるみたいなんですけれども、ここのところの活動状況の発表とか、２年間を振り返ってといったところのご意見というか、中身のまとめがどういうふうにされているのかとか、その後の活用、すごい貴重なご意見がいっぱい出ていると思うんですが、この辺の、今後の活用について、お伺いしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"１点目の、幅広くご参加いただくというのは、まさにこちらも思っているとおりでございまして、次回の募集等については、よりＰＲの充実等努めてまいりたいと考えています。","voiceIndex":48,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大体中身もぜひ区民の皆さんに、何らかの形で公開をしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-024"},{"speaker":"横山委員","kind":"質問","question":"これは、消防庁と各自治体というか、出し方がまちまちの指導をしているようで、家庭の主婦の方はどっちを選んでいいかという、大変困っている部分で、委員の中にも主婦の方たくさんいらっしゃるんですけれども、どっちにしているのかと思いますけれども、品川区ではどういう指導をしているかということを、ちょっとお聞きしたいんですけど。","respondent":"中山清掃リサイクル課長","answer":"先ほど申し上げたように、例えば清掃協力会のときから、そのまま継続的に町会長さんだとか、ご加入していた方から、今回は、より地域の中でこういう活動に実践部隊としてご参加いただける方のご推薦をということになりましたので、そういう意味ではより実行性が上がる。","voiceIndex":51,"id":"exchange-025"},{"speaker":"横山委員","kind":"質問","question":"前にも、区政モニターって今でもあるのかな、そういった形で謝礼を出していて、全然参加しない人にも出していたという。これもＮＨＫで、テレビでやっているぐらいですから、全国はそういう、穴をあけないで出してくださいというのは、私は大体しみわたっていると思うんだけれども。ＰＲがもう１回必要じゃないかなと思うんですけれども。","respondent":"中山清掃リサイクル課長","answer":"使い切ると同時に穴はあけないでお出しくださいということで周知をしておりますし、これから出す印刷物、あるいはホームページ等も、それは統一していきたいと考えています。","voiceIndex":53,"id":"exchange-026"},{"speaker":"辻委員","kind":"質問","question":"この次の２年間の中には、各戸収集、個別収集というんですか、そういうものが実際に視野に入ってくると思うんです。そうしたときに、自分がどこで、地域の中でどう、今言ったような排出量が出て、どうなっているんだという、そういうものの考え方、切り口というのが、今後の取り組みの、地区の会議に必要になってくるんです。どうですか、その要綱の、連絡会というのは。","respondent":"中山清掃リサイクル課長","answer":"中には町会長がいらっしゃったりしますけれども、あくまでも、それは一推進員ということで出ていただいているということで、区と清掃事務所とのキャッチボールをするという場面という形で考えておりますので、会長を通じてではなく。","voiceIndex":55,"id":"exchange-027"},{"speaker":"辻委員","kind":"質問・要望","question":"この要綱というのはどういうことになるんですか。役割というのはそういう形で変わってきているのではないですか。これはぜひやっていただきたい。そのために、あそこの、何ですか、清掃作業の人が行くのが大変だったら、じゃ地域で、臨時の、一時集積場所をつくってでもいいからやってみようと言えば、清掃作業の人たちも、よりきちんといくんじゃないですか。その辺どうですか。","respondent":"松本環境清掃事業部長","answer":"今ご意見がありましたように、私どももこの会を、実際に活用できるよりいいものにしていきたい。そして、私どものごみ・清掃事業の充実に努めていきたいと思っていますので、そういう意味では、ご意見を踏まえて、これからさらなる工夫をさせていただきたいと思います。","voiceIndex":57,"id":"exchange-028"},{"speaker":"辻委員","kind":"意見","question":"ぜひ、これはお願いしたい。人の顔が見えていく形の事業です。というのは、集積場所をこういうふうにしとけばよかったという部分ではない形の、今回の、これからの清掃事業のあり方、そのために、具体的なリサイクルを活用していかなきゃいけないという時代の中で、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-029"}]},{"id":"topic-03","title":"続きまして、３清掃車両への小学生絵画ポスター貼付","agenda":"続きまして、３清掃車両への小学生絵画ポスター貼付","exchanges":[{"speaker":"上山委員","kind":"質問","question":"どれぐらいの比率だったのか、ちょっと教えていただければと思ったのと、これはちょっと，きょうのご報告じゃなくて恐縮なんですけれども、何か環境整備云々かんぬんで、液化の天然ガスか何かに車をかえるのに、そのとき一緒にやるようなことでやっていたのか、それとも、それとは関係なく、独自にこれは課で考えられたものなのか、ちょっとそこら辺のかかわり等、関連がもしあればというのを。","respondent":"中山清掃リサイクル課長","answer":"直営の車両と、この民間から雇い上げている車両の割合は、直営１に対して民間のほうが４ということで、１対４というような状況です。","voiceIndex":64,"id":"exchange-030"},{"speaker":"上山委員","kind":"質問","question":"どうしてもというならそれは別ですけれども、委員長としてはどういうふうな判断をされているのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-031"},{"speaker":"上山委員","kind":"質問・要望","question":"一つは明確にあれば。このことが要因として、大きな要因として減ったという自治体が具体的に名前が挙がれば、ご答弁いただきたいと思いますけれども、いかがでしょうか。この有料化を導入したことによって、そのことが要因として明確に、例えば今まで１０だったものが７になったんだと、このことが要因でなったんだということがあれば、教えていただければと思うんですけれども、参考までに。","respondent":"中山清掃リサイクル課長","answer":"全国的には家庭ごみにおいても有料化を進める自治体が、多分半数を超えてきているかなという中では、導入時に減量があったというのは、それぞれの自治体においてデータがあろうかと認識しております。","voiceIndex":70,"id":"exchange-032"},{"speaker":"上山委員","kind":"意見","question":"そういう意味で言えば、いろいろ問題になっていることはわかりますし、論議も全くないとは言いませんけれども、今の不法手段の云々かんぬんはどうかわかりませんけれども、余り記憶にないんですが、皆さんのこの委員会の中で、十分論議されて、これが提言として盛り込むまでには至っていないというふうに、私は思っていますけれども、これは共産党としては、ちょっと乗れませんね、こういうことには。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-033"},{"speaker":"川西委員","kind":"質問","question":"いろいろと細かいのが、すごくいっぱい出てきている、そういうのを最大公約数として出される場合には、別の委員会ではもう少し、最大公約数的な提言というのがあるんじゃないかと。細か過ぎる。私、この間一般質問でした有料化の問題なんか、委員の一人として、提言の中に賛成できません、今は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"ですから、正副のところでおまとめいただいて盛り込んでくださったわけですから、委員長なり副委員長なりが、そういう、当初申し上げたように総論的なところで、一致できるところで出すという考え方でこれに臨んでいただいたのかどうかと、それから、三つなり四つを追加するときに、その辺とのかかわりでどういうふうに検討されたのかを、ちょっと改めて伺いたいなというふうに思っているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-035"},{"speaker":"土井委員長","kind":"意見","question":"若干私のほうからご説明いたします。それから、ごみの有料化の問題は、ここにも記載をしておりますけれども、検討ということ、今お話がありました部分も含めて、検討をするということでは、議論があったところだというふうに思っておりますので、そういうことで「検討されたい」という形の、皆さん総論的に一体になれるほどの形でお示しをしたと、こういうことです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":75,"id":"exchange-036"},{"speaker":"南委員","kind":"確認","question":"これが一応まとめていただいて、きょうの、最終の委員会の中で、じゃどこの部分だったら一致できるとか、どこの部分はちょっと違うんじゃないかという議論を一定時間かけてやって、そしてまとめていくという、きょうの進め方ですけど、ということでもう一回確認させていただいていいんですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-037"},{"speaker":"田中委員","kind":"提案","question":"それがこういう形にまとめられていると思います。下二つは、下から２番目はきょうも議論に出ましたし、また、一番下は委員長がおっしゃられたように、昨今のこういう状況も踏まえて、これも今後の検討課題として提言すべき内容だと判断し、自民党としては委員長に提案させていただいて、この方向でとりまとめていただけたらということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":78,"id":"exchange-038"},{"speaker":"川西委員","kind":"意見","question":"一つは、ほかの面ではいろいろありますけれども、有料化については、今品川区が１５年度以降、１８年度を目途に進めようとしている各戸収集、いろいろ難しい問題あろうかと思いますけれども、これで減量化が促進されるというより、私は少し経緯を見たいというふうな立場です。それをさておいて、提言まで文章でするということは反対します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-039"},{"speaker":"南委員","kind":"質問","question":"私も川西委員の発言はすごく心強いなというふうに思うんですよね。言葉尻をとらえるつもりはないけれども、やっぱり、実態とか経過をちゃんと見て、それで本当に効果があるんだというふうになって、初めて、よそが始めているわけですから、実際有料化の部分は、事業系であろうと、よその自治体であろうと、よそでは始めている。今のこの時期は時期尚早過ぎるというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-040"},{"speaker":"石田副委員長","kind":"質問・要望","question":"私から、ちょっといいですか。正副というところの話をします。正副で以前から話があったものを、すべて一応出していただくような形をとりました。それをまた正副が踏まえて、このようにお出しをしているわけで、いいですか、自民党会派だけからこういう形の意味合いの話がありました。それで、会派からそういう意見があったものを集約して出しているということですから、それだけはご理解ください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"私の要望をとらえていただきまして、こういう文言に変えていただいたんですが、確かに過去、他の自治体の実態を見ながらでもおそくはないのではないかというご意見も出ましたけれども、品川区としては基礎的自治体となりますと、独自性をより発揮していく中では、一つ、他の自治体をまねるのももちろん必要ではありますが、品川区という独自の対応として、主体性を持ってやるべきだろうと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-042"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、有料化というふうになってくると、これを載せちゃうと、なかなか、その辺のレールが敷かれちゃうものだというふうに心配する部分だってなきにしもあらずですから、もっと平場のところでよくたたいて、そして、この委員会でも、それを一つのテーマにしても、そういう時間を持っても十分結構ですけれども、やっぱり、時期尚早じゃないかなというふうに思うし、何よりも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-043"},{"speaker":"田中委員","kind":"質問・要望","question":"載せないことには、テーマに取り上げてもらえるかどうかが、今後この委員会が設置されるかどうかわかりませんので、そういう意味では、次回の申し送りをする上でも、こういうことを今後議論していくテーマの大きな一つであるということだけは、ぜひ載せていただきたい。両論併記という形は、検討しないということの両論なんでしょうか、それはちょっと、両論という意味がよくわからないんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-044"},{"speaker":"本間委員","kind":"意見","question":"書記さんも含めてご苦労されたなというふうに思いますが、基本的な私の受けとめ方としては、大きな１番から大きな２番に分けられておりますが、特に６番、その他の部分ですね、ここの部分に皆さんの波長といいますか、違いが出てきていると思いますが、私は、先ほど田中委員のほうからもお話がございましたように、同種の意見なんですが、清掃事業が平成１２年に品川区に移管されてから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"リサイクルを進めるというところにおいては、私は、今この間論議した中で、区民の皆さんがどれだけごみを減らそうという論議のところに行くのかというところが大事であって、他都市の場合も、やはり住民の意識の啓発がまず第一だということで取り組んでいて、減量につながっているところが多いので、上げれば減量になるというような方向に行くような、この今回の一行はとても承服できないので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-046"},{"speaker":"川西委員","kind":"質問","question":"私、まだ１週間もたっていないですよ、ごみ有料化について区はどういうふうに考えているんだという一般質問をして、口の息の乾かないうちにこれに賛成できないですよ。私、もし当選したら、あと４年間はごみで議員活動をやろうというくらいの意欲なんですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-047"},{"speaker":"辻委員","kind":"質問","question":"それで、全体的な流れを聞いていると、６以外はほぼオーケーということですから、先ほど本間委員の話がありましたけれども、６の「その他」を削ってしまう。取るというだけではなく、取られてどうなのかという検討もしようと。要するに、反対意見がありましたなんていう提言をするわけにいかないですから。それについて反対意見もございましたと、でもそのテーマはどうなんですかという部分の問題。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-048"},{"speaker":"南委員","kind":"質問","question":"ごみの減量をさせていくのに、区民の意識啓発を図っていくためにどういうふうにしたらいいのかというところでの提言ですから、だから有料化によってごみの減量が本当に図られているのか、そういう点で、やっぱりこの問題をとらえた時には、入らない項目じゃないかというふうに思うわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-049"},{"speaker":"横山委員","kind":"質問・要望","question":"これまで行革委員会が議長のほうに、特別委員会のもとでこういった提言をしている過去があるわけですけれども、図書館だとか公園だとか、１年かけてやってきた。ですから、やっぱり、各会派にそういった意見を求められて提出していて、そのもとで、前は検討したんですね。それは辻委員が言うような形のまとめ方で、これまでを踏襲しているのではないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"そこのところで、一致するというところは別に否定するものでないし、うちのほうのそういう主張が、さっき私が言ったように、一致するところでまとまっていただきたいということが、そこだけでまとめるということが受け入れていただけないんであれば、両論併記という形で載せていただく、そういう方向でまとめてもらいたいという、そういうことで。","respondent":"土井委員長","answer":"そういう意味で、若干の文言の訂正等が必要だということであれば、このあと、また正副で話し合いをさせていただいて、若干の文言の訂正等々は行って、議長に提出をしてまいりたいと、このように思います。","voiceIndex":92,"id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"やむを得ないというか、そういうことでいいというふうに思います。ただ、正副のところでおまとめいただいたものを、改めて議長に提出していく前に、この委員会を再開するんですか。〔「いたしません」と呼ぶ者あり〕しない。しないで一任して提出していくという、そういうことで進めていくということですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-052"},{"speaker":"川西委員","kind":"意見","question":"それで、かなり減量というのが効果が上がってくるというふうに、私は踏んでいます。そういう点では、この品川区が進めようとしている現状について推進をしながら、５年、１０年先にこういうことが出てくるならいいんだけれども、今の時点でこれを、文章的にどう柔らかくしても、ちょっと出せないというふうに判断をしています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-053"},{"speaker":"辻委員","kind":"質問・要望","question":"これ、もうまとめないと、時間ですからしようがないんですけど、例えば有料化については、なお慎重に検討したいという意見があったといえば、それを書くんだったら書くでもいいわけですよ。ただ、その中にも、最初のまとめの段階のときに、有料化についてはさまざまな意見が委員の中でも出たから、ごく慎重にやってもらいたいという意見なり要望を、すっと一行入れておけばうまくなるかという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-054"},{"speaker":"川西委員","kind":"意見","question":"ちょっとだけ一言。大変よくわかりました。そういう点で、この行を何とか工夫して文章化したいということで、わかりましたので、私は、各戸収集のことについて目標が三つあって、その中に減量対策というのが大きく一つあるわけです。だから、１５年度各戸収集によって減量化を進めようとしている。品川区でやっていることを評価してもらいたい、私は。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-055"},{"speaker":"辻委員","kind":"質問","question":"有料化どうのこうのではなくて、それをどうするか。それをやることについては、課題には有料化の是非を含めて考えようと。その有料化自身の検討については、これは、ただ単にそういうふうに扱うのではなくて、そういうふうに、区民の意見を聞くなりして慎重にやってもらいたいというのが、委員会として入ればどうですかという意見なんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-056"},{"speaker":"南委員","kind":"質問・要望","question":"それと、一番最後のところの過料については、これは、なんというんでしょうか、検討されたいということではなくて、その不法手段による取得者等の問題について検討というんでしょうか、何とかということで、過料までいくというのはちょっとどうなのかなという気はするんです。ですから、その辺についての表現も考慮していただけるのであれば考慮していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-057"},{"speaker":"上山委員","kind":"質問","question":"そういう声として、やっぱり載せてもらいたいと思うんです。それはできないものでしょうか。そういう議論があったということを、この中に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-058"},{"speaker":"横山委員","kind":"意見","question":"だから、一任すると言っても、その文面を先にちょっと見せていくというぐらいな、それは当然として、特別委員会の総意で、まるきり外に置いてということではないと思いますので、その辺はと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":103,"id":"exchange-059"},{"speaker":"石田副委員長","kind":"意見","question":"本日で、特別委員会が最終日ということであります。土井委員長のもと、副委員長として、皆様とともに清掃・リサイクル特別委員会を行ってまいりました。最後に、今、非常に活発なご意見をいただきながら、提言のとりまとめを、まだこの先、私どもやっていかなくてはならないところですが、皆様の熱い思いを踏まえながら、一生懸命取り組んでいきたいと考えています。１年間、本当にありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":112,"id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5682#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":50772,"voices":114}},{"id":"h15-20030305-16","meetingId":"h15-cm03","date":"2003年3月5日","dateIso":"2003-03-05","committee":"街づくり特別委員会","time":"午前１０時０７分～午前１１時５２分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"意見","question":"１ページ目の説明の中で、日影の測定面の２メートルから６.５メートルということで、これは日影という点からすると、厳しい状況に、日影被害を受けるほうはね、状況になるんですけど、これは近商と準工の二種特別工業を除くという説明があったんですが、面積的にはどれぐらいになるのか。","respondent":"伊佐都市計画課長","answer":"細かい数字の資料がございませんので後ほどお答えしますが、近隣商業につきましては、路線指定がほとんどありますが、準工業についてはかなり面的な部分があります。面積は後ほどお答えします。","voiceIndex":5,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"ちょっと今の説明とはあれなんですけど、１１月２７日にこの委員会で、建築基準法の一部改正の説明があって、そのときに、容積率を迅速に緩和する制度の導入ということが言われていまして、容積率を住居系の建物については指定容積の１.５倍まで容積を緩和をするという基準法の改正の中で変更があったと思うんですが、これが今度の用途地域の指定がえ、あるいは今後の都市計画、都の都市計画の中で。","respondent":"山室住宅指導担当部長","answer":"１１月２７日にご説明しましたのは、総合設計制度の一般施設といいますか、通常の許可ではなくて、一般の建築確認で対応できる仕組みが整ったと。その中で、一定の面積を満たすものについては容積の割り増しは可能になるという仕組みを導入したわけです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"わかりました。１の1)で言っているわけですね。総合設計制度の中で緩めたと、わかりました。それで、さっき言った近商の問題も含めて、今度の用途地域の指定がえで、ダウンゾーニングしたところもあったって、先ほど聞いたんですが、全体として、それぞれの用途地域ごとに面積がどれぐらい広がったのかというのが、ある程度、示せるんでしょうか。","respondent":"伊佐都市計画課長","answer":"平均容積で見ますと、１.３％上がって。現行は今、平均、品川あたりの平均容積が２７６.１％なんですが、これが２７７.４％になるものです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"沢田委員","kind":"意見","question":"用途地域ごとの全体面積がどう移ったのかというのは、今ので間に合わなければ、後でもいただけるとありがたいです。それとあと、さっき言った近隣商業の容積率の緩和については、また……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-004"},{"speaker":"船波委員","kind":"意見","question":"たまたま出ました１ページ目の３番の測定面の高さ、建築基準法、昨年、改正されて、都がいろいろと改正して、こうした規制面、規制、ビルの高さを変えようという理由はふれてありませんが、理由は何かということと、高さが高くなると、どういった変化が生じるのか。","respondent":"伊佐都市計画課長","answer":"先ほどもご説明申し上げましたが、これは第三種高度地区というところの指定の部分について、原則６.５メートルを採用する。この考え方は、第三種高度地区という高度地区が10メートル直でたち上げて、１：１.２５の勾配で切ります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"船波委員","kind":"質問","question":"そうすると、第三種高度地区で許されているものが、３階建てが建てられるようになるということでしょうか。それから、日影についてのことについてあれしますと、例えば近隣商業地域だと、日影規制５の３になっているし、例えば準工業だと、それがどういったものなのか。","respondent":"山室住宅指導担当部長、伊佐都市計画課長","answer":"したがって、この１ページの素案について、検討するというふうに書いてありますのは、私どものほうでも、東京都の考え方を原則的に適用するんではなくて、今までの経緯を踏まえて、慎重に検討していく必要があるんじゃないかと。日影の今回の面積ですが、三種高度地区の面積ですが、三種高度地区全体が４７４ヘクタール、このうち住居系の用途と第二種特別工業地区を除いた今回の変更を検討している部分の面積は２３０ヘクタールです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"船波委員","kind":"質問","question":"そうすると、この細い道路沿いの近隣商業地域で、測定面の４メートルが６.５メートルにかわると、その影響が、すぐ隣り合わさっている第一種住居地域にいくこともあるんじゃないかと思いますけど、その近隣商業地域で、測定面が上がるところとか、近隣商業地域で日影が５の３という決まりがある場合に、その日影が、すぐ隣りの第一種住居に影は落ちるというようなことがあるんじゃないかと思いますけど。","respondent":"山室住宅指導担当部長","answer":"今、船波委員のおっしゃっています例えば裏側の敷地については、４－２.５ということはこの規制を受けます。","voiceIndex":20,"id":"exchange-007"},{"speaker":"船波委員","kind":"意見","question":"じゃ、その隣り合わせているところはわかりましたが、では、この細く伸びてる近商地域の中でも、建て替えるときに今までと、状況が悪化するようなところがあるということで、隣同士の日影をめぐる対立になってしまうと思うんですが、有効利用ということで、こうした測定面ができるってことでしたけど、測定面をあげても、それによって今後、近隣の建築をめぐる対立が起きてしまっては。","respondent":"山室住宅指導担当部長","answer":"その準住宅的な日照確保というのは、基本的には３階以上を確保していったらどうかというのが、端的に言ったこの規制の考え方なわけですね。ですから、そういった考え方で、品川の場合は進めていっていいのかどうかということを我々としても今、検討している最中だと思います。","voiceIndex":22,"id":"exchange-008"},{"speaker":"船波委員","kind":"質問","question":"わかりました。そういうことを行政の側として検討されているのはわかりましたが、今後、この用途地域というのが都市計画を基本として変更したりしていくということですから、きょうの１枚目の３番の測定面の変化についても、その行政の中だけの検討でなくて、地区計画がつくられていくような方向で、議論をするとか、地域の方がそういうプロセスにかかわっていくとか、そういうところはどうですか。","respondent":"山室住宅指導担当部長","answer":"ご意見のとおり、私どものほうも用途地域の説明会、先ほど都市計画課長が申し上げたとおり、5月の連休明けから始めますので、そのときにまでに一定の整理をして、説明会等で当然、具体的なデータも含めて、こういうようなことで考えていますよということで。","voiceIndex":24,"id":"exchange-009"},{"speaker":"沢田委員","kind":"質問・要望","question":"将来にわたって住み続けるという点で、そういうのがいいのか、どうなのかという時代に入ったということと、そうした人を集めて、事業所を集め、高密度のまちをつくったことが、ヒートアイランド現象をもたらして、第２、第３の太陽をつくることに等しいということが、いろんな研究機関から私はやられているんじゃないかって指摘されていることを見ますと、今後、規制緩和については十分慎重な。","respondent":"伊佐都市計画課長","answer":"近隣商業についての考え方については、確かにおっしゃるとおり、近隣商業の中でも、もし住宅というものがあれば、確かに１階、２階の位置については非常に厳しい状況がありますが、やはり近隣商業でいえば、１階、２階はやっぱり商業としての機能が。","voiceIndex":27,"id":"exchange-010"},{"speaker":"沢田委員","kind":"提案","question":"さっき言ったように、今の近隣商業地域が、昔みたいに景気がいい時代と違って、建て替えもままならないお店がたくさんあるし、それから、シャッターを閉めて、商店ではないというのが、ものすごい勢いで進んでいるわけですよね。これはきょう提案になった問題は、どちらかというと小さな問題ですからあれですけど、意見だけ述べて終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-011"},{"speaker":"北野委員","kind":"質問","question":"日影規制のことなんですけれども、４だったら４時間から２.５時間、この間は当たらなくてもいい。それで、これは日影規制というのは区独自で決められることなんでしょうか。何か先ほどのお話だと、品川区のほうはちょっと日影規制が厳しくしているようなことに伺ったんですけど。","respondent":"山室住宅指導担当部長","answer":"今回は、できる限りそれを標準に戻してほしいというのが都の考えですが、我々としては今までの経緯もやはり尊重しながら、都との調整をしていきたいということは考えています。","voiceIndex":31,"id":"exchange-012"},{"speaker":"北野委員","kind":"質問・要望","question":"わかりました。やはり道路が広がって、高くなって広がった分、高くなる場合に、当たった方たちはやっぱりいいと思うんですけど、逆に今までそういう地域になかった方たちは、今までの地域で本当に十分、注意した形で、合意をとっていただきながら行っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"やはり日影の関係なんですけれども、具体的にどういう、さっき１６カ所ですか、ところどころ、第三種高度地区の１６カ所のところで、実際、近隣商業地域及び準工業地域での適用が、６.５メートルの適用をするというふうなところが、具体的にどういうふうなところかということなどをお聞きしたいんですけど、例えば私、中延地域なんですけど、昭和通り商店街とかそういうところも、この対象というふうな。","respondent":"伊佐都市計画課長","answer":"用途地域の総括図では見にくいんですが、この中で薄いピンクの部分が近隣商業、その中で、三種高度、それから日影５時間－３時間と書いてある、この部分が今回の適用を検討している区域となります。","voiceIndex":34,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして業者の側からすると、それは認められていることなのでこうなっていますというふうなことでやられてくるわけですから、それがもっと地域の住民の人たちにとってみれば、今までのお日様、環境を守るというようなことがもっとできにくくなってしまうような状況がつくられることになるわけですから、本当にそういうふうなことはぜひ。","respondent":"山室住宅指導担当部長","answer":"ですから我々としても、説明会で意見を聞く前に、当然のことながら今まで寄せられている意見、それから庁内の調整とかいろいろな状況を踏まえて１つの素案をつくって、その上で説明会では具体的に説明をしていきたいというふうに考えております。","voiceIndex":36,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"建築紛争のところでは、本当にできれば５階建てにしてほしい、それがちょっと進むとせめて８階建てにしてほしい、そういうような感じでだんだん我慢せざるを得ないという状況が強くなっているというのが、実際地域の中にはありますので、今、どこの地域をそういうふうな６.５メートルというようなところでやっていくのかというところは、今検討しているところですので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-016"},{"speaker":"桜井委員","kind":"質問","question":"私は２点お聞きします。１つは、基本的な考え方なんですけれども、ここに「用途地域変更にあたっては、都市機能の更新、都市居住の推進、住環境の保全」と出てきていますね。ちなみにそういった建築紛争の特徴点は、どういうところに、どういう地域に、どういうふうにあらわれているのかを聞きたいんですね。それが１点。きのう総務委員会で、７つのプランということで実施計画を説明されています。","respondent":"浜脇住環境整備課長、小野政策担当課長、伊佐都市計画課長","answer":"今言ったように既存のマンション等と新しくできるマンション等の施設の調和というものが今のところ周辺の環境とか。７つのプランの中に都市機能の更新という問題が含まれていないんじゃないかという桜井委員からの発言ですが、きのうもちょっとご説明いたしましたように。区の方針の中でも活力ある緑豊かな住みよいまちということで、そういう意味でもどれが１番、２番というようなものではないと思います。","voiceIndex":39,"id":"exchange-017"},{"speaker":"桜井委員","kind":"質問・要望","question":"そういうことで、今度の用途地域に当たって、もちろん事業所の方から見れば効率的に土地を使いたいという、その思いは別に否定しませんけれども、やはり多数の区民の皆さんの改善を求めていることというのは、やっぱり日影とかプライバシーとか、あるいはマンション乱立によっての、一定程度快適な環境というふうに私は思うんですね。そういうことで、さっきのプランのほうは大ざっぱに言っただけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-018"},{"speaker":"中島委員","kind":"質問","question":"これはゲートシティのほうは、こちらの明電舎のほうから渡っていく方もこれから先は多くなると思うんですね。それで、そうでなければ今度、明電舎のあたりに違法駐輪で自転車がいっぱいとまっているわけですね。そういったことを考えたときに、将来的には自転車も通れるような計画というのは考えていらっしゃらないんでしょうか。","respondent":"南雲都市開発課長","answer":"ただ、自由通路に関しましては自転車がそのまま通りますと、歩行者に対して危険な面もありますので、現在は自転車を通すことは考えておりませんが、ただ、駅の東と西を結ぶ自転車の通路につきましては、この西口の開発の全体の中で。","voiceIndex":51,"id":"exchange-019"},{"speaker":"沢田委員","kind":"質問","question":"平成１５年１２月開通予定といいますから、一応現在１２月末なんですか。それから着工はいつごろだったのか教えてください。","respondent":"南雲都市開発課長","answer":"平成１５年１２月ということなんですが、まだ具体的に１２月いつかというところまでは確定していません。今鉄道が通っているところの工事ですので、確定する段階までは至っておりませんが、遅くとも１２月末までには……。その工事に着工しましたのが、平成１２年の３月です。","voiceIndex":53,"id":"exchange-020"},{"speaker":"沢田委員","kind":"質問・要望","question":"この赤い部分ができて、大分流れが緩和されたし、非常に便利になったという話です。ちょっと何かの話し合いでＪＲと話し合う場があったら、りんかい線が入ってくる、埼京線が来る、何か一遍にいろいろな電車が入ってきちゃって、お年寄りが入ってどう行ったらいいかと、私も迷っちゃうんですけれども、わかりづらいんですね。それは要望で、機会があったらよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-021"},{"speaker":"沢田委員","kind":"質問","question":"準防火と準耐火と耐火の違いというのが素人なものでよくわからないんですけれども、少し説明を。実際に準耐火ができれば、燃えやすいというのが大分ブレーキがかかるのかという効果なんかがもしわかったら改めて教えてほしいんですが。","respondent":"山室住宅指導担当部長","answer":"ですから、木造住宅の密集地域の整備の対策というのは、ご案内のとおり道路等を整備する、公園を整備するといった基盤を整備するやり方と、それから建物そのものを燃えない、もしくは燃えにくくするといった、地域の特性に応じたいろいろな考え方があろうかと思うんですが。","voiceIndex":65,"id":"exchange-022"},{"speaker":"沢田委員","kind":"質問・要望","question":"それから全体として低所得とは言えないでしょうけれども、なかなか生活が困難な人が混ざっているということになると、果たしてどこまでいけるのかということ。ただ上に上げたことによってそれが可能になるということもあるから、一概になかなか言えないと思うんですけれども、住民の声をよく聞いて、これも進めていただきたいと要望だけしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-023"},{"speaker":"高星副委員長","kind":"意見","question":"簡単に１つだけ聞かせてください。この知事が指定した地域ということを書いてあるわけですが、せんだって東京都の都市計画の中で、品川区で危ないよと指摘された都内の１０番目に入っているところで、中延の一部、二葉の一部ということで、これは区長の施政方針の中で真剣に取り組んでいくということで述べているわけですが、それらとの整合性はどうなっているのか、そこだけ聞きたいんです。","respondent":"山室住宅指導担当部長","answer":"ですから私どものほうとしては、災害危険度調査でランク５、もしくはその周辺に広がるランク４ですか、そういったところが検討していく必要のある対象地域かなというふうに考えています。それと、申しわけありません。","voiceIndex":68,"id":"exchange-024"},{"speaker":"桜井委員","kind":"質問","question":"今まで、なかなか密集地域の改善が進まないというのは、補助金を含めて制度的にもなかなか困難性があったわけです。だからそういう地域を指定する、あるいはもっと促進しようという点からいえば、さらに、例えば特別な融資制度とか、木造密集の改善をする上でも、一定の住宅改修の資金制度があるけれども、それだけにとどまらない、この条例を進めてく上での考え方というのはあるのでしょうか。","respondent":"山室住宅指導担当部長","answer":"それから今、委員もおっしゃっていたように、私ども住宅施策の中でいろいろな助成制度がありますから、そういったものを含めてＰＲといいますか、していくというのが当面の対応だろうというふうに考えております。","voiceIndex":70,"id":"exchange-025"},{"speaker":"桜井委員","kind":"質問・要望","question":"今、視野に入っているということでちょっと安心してますけど、今なかなかやっぱり、確かに建物そのものは、所有権個人だけれども、全体的にまちを守っていくという社会性の面からいうと、やっぱり行政としてもそれなりのことを考えなくてはいけないと思っているんです。だから今の住宅のことも含めて、こうしたまちができるような、そうしたことも積極的にやっていただきたいということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-026"},{"speaker":"須藤副委員長","kind":"意見","question":"１年間、いろいろ皆さんのご尽力をいただきたまして、街づくり特別委員会、いろいろと審議させていただきましてありがとうございました。街づくりの問題は終わることがないと思います。これからまた見直し案についても諮っていくんだろうと思います。審議ができる状況をつくってもらえたらいいなと思っています。よろしくお願いします。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":83,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6250#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":29112,"voices":85}},{"id":"h15-20030306-14","meetingId":"h15-cm03","date":"2003年3月6日","dateIso":"2003-03-06","committee":"行財政改革特別委員会","time":"午前１０時０５分～午後３時３６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"１の請願・陳情審査","agenda":"１の請願・陳情審査","exchanges":[{"speaker":"鶴委員","kind":"質問・要望","question":"本会議でも一般質問でも触れましたけれども、今も委員長がお話しされたように、この案件は継続審査となっておりますね。この事実については、委員長としてはどういうふうにお感じになっていたのでしょうか。議会のルールとしてしかるべき措置をおそらくおとりになったのではないかと思うけれども、何らアクションはあったのか、なかったのか、お聞かせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":3,"id":"exchange-001"},{"speaker":"鶴委員","kind":"質問","question":"「今後第１回定例会までに行財政改革特別委員会の日程はなく、同陳情は４月に区議会議員選挙のため廃案となることが確定した」こう書いてあるんです。こういうことがまかり通っていいことなのかどうか。審査中のものが、事実でないことをあたかも事実であるかごとく書くということについては、議会のルールから見てもいかがなものかというふうに思いますが、いかがでしょうか。","respondent":"福田区議会事務局長","answer":"この委員会のたしか第１回目のときであったというふうに覚えておりますが、当議会にとりましては、陳情も請願も事実上同じ取り扱い。つまり、請願は憲法上の権利である、それと事実上同じだというふうに申し上げました。","voiceIndex":7,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"今、私どものホームページのことについて出されましたので、申し述べておきます。これまでの審議の経過等含めて、私どもの見解を述べたという形でホームページに掲載をしています。この陳情者自身が品川新聞の中で、前々回でしょうか、事実上廃案だというふうに述べておりますし、陳情者自身がそのように品川新聞の中で述べているということだけはお伝えをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鶴委員","kind":"意見","question":"今のことは、見解を述べただけだとおっしゃるけれども、責任を他に転化するやり方はよくないというふうに思うんですね。要するに、請願者のあるいは陳情者の手から既に離れているんです。見解を述べた、何でも見解を述べたら、とんでもないことを、あれは見解だったんですよということで済ませる性格のものであるかという、それぞれが胸に手をあてて考えてみる必要があるのではないかというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、議会の意思の決定は、当該委員会の決定の後、出すべきであって、それから、本会議等の意思の決定の後、しかるべき方法で出すのがいいのかなというふうなことで、感想として今述べします。ですから、まして来月には間違いなく区議会議員選挙が行われる中で、ここで非常に大きな決断をしていくというのは、いろんな意味で品川区議会の責任についてはどうなのかと疑問に感じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-005"},{"speaker":"宮崎副委員長","kind":"確認","question":"ちょっと１点確認しておきたいんですけれども、この今回の陳情は、今度の選挙を４人削減してということで陳情されていますけれども、今、先日、立候補予定者の説明会をやると。事実上、選挙に向かっていろいろな方が活動を始めております。その点が非常に、特に新人の方にとってみると非常に不利になるという意見もあるんですけれども、実際、いつが期限というものはあるんでしょうか。","respondent":"福田区議会事務局長","answer":"事実上、実態上、つまり、いろいろ政治向きなことにつきましては存じません。法的に申し上げますと、第１回定例会最終日の議決におきまして支障はないというふうに認識しております。","voiceIndex":12,"id":"exchange-006"},{"speaker":"宮崎副委員長","kind":"意見","question":"問題なのは、実際上もうこの４２名でずっと動いてきているということなんですね、定数４２名で。やっぱりここは問題だと思うんですね。そういう中で、定数を下げるというのは、新人にとっては非常に狭き門にしている、そういうふうにも言われているんですけれども、そういう見解については存じておりますか、局長。","respondent":"福田区議会事務局長","answer":"存じません。","voiceIndex":14,"id":"exchange-007"},{"speaker":"宮崎副委員長","kind":"質問","question":"だから、これは議論が煮詰まっていないわけですね。だから、実際上、今回の議会での採択は非常に難しいというのが僕らの共産党の見解です。だから、まじめに議論をやろうというんであれば、質問にはちゃんと答えるというのがあってしかるべきだと私は思うんです。大体議会のスリム化による活性化というのが一体どこに実例があるのか、そういうことは前回も前々回も質問しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-008"},{"speaker":"鶴委員","kind":"質問","question":"副委員長としては、大変逸脱した珍論だというふうに思わざるを得ないんですが、要するに、スリム化になるというふうに私は思っているわけです。こと細かなことについては、あえてそういうことまで説明しなきゃならない立場にないですよ、私は。陳情者に聞くべきことです。私の言うスリム化論とあなたが言うスリム化論は違うはずですから。だから、言いたくないんですよ。とんでもないことですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-009"},{"speaker":"宮崎副委員長","kind":"意見","question":"今、鶴委員が外でということであれば、外で大いにやろうと思うんですけれども。私は、それほど言うんであればちゃんと説明してくださいと何回も言っているんですよ。だって、全くスリム化による活性化、じゃあ、あなた自身は見解はあるというんであれば、ちゃんとそれを説明してくださいよ。中心点が全くぼやけて、採択を主張する鶴委員自身も説明されないということだけは、ちょっとはっきり言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-010"},{"speaker":"原委員","kind":"質問","question":"先ほど意見の中で、現役有利・不利の話が出ていますけれども、それもとんでもない話だと思うんですね。そういうふうに言うこと自体がおかしな話で、めちゃくちゃな陳情でも何でもない、ちゃんとした陳情でこういう形を提出されているわけですから。したがいまして、いろいろな意見があると思いますけれども、まとめていただいて、委員長のほうで決断をしていただければというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-011"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"今、ホームページの件でありましたので、ちょっと一言だけ言っておきます。流れの中で、我が党としてはこれが事実上廃案だろう、そういう見解ですので、事実経過としては前回のところで継続になったということで述べておりますので、そこのところは、まだホームページを見たわけじゃないというお話だったので、ぜひそこのところは事実を確認していただければと思います。これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-012"},{"speaker":"堺委員","kind":"質問","question":"今、ホームページのやりとりの中で、党の見解であって、推定のような言い方でしたね、確定ではないような、という話でしたけれども、ここにある２月２日の沢田議員の名前のホームページですかね、これ。これは議会無視というんですか、ちょっとどういう表現を使っていいのかよくわかりませんけれども、これは許せる文章ではないというふうに言わざるを得ないんですね。その辺、委員長どうお考えですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-013"},{"speaker":"堺委員","kind":"質問・要望","question":"党の見解を批判という立場で、賛成という立場で述べようと、それも自由ですから、許される範囲の中でどう述べようとそれは結構ですが、事実と相反することについては慎重に、ホームページですから、いろんな人たちが見るわけです。ですから、今後そういうことのないように、書く場合には慎重に対応していただきたい。こんなことを要望しておきたいと思うんです。理由はまた後ほど述べたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-014"},{"speaker":"金高委員","kind":"意見","question":"新しい構成の中になったときに、またこの問題は当然、ここで論議されておりますから、陳情された方もまた改めて違った角度から出してくるという思いは、この文章からも見受けられますので、そのときに新しいメンバーで４年間、あるいはそんなに時間をかける必要はないと思いますけれども、やはり仕切り直しをした上でもって、しっかりと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"陳情の中身のことについて見解を述べていきたいと思います。ですから、その点で、区議会という一方の役割、これの力を減ずることになりかねないものであるというふうに思っています。もちろん、議会費で経費の節減を図るべきものというのはいろいろあるんだと思います。ですから、この間の論議を踏まえて、私どももこの陳情については継続するという立場で発言をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問・要望","question":"長引かせるつもりはありませんので、簡単にお話します。先ほどのホームページの件は、議会全体の意思のあらわし方になってきますので、しかるべきところで委員長のほうから議論をしていただける場をつくっていただきますように要望をお願いしておきます。それから、先日の総務委員会で参考までに、正田邸のことがこれも継続になりました。そういうふうなことも含めて継続になった経過があります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-017"},{"speaker":"原委員","kind":"質問・要望","question":"１つは、それを伝えるのに、委員会の意思としては伝えられると思うんです。なぜかというと、一応１回切れるわけですから、人員構成も変わるわけですから、それはちょっと難しいけれども、委員会の意思としてそれをちゃんと次に残していく、これはできる話だろうと私は思っていますので、今、伊藤委員が言いましたけれども、そこのところだけはそのように訂正をしていただきたい、このように思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-018"},{"speaker":"堺委員","kind":"質問・要望","question":"」その後いろいろ言われておりますが、結論として、「したがって、品川区議会は現行議員定数４２人から４人削減し、条例定数を３８人に改め」、この時点では今年の４月を想定しておりますが、「区議会議員選挙から施行する品川区議会議員定数条例の速やかな改正を求めるものである。最終本会議が３月２８日です。こういう視点から、この件については今日採択をすべきである。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-019"}]},{"id":"topic-02","title":"続きまして、３の報告事項","agenda":"続きまして、３の報告事項","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"１点だけお聞かせ願いたいんですけれども、平成１３年度の、当初議会に、この委員会に示されたときに、それぞれの所管の課長でしょうかね、評価のところから、次の部長、経営者会議というふうに示されていました。","respondent":"榎本行財政改革担当課長","answer":"今、菊地委員のほうからご質問ありまして、示すことができないというわけではないんですけれども、昨年もこの行財政改革委員会の中で、議論の報告として、途中の経過段階として、そういう評価段階を経て、事務事業評価をまとめているということでご報告させていただきまして。","voiceIndex":45,"id":"exchange-020"},{"speaker":"原委員","kind":"質問・要望","question":"お答えできるかどうかわかりませんけれども、１点だけ確認をさせていただきたいんです。９ページに今回の評価結果が出ていますね。","respondent":"榎本行財政改革担当課長","answer":"職員としてもこういう実際の方向性がはっきり認識できるような形になりますので、順次できるところから見直しを進めていくという形で考えております。","voiceIndex":47,"id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問","question":"例えば、平成１４年度にはこれだけやりたい。ですから、これを評価もちろんいいんですけれども、この将来について、ただ品川区内だけの行政評価をしていくのは、もちろんそれはそれでいいんですけれども、この検討した結果として、行政でやるべきものと、これはどう考えても民間でやらせたほうが安いというような結論が出てくると思われますので、その将来的な構想までもしありましたらお聞かせください。","respondent":"榎本行財政改革担当課長","answer":"なかなかこのコストを表現するときには、委員おっしゃるとおりに、事業費、人件費その他の間接経費等を入れながらあらわしていく形にはしたいところなんですけれども、その辺のシステム的なものも含めまして、また検討を進めていきたいと考えています。","voiceIndex":49,"id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それだけのものを投入しているにもかかわらずこれしか実績が上がっていないということをあらわしているわけですから、もっとパッと見たときに、品川区は立派にやっているという部分と、それから、もう一方、そうじゃない部分が区民にわかりやすいものをこれからつくっていくことが次の目標ではないかと思われますので、ぜひそういう方向で進んでいっていただきますように要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-023"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"１点だけちょっと、要望になろうかと思うんですけれども、聞きたいんですけれども。事業の１つ１つのところで説明がいろいろ書いてあるんですけれども、その事業１つ１つの見直す動機と言いますか、まあ、全体には、事業全体を見直すということが前提になっているんですけれども、その１つ１つの問題意識というのがここからではよく見えないんですね。ちょっと要望になりましたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-024"},{"speaker":"藤田副委員長","kind":"意見","question":"この１年間、委員の皆様、理事者の皆様、そして、書記のご協力をいただきまして、無事終えることになりました。松澤委員長を補佐したかどうかはよくわかりませんけれども、この１年間、現業職員の人的配置の問題等々、中身のある議論ができたものと考えています。この１年間、本当にありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5726#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":23875,"voices":63}}]);
